// ── Daily Mission Definitions ───────────────────────────────────
const BOT_MISSION_DEFS = [
  { id:"play_3",   target:3,    type:"play", reward:500  },
  { id:"win_2",    target:2,    type:"win",  reward:1000 },
  { id:"bet_5000", target:5000, type:"bet",  reward:750  },
];
function missionToday(){ return new Date().toISOString().slice(0,10); }
async function trackMission(userId, type, amount=1){
  try{
    const date = missionToday();
    let doc = await dailyMission.findOne({ userId, date }).catch(()=>null);
    if(!doc){
      const { Schema } = require("mongoose");
      doc = await dailyMission.create({
        userId, date,
        missions: [...BOT_MISSION_DEFS.map(m=>({id:m.id,progress:0,claimed:false})),
                   {id:"login_site",progress:0,claimed:false}]
      }).catch(()=>null);
    }
    if(!doc) return;
    let changed = false;
    for(const def of BOT_MISSION_DEFS){
      if(def.type!==type) continue;
      const prog = doc.missions.find(m=>m.id===def.id);
      if(!prog||prog.progress>=def.target) continue;
      prog.progress = Math.min(def.target, prog.progress + amount);
      changed = true;
    }
    if(changed){ doc.markModified("missions"); await doc.save().catch(()=>{}); }
  }catch(e){ console.error("[trackMission]",e.message); }
}

