// ================================
// Provably Fair system
// ================================
const PF_FILE = path.join(__dirname, "provablyFair.json");

function randomSeedHex() {
  return crypto.randomBytes(32).toString("hex");
}

function hashSeed(seed) {
  return crypto.createHash("sha256").update(seed).digest("hex");
}

function hmacHex(serverSeed, message) {
  return crypto.createHmac("sha256", serverSeed).update(message).digest("hex");
}

function toRoll100(hmac) {
  const slice = hmac.slice(0, 13);
  const intVal = parseInt(slice, 16);
  return ((intVal % 10000) / 100).toFixed(2);
}

function defaultPFState() {
  const serverSeed = randomSeedHex();
  return {
    serverSeed,
    serverSeedHash: hashSeed(serverSeed),
    createdAt: Date.now(),
    history: [],
    users: {},
  };
}

function loadPF() {
  try {
    if (!fs.existsSync(PF_FILE)) {
      const data = defaultPFState();
      fs.writeFileSync(PF_FILE, JSON.stringify(data, null, 2));
      return data;
    }
    const data = JSON.parse(fs.readFileSync(PF_FILE, "utf8"));
    if (
      !data.serverSeed ||
      !data.serverSeedHash ||
      typeof data.users !== "object"
    ) {
      const fresh = defaultPFState();
      fs.writeFileSync(PF_FILE, JSON.stringify(fresh, null, 2));
      return fresh;
    }
    return data;
  } catch {
    const fresh = defaultPFState();
    fs.writeFileSync(PF_FILE, JSON.stringify(fresh, null, 2));
    return fresh;
  }
}

function savePF(data) {
  fs.writeFileSync(PF_FILE, JSON.stringify(data, null, 2));
}

function getOrCreatePFUser(data, userId) {
  if (!data.users[userId]) {
    data.users[userId] = {
      clientSeed: randomSeedHex().slice(0, 16),
      nonce: 0,
    };
  }
  return data.users[userId];
}

const PF_GAME_TRACKER_FILE = path.join(__dirname, "pfGameTracker.json");



function defaultPFGameTracker() {
  return {
    activeByChannel: {},
    sessions: {},
    lastFinalizedAtByChannel: {},
  };
}

function loadPFGameTracker() {
  try {
    if (!fs.existsSync(PF_GAME_TRACKER_FILE)) {
      const fresh = defaultPFGameTracker();
      fs.writeFileSync(PF_GAME_TRACKER_FILE, JSON.stringify(fresh, null, 2));
      return fresh;
    }
    const parsed = JSON.parse(fs.readFileSync(PF_GAME_TRACKER_FILE, "utf8"));
    if (!parsed.activeByChannel || !parsed.sessions) {
      const fresh = defaultPFGameTracker();
      fs.writeFileSync(PF_GAME_TRACKER_FILE, JSON.stringify(fresh, null, 2));
      return fresh;
    }
    if (
      !parsed.lastFinalizedAtByChannel ||
      typeof parsed.lastFinalizedAtByChannel !== "object"
    ) {
      parsed.lastFinalizedAtByChannel = {};
    }
    return parsed;
  } catch {
    const fresh = defaultPFGameTracker();
    fs.writeFileSync(PF_GAME_TRACKER_FILE, JSON.stringify(fresh, null, 2));
    return fresh;
  }
}

function savePFGameTracker(data) {
  fs.writeFileSync(PF_GAME_TRACKER_FILE, JSON.stringify(data, null, 2));
}

function extractBetAmount(content) {
  const parts = content.trim().split(/\s+/);
  if (parts.length < 2) return "unknown";
  const maybeBet = parts[2] || parts[1];
  return maybeBet || "unknown";
}

function extractOpponentIdFromMessage(message) {
  const mention = message.mentions?.users?.first();
  if (mention && mention.id !== message.author.id) return mention.id;
  return null;
}

