function setActivePFGameType(channelId, gameType) {
  const tracker = loadPFGameTracker();
  const queue = tracker.activeByChannel[channelId] || [];
  if (!queue.length) return;
  const sessionId = queue[0];
  const session = tracker.sessions[sessionId];
  if (!session || session.status !== "open") return;
  session.gameType = gameType;
  tracker.sessions[sessionId] = session;
  savePFGameTracker(tracker);
}

function hasMatchingOpenPFSession(tracker, channelId, playerId, opponentId) {
  const queue = tracker.activeByChannel[channelId] || [];
  for (const sid of queue) {
    const s = tracker.sessions[sid];
    if (!s || s.status !== "open") continue;
    if (
      s.playerId === playerId &&
      (s.opponentId || null) === (opponentId || null)
    )
      return true;
  }
  return false;
}



function cancelOpenSessionsForPlayer(tracker, channelId, playerId) {
  const queue = tracker.activeByChannel[channelId] || [];
  const kept = [];
  for (const sid of queue) {
    const s = tracker.sessions[sid];
    if (!s || s.status !== "open") continue;
    if (s.playerId === playerId) {
      s.status = "cancelled";
      s.closedAt = Date.now();
      tracker.sessions[sid] = s;
      continue;
    }
    kept.push(sid);
  }
  tracker.activeByChannel[channelId] = kept;
}

