// متغيرات النظام
let inviteSystemEnabled = false;
const inviteCache = new Map(); // تخزين الدعوات لكل سيرفر

// دالة تحديث ذاكرة الدعوات
async function updateInviteCache(guild) {
  try {
    const invites = await guild.invites.fetch().catch(() => new Map());
    const inviteMap = new Map();
    invites.forEach(inv => {
      inviteMap.set(inv.code, {
        code: inv.code,
        uses: inv.uses || 0,
        inviter: inv.inviter,
        maxUses: inv.maxUses,
        createdAt: inv.createdAt
      });
    });
    inviteCache.set(guild.id, inviteMap);
    console.log(`📋 تحديث ذاكرة الدعوات لسيرفر ${guild.name} - ${inviteMap.size} دعوة`);
    return inviteMap;
  } catch (error) {
    console.error(`خطأ في تحديث ذاكرة الدعوات: ${error.message}`);
    return new Map();
  }
}

