// أمر تفعيل النظام
client.on("messageCreate", async (message) => {
  if (!message.guild) return;
  if (message.author.bot) return;

const args = message.content.trim().split(/\s+/);
const cmd = args[0].toLowerCase();

if (cmd === '!export' || cmd === 'export') {
  // التحقق من أن المستخدم هو المالك
  if (!owners.includes(message.author.id)) {
    return message.reply({ content: "> ❌ هذا الأمر مخصص للمالك فقط!" });
  }

  try {
    await message.channel.send('⏳ **جاري تجميع ملفات المشروع...** يرجى الانتظار...');

    const { exec } = require('child_process');
    const util = require('util');
    const execPromise = util.promisify(exec);

    const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
    const zipFileName = `project-backup-${timestamp}.zip`;
    const zipFilePath = path.join(__dirname, zipFileName);

    // إنشاء ملف ZIP باستخدام أمر النظام
    const excludeDirs = ['node_modules', '.git', 'tmp', 'temp', 'cache', '.cache', 'dist', 'build', '.next', 'coverage', '.vscode', '.idea', 'output'];
    const excludeFiles = ['package-lock.json', 'yarn.lock', '.env', '*.log', 'backup-*.zip', 'project-backup-*.zip', 'Thumbs.db', '.DS_Store'];

    let excludeParams = '';
    excludeDirs.forEach(dir => { excludeParams += ` --exclude="${dir}/*"`; });
    excludeFiles.forEach(file => { excludeParams += ` --exclude="${file}"`; });

    // استخدام zip (Linux/Mac) أو专 لـ Windows
    const command = `zip -r "${zipFilePath}" . ${excludeParams} -x "*.git*" "*.log"`;

    try {
      await execPromise(command);
    } catch (zipError) {
      // إذا فشل zip، جرب بديلاً باستخدام tar
      const tarCommand = `tar -czf "${zipFilePath.replace('.zip', '.tar.gz')}" --exclude="node_modules" --exclude=".git" --exclude="*.log" --exclude=".env" .`;
      await execPromise(tarCommand);
    }

    const stats = fs.statSync(zipFilePath);
    const fileSizeMB = (stats.size / 1024 / 1024).toFixed(2);

    try {
      await message.author.send({
        content: `✅ **تم تصدير المشروع بنجاح!**\n📦 **حجم الملف:** ${fileSizeMB} MB\n📅 **التاريخ:** ${new Date().toLocaleString('ar-EG')}\n\n⚠️ هذا الملف يحتوي على كود المصدر الكامل. يرجى الاحتفاظ به في مكان آمن.`,
        files: [zipFilePath]
      });

      await message.channel.send(`✅ **تم تصدير المشروع!** تم إرسال الملف إليك عبر الرسائل الخاصة.\n📦 الحجم: ${fileSizeMB} MB`);

      setTimeout(() => {
        if (fs.existsSync(zipFilePath)) fs.unlinkSync(zipFilePath);
      }, 5000);

    } catch (dmError) {
      await message.channel.send(`❌ **فشل الإرسال!** يرجى تمكين الرسائل الخاصة (DM).`);
    }

  } catch (error) {
    console.error('Export error:', error);
    await message.channel.send('❌ **حدث خطأ أثناء تصدير المشروع!**');
  }

  return;
}

  // !setinvite - Owner only: Set the invite bonus amount
  if (cmd === "!setinvite") {
    if (!owners.includes(message.author.id)) {
      return message.reply({ content: "> ❌ هذا الأمر مخصص للمالك فقط!" });
    }

    const amount = args[1];
    if (!amount || isNaN(amount)) {
      return message.reply({ 
        content: "> ⚠️ الرجاء إدخال مبلغ صحيح\n> **الاستخدام:** `!setinvite <المبلغ>`" 
      });
    }

    const newAmount = parseInt(amount, 10);
    if (newAmount <= 0) {
      return message.reply({ content: "> ❌ المبلغ يجب أن يكون أكبر من الصفر!" });
    }

    const oldAmount = BALANCE_UPDATE_AMOUNT;
    BALANCE_UPDATE_AMOUNT = newAmount;

    return message.reply({
      embeds: [new MessageEmbed()
        .setColor("#00ff00")
        .setTitle("✅ تم تحديث مبلغ المكافأة")
        .setDescription(
          `> 💰 **المبلغ القديم:** \`${oldAmount.toLocaleString()}\` عملة\n` +
          `> 💰 **المبلغ الجديد:** \`${newAmount.toLocaleString()}\` عملة\n` +
          `> 📝 **تم التحديث بواسطة:** ${message.author}\n` +
          `> ⏰ **الوقت:** <t:${Math.floor(Date.now() / 1000)}:F>`
        )
        .setTimestamp()]
    });
  }

  // Enable the invite system
  if (message.content === "!invon") {
    const isOwner = owners.includes(message.author.id);
    const hasPerm = permStore.canUseCommand(message.author.id, "invon");
    if (!isOwner && !hasPerm) return;
    inviteSystemEnabled = true;
    await updateInviteCache(message.guild);
    return message.reply({
      embeds: [new MessageEmbed()
        .setColor("#00ff00")
        .setTitle("🔔 نظام تتبع الدعوات مفعل")
        .setDescription(
          `> ✅ **تم تفعيل النظام بنجاح!**\n` +
          `> 📊 سيتم تتبع الدعوات الجديدة وإرسال إشعارات إلى <#${NOTIFICATION_CHANNEL_NEW}>\n` +
          `> 💰 المكافأة للمستخدمين الجدد (حساب فوق 3 أشهر): \`${BALANCE_UPDATE_AMOUNT.toLocaleString()}\` عملة`
        )
        .setTimestamp()]
    });
  }

  // Disable the invite system
  if (message.content === "!invoff") {
    const isOwner = owners.includes(message.author.id);
    const hasPerm = permStore.canUseCommand(message.author.id, "invoff");
    if (!isOwner && !hasPerm) return;
    inviteSystemEnabled = false;
    return message.reply({
      embeds: [new MessageEmbed()
        .setColor("#ff0000")
        .setTitle("🔕 نظام تتبع الدعوات معطل")
        .setDescription(`> ❌ **تم تعطيل النظام.** لن يتم تتبع الدعوات الجديدة.`)
        .setTimestamp()]
    });
  }

  // أمر لعرض حالة النظام
  if (message.content === "!invstatus") {
    const isOwner = owners.includes(message.author.id);
    const hasPerm = permStore.canUseCommand(message.author.id, "invstatus");
    if (!isOwner && !hasPerm) return;
    const embed = new MessageEmbed()
      .setColor(inviteSystemEnabled ? "#00ff00" : "#ff0000")
      .setTitle("📊 حالة نظام تتبع الدعوات")
      .setDescription(
        `> **الحالة:** ${inviteSystemEnabled ? "🟢 مفعل" : "🔴 معطل"}\n` +
        `> **قناة الإشعارات:** ${NOTIFICATION_CHANNEL_NEW ? `<#${NOTIFICATION_CHANNEL_NEW}>` : "❌ غير محددة"}\n` +
        `> **مبلغ المكافأة:** \`${BALANCE_UPDATE_AMOUNT.toLocaleString()}\` عملة\n` +
        `> **شرط المكافأة:** حساب عمره 3 أشهر أو أكثر`
      )
      .setTimestamp();
    return message.reply({ embeds: [embed] });
  }

  // أمر تعديل مبلغ المكافأة (للمالك فقط)
  if (cmd === "!setinvite") {
    // التحقق من أن المستخدم هو المالك
    if (!owners.includes(message.author.id)) {
      return message.reply({ content: "> ❌ هذا الأمر مخصص للمالك فقط!" });
    }

    const amountStr = args[1];
    if (!amountStr) {
      return message.reply({ content: "> ❌ استخدام خاطئ!\n> **الاستخدام:** `!setinvite <amount>`\n> مثال: `!setinvite 5000000`" });
    }

    const amount = parseInt(amountStr);
    if (isNaN(amount) || amount <= 0) {
      return message.reply({ content: "> ❌ يرجى إدخال رقم صحيح وموجب!" });
    }

    const oldAmount = BALANCE_UPDATE_AMOUNT;
    BALANCE_UPDATE_AMOUNT = amount;

    const embed = new MessageEmbed()
      .setColor("#00ff00")
      .setTitle("✅ تم تحديث مبلغ المكافأة")
      .setDescription(
        `> **المبلغ القديم:** \`${oldAmount.toLocaleString()}\` عملة\n` +
        `> **المبلغ الجديد:** \`${amount.toLocaleString()}\` عملة\n` +
        `> 📝 **تم التحديث بواسطة:** ${message.author}`
      )
      .setTimestamp();

    return message.reply({ embeds: [embed] });
  }
});

// مراقبة انضمام الأعضاء الجدد
client.on("guildMemberAdd", async (member) => {
  console.log(`👤 عضو جديد: ${member.user.tag} (${member.id})`);

  // Check if user already joined before
  const existingUser = await db.findOne({ id: member.id }).catch(() => null);
  if (existingUser && existingUser.hasJoinedServer) {
    console.log(`⚠️ ${member.user.tag} كان قد انضم من قبل. لن يتم إرسال مكافآت جديدة.`);
    return; // User already joined before, don't send rewards
  }

  // Mark this member as having joined — do this immediately so rejoins are always blocked
  await db.updateOne({ id: member.id }, { $set: { hasJoinedServer: true } }, { upsert: true }).catch(() => {});

  if (!inviteSystemEnabled) {
    console.log("⚠️ نظام تتبع الدعوات معطل");
    return;
  }

  // الحصول على قناة الإشعارات
  const channel = member.guild.channels.cache.get(NOTIFICATION_CHANNEL_NEW);
  if (!channel) {
    console.log(`❌ لم يتم العثور على قناة الإشعارات: ${NOTIFICATION_CHANNEL_NEW}`);
    return;
  }

  try {
    // الحصول على الدعوات القديمة من الذاكرة
    const oldInvites = inviteCache.get(member.guild.id);
    if (!oldInvites) {
      console.log("⚠️ لا توجد بيانات سابقة للدعوات");
      await updateInviteCache(member.guild);
      return;
    }

    // الحصول على الدعوات الجديدة
    const newInvitesMap = await member.guild.invites.fetch().catch(() => new Map());
    const newInvites = new Map();
    newInvitesMap.forEach(inv => {
      newInvites.set(inv.code, {
        code: inv.code,
        uses: inv.uses || 0,
        inviter: inv.inviter
      });
    });

    // البحث عن الدعوة المستخدمة (التي زاد عدد استخداماتها)
    let usedInvite = null;
    let usedInviteCode = null;

    for (const [code, oldData] of oldInvites) {
      const newData = newInvites.get(code);
      if (newData && newData.uses > oldData.uses) {
        usedInvite = newData;
        usedInviteCode = code;
        console.log(`🔍 تم العثور على الدعوة المستخدمة: ${code} (الاستخدامات: ${oldData.uses} → ${newData.uses})`);
        break;
      }
    }

    // Also check for brand-new invites that weren't in the old cache at all
    if (!usedInvite) {
      for (const [code, newData] of newInvites) {
        if (!oldInvites.has(code) && newData.uses > 0 && newData.inviter) {
          usedInvite = newData;
          usedInviteCode = code;
          console.log(`🔍 دعوة جديدة غير مسجلة مسبقاً: ${code} (الاستخدامات: ${newData.uses})`);
          break;
        }
      }
    }

    // تحديث ذاكرة الدعوات
    await updateInviteCache(member.guild);

    // إذا لم يتم العثور على الدعوة المستخدمة
    if (!usedInvite || !usedInvite.inviter) {
      console.log("❌ لم يتم العثور على الدعوة المستخدمة أو من قام بالدعوة");
      const errorEmbed = new MessageEmbed()
        .setColor("#ff0000")
        .setDescription(
          `> 👤 **العضو الجديد:** ${member.user}\n` +
          `> ❌ **لم يتم تحديد من قام بدعوته**\n` +
          `> ⚠️ تم الانضمام عبر رابط قديم أو دعوة غير مسجلة`
        )
        .setTimestamp();
      await channel.send({ embeds: [errorEmbed] });
      await channel.send({ files: ["line2.png"] }).catch(() => {});
      return;
    }

    const inviter = usedInvite.inviter;

    // حساب عمر الحساب بالأشهر
    const accountAgeMonths = (Date.now() - member.user.createdTimestamp) / (1000 * 60 * 60 * 24 * 30);
    const isOldAccount = accountAgeMonths >= 3;

    console.log(`📊 معلومات العضو: ${member.user.tag} | عمر الحساب: ${accountAgeMonths.toFixed(2)} شهر | ${isOldAccount ? "✅ مؤهل" : "❌ غير مؤهل"}`);

    // إنشاء رسالة الإشعار
    let description = "";
    let shouldAddBalance = false;

    if (isOldAccount) {
      shouldAddBalance = true;
      description = 
        `> 👤 **العضو الجديد:** ${member.user}\n` +
        `> 🎫 **تمت دعوته بواسطة:** ${inviter}\n` +
        `> 📅 **عمر الحساب:** ${accountAgeMonths.toFixed(1)} شهر (فوق 3 أشهر)\n` +
        `> ✅ **تم إضافة مكافأة:** \`${BALANCE_UPDATE_AMOUNT.toLocaleString()}\` عملة\n` +
        `> 💰 **تلقى المكافأة:** ${inviter}`;
    } else {
      description = 
        `> 👤 **العضو الجديد:** ${member.user}\n` +
        `> 🎫 **تمت دعوته بواسطة:** ${inviter}\n` +
        `> 📅 **عمر الحساب:** ${accountAgeMonths.toFixed(1)} شهر (أقل من 3 أشهر)\n` +
        `> ❌ **لم يتم إضافة مكافأة** (الحساب جديد جداً)`;
    }

    const embed = new MessageEmbed()
      .setColor(isOldAccount ? "#00ff00" : "#ffaa00")
      .setTitle("🎉 عضو جديد انضم للسيرفر!")
      .setDescription(description)
      .setTimestamp();

    await channel.send({ embeds: [embed] });
    await channel.send({ files: ["line2.png"] }).catch(() => {});

    // إضافة الرصيد إذا كان الحساب قديماً
    if (shouldAddBalance) {
      await updateBalance(inviter.id, BALANCE_UPDATE_AMOUNT);
      console.log(`💰 تم إضافة ${BALANCE_UPDATE_AMOUNT} عملة إلى الداعي ${inviter.tag}`);
    }

  } catch (error) {
    console.error("❌ خطأ في معالجة العضو الجديد:", error);
    const errorEmbed = new MessageEmbed()
      .setColor("#ff0000")
      .setDescription(`> ❌ **حدث خطأ في معالجة العضو الجديد**\n> ${error.message}`)
      .setTimestamp();
    await channel.send({ embeds: [errorEmbed] }).catch(() => {});
  }
});

// دالة تحديث الرصيد
async function updateBalance(userId, amount) {
  try {
    let userData = await db.findOne({ id: userId });

    if (!userData) {
      userData = await db.create({
        id: userId,
        coins: amount,
        status_playing: "no",
        deposits: 0,
        withdrawals: 0,
        hasJoinedServer: true
      });
      console.log(`✅ تم إنشاء حساب جديد لـ ${userId} برصيد ${amount}`);
    } else {
      userData.coins = parseInt(userData.coins) + amount;
      userData.hasJoinedServer = true;
      await userData.save();
      console.log(`✅ تم إضافة ${amount} إلى رصيد ${userId} - الرصيد الجديد: ${userData.coins}`);
    }

    return true;
  } catch (error) {
    console.error(`❌ خطأ في تحديث رصيد ${userId}:`, error);
    return false;
  }
}


const CHANNEL_ID = SERVER_SETTINGS.channels.redeemSetupChannelId;
const ADMIN_ROLE_ID = SERVER_SETTINGS.roles.adminRoleId;
const CODES_FILE = path.join(__dirname, "redeemCodes.json");

// Ensure codes file exists
if (!fs.existsSync(CODES_FILE))
  fs.writeFileSync(CODES_FILE, JSON.stringify([]));
client.on("messageCreate", async (message) => {
  if (!message.guild) return;

  // Command: !setupredeem
  if (message.content === "!setupredeem") {
    const isOwner = owners.includes(message.author.id);
    const hasPerm = permStore.canUseCommand(message.author.id, "setupredeem");
    if (!isOwner && !hasPerm) {
      return message.reply("> ❌ ليس لديك صلاحية لاستخدام هذا الأمر.\nطلب من الإدارة: `!giveperm setupredeem @user`");
    }
    const channel = message.guild.channels.cache.get(CHANNEL_ID);
    if (!channel) return message.reply("Channel not found!");

    const embed = new MessageEmbed()
      .setColor("#032943")
      .setTitle("Diamond Redeem Codes")
      .setDescription(
        `
        ضع الأكواد صحيح من أجل الحصول على الجائزة
        كم بيستخدمها قبل إنتهاء وقتها أو عدد استخدامها ألأقصى
        لا تعمل الأكواد بعد إنتهاء صلاحيتها أو وصولها لي لحد ألأقصى
      `,
      )
      .setImage("attachment://luckbanner.png");

    const button = new MessageButton()
      .setCustomId("redeem_code")
      .setLabel("استرداد الكود")
      .setStyle("SUCCESS");

    const row = new MessageActionRow().addComponents(button);

    channel.send({
      embeds: [embed],
      components: [row],
      files: [path.join(__dirname, "luckbanner.png")], // Attach the image file
    });

    return message.reply("✅ Redeem system has been set up!");
  }

  // Command: !createcode
  if (message.content.startsWith("!createcode")) {
    // Check if the user has the required role
    if (!owners.includes(message.author.id)) {
      return message.reply(
        "❌ You do not have permission to use this command!",
      );
    }

    // Extract command arguments
    const args = message.content.split(" ").slice(1);
    if (args.length < 5) {
      return message.reply(
        "❌ Usage: `!createcode <code> <amount> <timeofuse> <expiration> <cooldown>`\n" +
          "**code**: The redeemable code\n" +
          "**amount**: The reward amount\n" +
          "**timeofuse**: Maximum number of uses\n" +
          "**expiration**: Expiration time (UNIX timestamp)\n" +
          "**cooldown**: Cooldown in seconds",
      );
    }

    const [code, amount, timeOfUse, expiration, cooldown] = args;

    // Validate the inputs
    if (
      isNaN(amount) ||
      isNaN(timeOfUse) ||
      isNaN(expiration) ||
      isNaN(cooldown)
    ) {
      return message.reply(
        "❌ Please provide valid numeric values for amount, timeofuse, expiration, and cooldown.",
      );
    }

    // Load existing codes
    let codes = [];
    const codesFilePath = path.join(__dirname, "codes.json");

    try {
      if (fs.existsSync(codesFilePath)) {
        codes = JSON.parse(fs.readFileSync(codesFilePath, "utf8"));
        if (!Array.isArray(codes)) throw new Error("Invalid codes format");
      }
    } catch (err) {
      console.error("Error reading codes.json:", err);
      return message.reply(
        "❌ An error occurred while reading the codes data.",
      );
    }

    // Add the new code
    codes.push({
      code,
      amount: parseInt(amount),
      timeOfUse: parseInt(timeOfUse),
      expiration: parseInt(expiration),
      cooldown: parseInt(cooldown),
      redeemedBy: [],
    });

    // Save the updated codes list
    try {
      fs.writeFileSync(codesFilePath, JSON.stringify(codes, null, 2));
      message.reply(`✅ Code \`${code}\` has been created successfully!`);
    } catch (err) {
      console.error("Error writing to codes.json:", err);
      message.reply("❌ An error occurred while saving the code.");
    }
  }
});

client.on("interactionCreate", async (interaction) => {
  if (interaction.isButton() && interaction.customId === "redeem_code") {
    try {
      const modal = new Modal()
        .setCustomId("redeem_modal")
        .setTitle("Redeem Code");

      const components = [
        {
          type: 1, // MessageActionRow
          components: [
            {
              type: 4, // TextInputComponent
              custom_id: "code_input",
              style: 1, // SHORT
              label: "Enter your redeem code:",
              placeholder: "Enter the code here",
              required: true,
            },
          ],
        },
      ];

      modal.components = components;

      // Show modal before any other interaction response
      await interaction.showModal(modal);
    } catch (err) {
      console.error("Error showing modal:", err);
    }
  }

  if (interaction.isModalSubmit() && interaction.customId === "redeem_modal") {
    const code = interaction.fields?.find?.(f => f.customId === "code_input")?.value;
    let codes;

    // Handle errors while reading/parsing the file
    try {
      codes = JSON.parse(fs.readFileSync("codes.json", "utf8"));
    } catch (err) {
      console.error("Error reading codes.json:", err);
      return interaction.reply({
        content: "❌ An error occurred while reading the codes data.",
        ephemeral: true,
      });
    }

    // Ensure the codes file is an array
    if (!Array.isArray(codes)) {
      return interaction.reply({
        content: "❌ The codes data is invalid.",
        ephemeral: true,
      });
    }

    const foundCode = codes.find((c) => c.code === code);

    if (!foundCode) {
      return interaction.reply({
        content: "❌ Invalid code!",
        ephemeral: true,
      });
    }

    const now = Date.now();
    const alreadyRedeemed = foundCode.redeemedBy.find(
      (user) => user.id === interaction.user.id,
    );

    if (alreadyRedeemed) {
      const cooldownEnd = new Date(
        alreadyRedeemed.redeemedAt + foundCode.cooldown * 1000,
      );
      if (now < cooldownEnd) {
        return interaction.reply({
          content: `❌ You can redeem this code again after ${cooldownEnd.toLocaleString()}.`,
          ephemeral: true,
        });
      }
    }

    if (now > foundCode.expiration * 1000) {
      return interaction.reply({
        content: "❌ This code has expired!",
        ephemeral: true,
      });
    }

    if (foundCode.redeemedBy.length >= foundCode.timeOfUse) {
      return interaction.reply({
        content: "❌ This code has reached its usage limit!",
        ephemeral: true,
      });
    }

    foundCode.redeemedBy.push({ id: interaction.user.id, redeemedAt: now });

    try {
      fs.writeFileSync("codes.json", JSON.stringify(codes, null, 2));
    } catch (err) {
      console.error("Error saving codes.json:", err);
      return interaction.reply({
        content: "❌ An error occurred while saving the codes data.",
        ephemeral: true,
      });
    }

    interaction.reply({
      content: `✅ You have successfully redeemed the code and received **${foundCode.amount}**!`,
      ephemeral: true,
    });
  }
});

