// Handle the selection from the dropdown
client.on("interactionCreate", async (interaction) => {
  if (!interaction.isSelectMenu()) return;
  if (interaction.customId !== "ticket_select") return;

  const selectedOption = interaction.values[0];
  const user = interaction.user;
  const guild = interaction.guild;

  if (selectedOption === "charge_ticket") {
    // Create a recharge ticket channel
    const channel = await guild.channels.create(`${user.username}-شحن`, {
      parent: SERVER_SETTINGS.channels.ticketCategoryId, // Set category for recharge tickets
      permissionOverwrites: [
        {
          id: guild.id,
          deny: ["VIEW_CHANNEL"],
        },
        {
          id: user.id,
          allow: ["VIEW_CHANNEL", "SEND_MESSAGES"],
        },
      ],
    });

    // Send recharge and withdrawal instructions
    const rechargeEmbed = new MessageEmbed()
      .setColor("#032943")
      .setTitle("كيفيه الشحن؟")
      .setDescription(`\`#credit ${SERVER_SETTINGS.users.ownerId} "المبلغ"\``);

    const withdrawalEmbed = new MessageEmbed()
      .setColor("#032943")
      .setTitle("كيفيه السحب؟")
      .setDescription(`توجه الى روم ⁠${SERVER_SETTINGS.links.withdrawRoomUrl}`);

    const countdownEmbed = new MessageEmbed()
      .setColor("#032943")
      .setDescription("**سوف يحذف الروم بعد 70 ثانية.**");

    await channel.send({ embeds: [rechargeEmbed] });
    await channel.send({ embeds: [withdrawalEmbed] });
    await channel.send({ embeds: [countdownEmbed] });

    // Start the countdown for deletion
    let timeRemaining = 70;
    const countdownMessage = await channel.send(
      `وقت التذكرة: ${timeRemaining}s`,
    );

    const countdownInterval = setInterval(async () => {
      timeRemaining -= 1;
      await countdownMessage.edit(`وقت التذكرة: ${timeRemaining}s`);
      if (timeRemaining <= 0) {
        clearInterval(countdownInterval);
        await channel.delete();
      }
    }, 1000);

    // Acknowledge the ticket creation to the user
    await interaction.reply({
      content: `تم فتح تذكرة الشحن الخاصة بك في القناة: ${channel}`,
      ephemeral: true,
    });
  } else if (selectedOption === "support_ticket") {
    // Create a support ticket channel
    const supportChannel = await guild.channels.create(
      `${user.username}-دعم-فني`,
      {
        parent: SERVER_SETTINGS.channels.ticketCategoryId, // Set category for support tickets
        permissionOverwrites: [
          {
            id: guild.id,
            deny: ["VIEW_CHANNEL"],
          },
          {
            id: user.id,
            allow: ["VIEW_CHANNEL", "SEND_MESSAGES"],
          },
        ],
      },
    );

    // Send support ticket instructions
    const supportEmbed = new MessageEmbed()
      .setColor("#032943")
      .setTitle("Support Tickets").setDescription(`
        **مرحبا بك في التكت الدعم الفني ، للمساعدة انتظر رد الدعم الفني واكتب سبب فتح التذكرة .**
      `);

    const deleteButton = new MessageButton()
      .setCustomId("delete_ticket")
      .setLabel("حذف التذكرة")
      .setStyle("DANGER");

    const row = new MessageActionRow().addComponents(deleteButton);

    await supportChannel.send({ embeds: [supportEmbed], components: [row] });

    // Acknowledge the ticket creation to the user
    await interaction.reply({
      content: `تم فتح تذكرة الدعم الفني الخاصة بك في القناة: ${supportChannel}`,
      ephemeral: true,
    });
  }
});

// Handling the delete ticket button interaction
client.on("interactionCreate", async (interaction) => {
  if (!interaction.isButton()) return;
  if (interaction.customId !== "delete_ticket") return;

  const channel = interaction.channel;

  // Check if the channel still exists (not deleted)
  if (!channel) {
    await interaction.reply({
      content: "هذه التذكرة قد تم حذفها بالفعل.",
      ephemeral: true,
    });
    return;
  }

  try {
    // Notify the user the ticket will be deleted in 5 seconds
    await interaction.reply({
      content: "التذكرة ستُحذف في 5 ثوانٍ.",
      ephemeral: true,
    });

    // Wait for 5 seconds before deleting the channel
    setTimeout(async () => {
      await channel.delete();
    }, 5000); // Wait for 5000 milliseconds (5 seconds)
  } catch (error) {
    console.error("Error deleting channel:", error);
    await interaction.reply({
      content: "حدث خطأ أثناء محاولة حذف التذكرة.",
      ephemeral: true,
    });
  }
});

