// Handle the selection from the dropdown
client.on("interactionCreate", async (interaction) => {
  if (!interaction.isSelectMenu()) return;
  if (interaction.customId !== "setrole_select") return;

  const roleOptions = {
    "1_5_million": SERVER_SETTINGS.roles.notify_1_5_million, // Role ID for 1-5 Million
    "10_20_million": SERVER_SETTINGS.roles.notify_10_20_million, // Role ID for 10-20 Million
    "50_100_million": SERVER_SETTINGS.roles.notify_50_100_million, // Role ID for 50-100 Million
    "500m_1billion": SERVER_SETTINGS.roles.notify_500m_1billion, // Role ID for 500M-1Billion
  };

  const selectedRole = interaction.values[0];
  const member = interaction.guild.members.cache.get(interaction.user.id);

  if (selectedRole === "reset_roles") {
    // Reset roles: Remove all notification roles
    await member.roles.remove([
      SERVER_SETTINGS.roles.notify_1_5_million,
      SERVER_SETTINGS.roles.notify_10_20_million,
      SERVER_SETTINGS.roles.notify_50_100_million,
      SERVER_SETTINGS.roles.notify_500m_1billion,
    ]);
    await interaction.reply({
      content: "تم إعادة تعيين رتبك بنجاح.",
      ephemeral: true,
    });
  } else if (roleOptions[selectedRole]) {
    // Add the selected role to the user
    await member.roles.add(roleOptions[selectedRole]);
    await interaction.reply({
      content: `تم إضافة رتبتك بنجاح! الآن أنت عضو في رتبة: ${selectedRole.replace("_", " ").replace("million", " مليون")}`,
      ephemeral: true,
    });
  }
});

