const dataPath = path.join(__dirname, "userData.json");

// Function to get user data
const getUserData = async (userId) => {
  try {
    const data = fs.readFileSync(dataPath, "utf8");
    const users = JSON.parse(data);
    return users[userId] || null;
  } catch (err) {
    console.error("Error reading user data file:", err);
    return null;
  }
};

// Function to save user data
const saveUserData = async (userId, userData) => {
  try {
    const data = fs.readFileSync(dataPath, "utf8");
    const users = JSON.parse(data);
    users[userId] = userData;
    fs.writeFileSync(dataPath, JSON.stringify(users, null, 2));
  } catch (err) {
    console.error("Error saving user data file:", err);
  }
};

client.on("messageCreate", async (message) => {
  if (
    message.content.startsWith("daily") || // or "دايلي"
    message.content.startsWith("دايلي")
  ) {
    // Ensure the command was sent by a valid user and is not a bot
    if (message.author.bot) return;

    // Get user data from JSON file
    let userData = await getUserData(message.author.id);

    // If user doesn't exist, create new user data
    if (!userData) {
      userData = {
        coins: 0,
        status_playing: "no",
        lastClaim: 0, // Initialize lastClaim as 0 if it's the first time claiming
      };
      await saveUserData(message.author.id, userData); // Save new user data
    }

    // Get current timestamp and the last claim time
    const currentTime = Date.now();
    const lastClaimTime = userData.lastClaim || 0; // Default to 0 if undefined

    console.log(`Current Time: ${currentTime}`);
    console.log(`Last Claim Time: ${lastClaimTime}`);

    // Check if 24 hours have passed since last claim
    const timeDifference = currentTime - lastClaimTime;
    const hoursPassed = timeDifference / (1000 * 60 * 60); // Convert milliseconds to hours
    console.log(`Hours Passed: ${hoursPassed}`); // Debugging log

    if (lastClaimTime > 0 && hoursPassed < 24) {
      // If less than 24 hours have passed, inform the user
      const hoursRemaining = Math.ceil(24 - hoursPassed);
      return message.reply({
        content: `> لقد قمت بالمطالبة بمكافأتك اليومية بالفعل. يمكنك المحاولة مرة أخرى بعد ${hoursRemaining} ساعة.`,
      });
    }

    // Random amount between 5000 and 10000
    const randomAmount = Math.floor(Math.random() * (10000 - 5000 + 1)) + 5000;

    // Add the random amount to the user's balance
    userData.coins = parseInt(userData.coins) + randomAmount;

    // Update the last claim time to current time
    userData.lastClaim = currentTime;

    // Save the updated user data
    await saveUserData(message.author.id, userData);

    // Create the embed reply
    const embed = new MessageEmbed()
      .setColor("#032943")
      .setTitle("مكافأتك اليومية!")
      .setDescription(
        `> ${message.author}, لقد حصلت على $${randomAmount.toLocaleString()} كوينز!`,
      )
      .setFooter(message.guild.name)
      .setTimestamp();

    // Send embed to the user
    message.reply({ embeds: [embed] });

    // Send the same embed to the log channel
    const logChannel = client.channels.cache.get(
      SERVER_SETTINGS.channels.dailyLogId,
    );
    if (logChannel) {
      logChannel.send({
        content: `> ||${message.channel}|| ||(https://discord.com/channels/${message.guild.id}/${message.channel.id}/${message.id})||`,
        embeds: [embed],
      });
    }
  }
});

// Interaction Event
client.on("interactionCreate", async (interaction) => {
  if (interaction.isButton() && interaction.customId === "request_withdraw") {
    let data = await db.findOne({ id: interaction.user.id });
    if (!data) {
      data = await db.create({
        id: interaction.user.id,
        coins: 0,
        status_playing: "no",
        is_withdrawing: false,
      });
    }

    // Check if the user is already withdrawing
    if (data.is_withdrawing) {
      return interaction.reply({
        content: "أنت في قيد عملية سحب بالفعل!",
        ephemeral: true,
      });
    }

    // Check if the user is in a game
    if (data.status_playing === "yes") {
      return interaction.reply({
        content: "> لا يمكنك السحب اثناء تحدي !",
        ephemeral: true,
      });
    }

    // Set the is_withdrawing flag to true
    data.is_withdrawing = true;
    await data.save();

    // Create and display the modal
    const modal = new Modal()
      .setCustomId("withdraw_modal")
      .setTitle("طلب سحب رصيد")
      .addComponents(
        new TextInputComponent()
          .setCustomId("withdraw_amount")
          .setLabel("المبلغ المراد سحبه")
          .setStyle("SHORT")
          .setPlaceholder("ادخل المبلغ هنا (بين 3,000,000 و 999,999,999)")
          .setRequired(true),
      );

    await showModal(modal, { client, interaction });
  }

  if (
    interaction.isModalSubmit() &&
    interaction.customId === "withdraw_modal"
  ) {
    const amountInput = interaction.fields.getTextInputValue("withdraw_amount");
    const amount = parseInt(amountInput);

    let data = await db.findOne({ id: interaction.user.id });
    if (!data) {
      data = await db.create({
        id: interaction.user.id,
        coins: 0,
        status_playing: "no",
        is_withdrawing: false,
      });
    }

    // Validate the withdrawal amount
    if (isNaN(amount) || amount < 1 || amount > 999999999) {
      data.is_withdrawing = false;
      await data.save();
      return interaction.reply({
        content: "المبلغ الذي أدخلته غير صالح. حاول مرة أخرى!",
        ephemeral: true,
      });
    }

    if (amount > data.coins) {
      data.is_withdrawing = false;
      await data.save();
      return interaction.reply({
        content: "ليس لديك رصيد كافٍ لسحب هذا المبلغ!",
        ephemeral: true,
      });
    }

    // Deduct the withdrawal amount and save the changes
    data.coins -= amount;
    data.is_withdrawing = false;
    await data.save();

    // Send styled withdrawal request to the requests channel
    const withdrawalEmbed = new Discord.MessageEmbed()
      .setColor("#032943")
      .setTitle("💸 طلب سحب رصيد جديد")
      .setDescription(
        `> 👤 **العضو:** <@${interaction.user.id}>\n` +
        `> 💰 **المبلغ المطلوب:** \`${amount.toLocaleString("en-US")}\`\n` +
        `> 💵 **الرصيد المتبقي:** \`${data.coins.toLocaleString("en-US")}\`\n` +
        `> 📅 **الوقت:** <t:${Math.floor(Date.now() / 1000)}:F>\n` +
        `> ━━━━━━━━━━━━━━━━━━━━\n` +
        `> ⚠️ **للموافقة أو الرفض استخدم الأزرار أدناه**`
      )
      .setThumbnail(interaction.user.displayAvatarURL({ dynamic: true }))
      .addFields(
        { name: "🆔 معرف العضو", value: `\`${interaction.user.id}\``, inline: true },
        { name: "📊 الحالة", value: "⏳ قيد المراجعة", inline: true },
      )
      .setFooter({ text: "طلب سحب • Diamond Casino" })
      .setTimestamp();

    const buttonRow = new Discord.MessageActionRow().addComponents(
      new Discord.MessageButton()
        .setCustomId("approve_withdraw")
        .setLabel("✅ تأكيد التحويل")
        .setStyle("SUCCESS"),
      new Discord.MessageButton()
        .setCustomId("cancel_withdraw")
        .setLabel("❌ إلغاء السحب")
        .setStyle("DANGER"),
    );

    const withdrawalChannel = client.channels.cache.get(
      SERVER_SETTINGS.channels.withdrawalRequestsId,
    );
    if (withdrawalChannel) {
      await withdrawalChannel.send({ embeds: [withdrawalEmbed], components: [buttonRow] });
    }

    interaction.reply({
      content: "> ✅ **تم تقديم طلب السحب بنجاح!**\n> سيتم مراجعته والتواصل معك خلال 24 ساعة.",
      ephemeral: true,
    });
  }
});

