function buildHelpRows(activePage) {
  const row1 = new MessageActionRow().addComponents(
    new MessageButton()
      .setCustomId("help_home")
      .setLabel("🏠 الرئيسية")
      .setStyle(activePage === "home" ? "SUCCESS" : "SECONDARY"),

    new MessageButton()
      .setCustomId("help_economy")
      .setLabel("💰 الاقتصاد")
      .setStyle(activePage === "economy" ? "SUCCESS" : "SECONDARY"),

    new MessageButton()
      .setCustomId("help_games")
      .setLabel("🎮 الألعاب")
      .setStyle(activePage === "games" ? "SUCCESS" : "SECONDARY"),

    new MessageButton()
      .setCustomId("help_betting")
      .setLabel("🏟️ الرهانات")
      .setStyle(activePage === "betting" ? "SUCCESS" : "SECONDARY")
  );

  const row2 = new MessageActionRow().addComponents(
    new MessageButton()
      .setCustomId("help_abilities")
      .setLabel("✨ القدرات")
      .setStyle(activePage === "abilities" ? "SUCCESS" : "SECONDARY"),

    new MessageButton()
      .setCustomId("help_trading")
      .setLabel("📈 التداول")
      .setStyle(activePage === "trading" ? "SUCCESS" : "SECONDARY"),

    new MessageButton()
      .setCustomId("help_watch")
      .setLabel("🎬 المشاهدة")
      .setStyle(activePage === "watch" ? "SUCCESS" : "SECONDARY")
  );

  return [row1, row2];
}

client.on("messageCreate", async (message) => {
  if (!message.guild || message.author.bot) return;
  const trig = message.content.trim().toLowerCase();
  if (!trig.startsWith("help") && !trig.startsWith("مساعدة")) return;

  await message.reply({
    embeds: [buildHelpEmbed("home")],
    components: buildHelpRows("home"),
  });
});

// —— help panel button navigation ———————————————————————————————
client.on("interactionCreate", async (interaction) => {
  if (!interaction.isButton()) return;
  const pageMap = {
    help_home: "home",
    help_economy: "economy",
    help_games: "games",
    help_betting: "betting",
    help_abilities: "abilities",
    help_trading: "trading",
    help_watch: "watch",
  };
  const page = pageMap[interaction.customId];
  if (!page) return;
  await interaction.update({
    embeds: [buildHelpEmbed(page)],
    components: buildHelpRows(page),
  });
});

