client.on("messageCreate", async (message) => {
  if (message.content.toLowerCase() === "line") {
    const isOwner = owners.includes(message.author.id);
    const hasPerm = permStore.canUseCommand(message.author.id, "line");
    if (!isOwner && !hasPerm) {
      return message.reply({
        content: "❌ ليس لديك الصلاحية لاستخدام هذا الأمر.\nطلب من الإدارة: `!giveperm line @user`",
        ephemeral: true,
      });
    }

    try {
      await message.channel.send({ files: ["line2.png"] });
      await message.delete();
    } catch (error) {
      console.error("Error while executing the line command:", error);
      message.channel.send("⚠️ حدث خطأ أثناء تنفيذ الأمر.");
    }
  }
});

let linkedData = require("./linked.json"); // Assuming 'linked.json' exists in your project

client.on("messageCreate", async (message) => {
  if (
    message.content.split(" ")[0] == "فلوس" ||
    message.content.split(" ")[0] == "Money" ||
    message.content.split(" ")[0] == "money"
  ) {
    let user = message.mentions.users.first() || message.author;

    // Fetch the user's data from the database (db.findOne())
    let data = await db.findOne({ id: user.id });
    if (!data) {
      // If no user data, initialize default data
      data = await db.create({
        id: user.id,
        coins: 0,
        status_playing: "no",
      });
    }

    let embed;

    // Check if the user is linked to another account
    let linkedData = require("./linked.json"); // Load the linked data
    let linkedUserId = linkedData[user.id]
      ? linkedData[user.id].linkedWith
      : null;

    if (linkedUserId) {
      try {
        // Fetch the linked user's data from the database (db.findOne())
        let linkedUserData = await db.findOne({ id: linkedUserId });
        if (!linkedUserData) {
          // If the linked user doesn't exist in the database, set default values
          linkedUserData = { id: linkedUserId, coins: 0, status_playing: "no" };
        }

        // Get the user and linked user balances
        let userBalance = data.coins;
        let linkedUserBalance = linkedUserData.coins;

        // Fetch the linked user info from discord
        let linkedUser = await client.users.fetch(linkedUserId);

        // Create the embed with both user and linked user balances
        embed = new MessageEmbed()
          .setColor("#032943")
          .setThumbnail(client.user.avatarURL({ dynamic: true }))
          .setTitle(`الرصيد الحالي لـ ${user.tag}`)
          .setDescription(
            `
            > $${parseInt(userBalance).toLocaleString()}

            **الرصيد الحالي لبنك ${linkedUser.tag}**
            > $${parseInt(linkedUserBalance).toLocaleString()}
          `,
          )
          .setFooter(message.guild.name)
          .setTimestamp();

        message.reply({ embeds: [embed], content: `> ${message.author}` });
      } catch (err) {
        console.error("Error fetching linked user data: ", err);
        message.reply("حدث خطأ في جلب بيانات المستخدم المرتبط.");
      }
    } else {
      // If not linked, show the user's own balance
      let userBalance = data.coins;
      embed = new MessageEmbed()
        .setColor("#032943")
        .setThumbnail(client.user.avatarURL({ dynamic: true }))
        .setTitle(`الرصيد الحالي لـ ${user.tag}`)
        .setDescription(`> $${parseInt(userBalance).toLocaleString()}`)
        .setFooter(message.guild.name)
        .setTimestamp();

      message.reply({ embeds: [embed], content: `> ${message.author}` });
    }
  }
});

client.on("messageCreate", async (message) => {
  // Handle the linking command
  if (message.content.split(" ")[0] == "ربط") {
    let mentionedUser = message.mentions.users.first();
    if (!mentionedUser) return message.reply("من فضلك ذكر مستخدم!");

    // Fetch user data from the database (linked.json)
    let userData = linkedData[message.author.id];
    let mentionedData = linkedData[mentionedUser.id];

    // If user data doesn't exist, initialize it
    if (!userData) {
      userData = { id: message.author.id, linkedWith: null };
      linkedData[message.author.id] = userData; // Save to linked.json
    }

    if (!mentionedData) {
      mentionedData = { id: mentionedUser.id, linkedWith: null };
      linkedData[mentionedUser.id] = mentionedData; // Save to linked.json
    }

    // Check if either is already linked
    if (userData.linkedWith) {
      return message.reply("أنت بالفعل مرتبط بحساب آخر.");
    }
    if (mentionedData.linkedWith) {
      return message.reply("المستخدم المذكور مرتبط بحساب آخر.");
    }

    // Create the linking request embed
    let embed = new MessageEmbed()
      .setColor("#032943")
      .setTitle("🔗 طلب ربط حسابات")
      .setDescription(`${mentionedUser.tag} طلب ربط معك!`)
      .addFields({ name: "📝 التفاصيل", value: `${message.author.tag} يريد ربط حسابه معك!` })
      .setThumbnail(client.user.avatarURL({ dynamic: true }))
      .setFooter(
        `طلب الربط من: ${message.author.tag}`,
        message.author.avatarURL(),
      )
      .setTimestamp();

    let row = new MessageActionRow().addComponents(
      new MessageButton()
        .setCustomId("acceptLink")
        .setLabel("✅ قبول")
        .setStyle("SUCCESS"),
      new MessageButton()
        .setCustomId("rejectLink")
        .setLabel("❌ رفض")
        .setStyle("DANGER"),
    );

    // Send the request with buttons
    mentionedUser.send({ embeds: [embed], components: [row] }).then(() => {
      message.reply(`تم إرسال طلب ربط إلى ${mentionedUser.tag}`);
    });

    // Handle the button interaction
    client.on("interactionCreate", async (interaction) => {
      if (!interaction.isButton()) return;

      if (interaction.user.id === mentionedUser.id) {
        if (interaction.customId === "acceptLink") {
          // Accept the link, update the data
          userData.linkedWith = mentionedUser.id;
          mentionedData.linkedWith = message.author.id;

          // Save the linked data to linked.json
          fs.writeFileSync(
            "./linked.json",
            JSON.stringify(linkedData, null, 2),
          );

          // Update the embed with success message
          const successEmbed = new MessageEmbed()
            .setColor("#032943")
            .setTitle("✅ تم الربط بنجاح")
            .setDescription(
              `${mentionedUser.tag} تم ربط حسابك مع ${message.author.tag} بنجاح!`,
            )
            .setThumbnail(client.user.avatarURL({ dynamic: true }))
            .setFooter(message.guild.name)
            .setTimestamp();

          // Send the updated embed to the mentioned user
          await interaction.update({ embeds: [successEmbed], components: [] });

          // Notify the channel where the original request was made (specific channel ID)
          const notificationEmbed = new MessageEmbed()
            .setColor("#032943")
            .setTitle("🔗 تم تسجيل عملية ربط")
            .setDescription(
              `
              **المرسل**: <@${message.author.id}> (${message.author.tag})
              **البنك**: <@${mentionedUser.id}> (${mentionedUser.tag})
            `,
            )
            .setFooter(message.guild.name)
            .setTimestamp()
            .setThumbnail(client.user.avatarURL({ dynamic: true }));

          const notificationChannel = await client.channels.fetch(
            SERVER_SETTINGS.channels.linkActionsLogId,
          );
          notificationChannel.send({ embeds: [notificationEmbed] });
        } else if (interaction.customId === "rejectLink") {
          // Reject the link
          const rejectEmbed = new MessageEmbed()
            .setColor("#032943")
            .setTitle("❌ تم رفض طلب الربط")
            .setDescription(`${mentionedUser.tag} رفض طلب ربط معك.`)
            .setFooter(message.guild.name)
            .setTimestamp();
          await interaction.update({ embeds: [rejectEmbed], components: [] });
        }
      }
    });
  }

  // Handle the unlinking command (/فصل)
  if (message.content.split(" ")[0] == "فصل") {
    let mentionedUser = message.mentions.users.first();
    if (!mentionedUser) return message.reply("من فضلك ذكر مستخدم!");

    // Fetch user data from the linked.json
    let userData = linkedData[message.author.id];
    let mentionedData = linkedData[mentionedUser.id];

    // Check if either user is linked to another
    if (!userData || !userData.linkedWith) {
      return message.reply("أنت غير مرتبط بحساب آخر.");
    }

    if (
      !mentionedData ||
      !mentionedData.linkedWith ||
      mentionedData.linkedWith !== message.author.id
    ) {
      return message.reply("المستخدم المذكور غير مرتبط بحسابك.");
    }

    // Unlink both users
    userData.linkedWith = null;
    mentionedData.linkedWith = null;

    // Save the updated data to linked.json
    fs.writeFileSync("./linked.json", JSON.stringify(linkedData, null, 2));

    // Notify the users and the channel
    const unlinkEmbed = new MessageEmbed()
      .setColor("#032943")
      .setTitle("🔗 تم فصل الحسابات بنجاح")
      .setDescription(
        `${mentionedUser.tag} تم فصل حسابك عن ${message.author.tag} بنجاح!`,
      )
      .setThumbnail(client.user.avatarURL({ dynamic: true }))
      .setFooter(message.guild.name)
      .setTimestamp();

    message.reply({ embeds: [unlinkEmbed] });

    // Send a notification to the channel where the unlink was made
    const notificationEmbed = new MessageEmbed()
      .setColor("#032943")
      .setTitle("🔗 تم فصل عملية ربط")
      .setDescription(
        `
        **المرسل**: <@${message.author.id}> (${message.author.tag})
        **البنك**: <@${mentionedUser.id}> (${mentionedUser.tag})
      `,
      )
      .setFooter(message.guild.name)
      .setTimestamp()
      .setThumbnail(client.user.avatarURL({ dynamic: true }));

    const notificationChannel = await client.channels.fetch(
      SERVER_SETTINGS.channels.linkActionsLogId,
    );
    notificationChannel.send({ embeds: [notificationEmbed] });
  }
});

