function getRandomNumber(min, max) {
  return Math.floor(Math.random() * (max - min + 1) + min);
}

// 🧠 Smart Taqribi Helper Functions
function getTaqribiSmartInfo(maxNum, currentScore, opponentScore, smallerRange, greaterRange) {
  const distanceToMax = maxNum - currentScore;
  const opponentDistance = maxNum - opponentScore;
  const avgSmaller = Math.floor((smallerRange.min + smallerRange.max) / 2);
  const avgGreater = Math.floor((greaterRange.min + greaterRange.max) / 2);

  // Strategy: suggest best button based on current position
  let strategy = "";
  let emoji = "";

  if (currentScore > maxNum) {
    strategy = "⚠️ أنت تجاوزت! انهِ اللعبة";
    emoji = "🔴";
  } else if (opponentDistance < 0 && distanceToMax > 0) {
    strategy = "✅ الخصم تجاوز! اختر بحذر";
    emoji = "🟢";
  } else if (distanceToMax > avgGreater) {
    strategy = "💡 اختر الأكبر";
    emoji = "📈";
  } else if (distanceToMax > 0 && distanceToMax <= avgGreater) {
    strategy = "💡 اختر الأصغر";
    emoji = "📉";
  } else {
    strategy = "⏹️ قريب جداً!";
    emoji = "🎯";
  }

  return {
    distance: Math.max(0, distanceToMax),
    opponentDistance: Math.max(0, opponentDistance),
    strategy,
    emoji,
    isBehind: opponentDistance < distanceToMax && distanceToMax > 0
  };
}

// Format player score display with smart info
function formatTaqribiPlayerDisplay(playerTag, score, maxNum, attempts, status, smartInfo) {
  const distText = smartInfo.distance > 0 ? `📊 المسافة: +${smartInfo.distance}` : `🎯 وصلت!`;
  return `**${playerTag}**\n> ${status}\n> المجموع: **${score}** | ${distText}\n> المحاولات: ${attempts}`;
}


