const CONFIG_FILE = "config.json";
const REDEEM_CODES_FILE = "redeem_codes.json";

// Bot configuration and redeem codes handling
function loadConfig() {
  if (!fs.existsSync(CONFIG_FILE)) {
    return {};
  }
  return JSON.parse(fs.readFileSync(CONFIG_FILE, "utf8"));
}

function saveConfig(config) {
  fs.writeFileSync(CONFIG_FILE, JSON.stringify(config, null, 4));
}

function loadCodes() {
  if (!fs.existsSync(REDEEM_CODES_FILE)) {
    return {};
  }
  return JSON.parse(fs.readFileSync(REDEEM_CODES_FILE, "utf8"));
}

function saveCodes(codes) {
  fs.writeFileSync(REDEEM_CODES_FILE, JSON.stringify(codes, null, 4));
}

function generateCode(length = 8) {
  const chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
  let result = "";
  for (let i = 0; i < length; i++) {
    result += chars.charAt(Math.floor(Math.random() * chars.length));
  }
  return result;
}

// Convert expiration time to milliseconds
function parseExpirationTime(expirationStr) {
  const match = expirationStr.match(/(\d+)([mhd])/);
  if (match) {
    const value = parseInt(match[1]);
    const unit = match[2];
    if (unit === "m") return value * 60000; // minutes
    if (unit === "h") return value * 3600000; // hours
    if (unit === "d") return value * 86400000; // days
  }
  return null; // Invalid format
}

client.on("messageCreate", async (message) => {
  if (message.author.bot) return;

  // Setup command
  if (message.content.toLowerCase() === "!setup") {
    const config = loadConfig();
    config.redeem_channel = message.channel.id;
    saveConfig(config);
    message.channel.send("تم إعداد قناة استرداد الأكواد بنجاح!");
  }

  // Create code command
  if (message.content.toLowerCase().startsWith("!createcode")) {
    const isOwner = owners.includes(message.author.id);
    const hasPerm = permStore.canUseCommand(message.author.id, "createcode");
    if (!isOwner && !hasPerm) {
      return message.reply("> ❌ ليس لديك صلاحية لاستخدام هذا الأمر.\nطلب من الإدارة: `!giveperm createcode @user`");
    }
    const args = message.content.split(" ");

    if (args[1] === "help") {
      const embed = new MessageEmbed()
        .setTitle("📖 كيفية استخدام الأمر `createcode`")
        .setDescription(
          "**صيغة الأمر:**\n" +
            "`createcode [code] [expiration] [usage_limit] [reward_amount]`\n\n" +
            "**تفاصيل:**\n" +
            "- **code**: إذا لم يتم تقديم كود، سيتم إنشاؤه بشكل عشوائي.\n" +
            "- **expiration**: مدة صلاحية الكود (افتراضي: 1d).\n" +
            "- **usage_limit**: الحد الأقصى لاستخدام الكود (افتراضي: 5).\n" +
            "- **reward_amount**: النقاط التي يمنحها الكود (افتراضي: 100).\n",
        )
        .setColor("#032943");
      return message.channel.send({ embeds: [embed] });
    }

    const code = args[1] || generateCode();
    const expiration = args[2] || "1d";
    const usageLimit = parseInt(args[3] || 5);
    const rewardAmount = parseInt(args[4] || 100);

    const expirationTime = parseExpirationTime(expiration);
    if (!expirationTime) {
      return message.channel.send(
        "❌ **صيغة غير صالحة للمدة!** استخدم: `m` للدقائق، `h` للساعات، `d` للأيام.",
      );
    }

    const expirationDate = new Date(Date.now() + expirationTime);
    const codes = loadCodes();

    if (codes[code]) {
      return message.channel.send(
        "❌ **الكود الذي تحاول إضافته موجود بالفعل!** الرجاء اختيار كود آخر.",
      );
    }

    codes[code] = {
      expiration_time: expirationDate.toISOString(),
      usage_limit: usageLimit,
      used: 0,
      reward_amount: rewardAmount,
      redeemed_users: [],
    };

    saveCodes(codes);

    const embed = new MessageEmbed()
      .setTitle("✅ كود جديد تم إنشاؤه")
      .setDescription(
        `**الكود:** \`${code}\`\n` +
          `**مدة الصلاحية:** \`${expiration}\`\n` +
          `**الحد الأقصى للاستخدام:** \`${usageLimit}\` مرة\n` +
          `**النقاط المكتسبة:** \`${rewardAmount}\` نقطة`,
      )
      .setColor("#032943")
      .setFooter("يمكنك مشاركة هذا الكود مع المستخدمين الآن!");

    message.channel.send({ embeds: [embed] });
  }

  // Redeem code command
});

