client.on("messageCreate", async (message) => {
  if (message.author.bot) return;
  if (!owners.includes(message.author.id)) return;
  const args = message.content.trim().split(/\s+/);

  // أغاني بيانو — list all songs
  if (args[0] === "أغاني" && args[1] === "بيانو") {
    const songs = pianoModule.loadSongs();
    if (!songs.length) return message.reply("> ❌ لا توجد أغاني مضافة.");
    const list = songs.map((s,i) => `**${i+1}.** ${s.emoji} **${s.name}** — ID: \`${s.id}\` — BPM: **${s.bpm || "؟"}** — صوت: ${s.audioSrc ? "✅" : "❌"}`).join("\n");
    return message.reply(`🎹 **أغاني البيانو المتاحة:**\n${list}`);
  }

  // إضافة أغنية بيانو <id> <emoji> <bpm> <الاسم>
  // مثال: إضافة أغنية بيانو summer 🌞 128 صيف حار
  // يمكن إرفاق ملف MP3 مباشرة مع الرسالة
  if (args[0] === "إضافة" && args[1] === "أغنية" && args[2] === "بيانو") {
    const id       = args[3];
    const emoji    = args[4];
    const bpmRaw   = args[5];
    const bpm      = parseInt(bpmRaw, 10);
    const name     = args.slice(6).join(" ");

    if (!id || !emoji || isNaN(bpm) || !name)
      return message.reply(
        "> ❌ الاستخدام: `إضافة أغنية بيانو <id> <emoji> <bpm> <الاسم>`\n" +
        "> مثال: `إضافة أغنية بيانو summer 🌞 128 صيف حار`\n" +
        "> يمكنك إرفاق ملف MP3 مع الرسالة لتُضاف تلقائياً كمصدر الصوت."
      );

    if (bpm < 40 || bpm > 300)
      return message.reply("> ❌ البروم (BPM) يجب أن يكون بين **40** و **300**.");

    const songs = pianoModule.loadSongs();
    if (songs.find(s => s.id === id))
      return message.reply(`> ❌ يوجد أغنية بالـ ID: \`${id}\` بالفعل. استخدم ID مختلف.`);

    const attachment = message.attachments.first();
    let audioSrc = null;
    if (attachment) {
      const fname = attachment.name?.toLowerCase() || "";
      if (fname.endsWith(".mp3") || fname.endsWith(".ogg") || fname.endsWith(".wav") || fname.endsWith(".m4a")) {
        audioSrc = attachment.url;
      } else {
        return message.reply("> ❌ الملف المرفق غير مدعوم. أرفق ملف `.mp3` أو `.ogg` أو `.wav`.");
      }
    }

    songs.push({ id, name, emoji, bpm, audioSrc });
    pianoModule.saveSongs(songs);

    const audioLine = audioSrc ? `\n> 🎵 ملف الصوت: مرفق (${attachment.name})` : "\n> 🔇 بدون ملف صوت (يمكن إضافته لاحقاً)";
    return message.reply(
      `> ✅ تمت إضافة الأغنية ${emoji} **${name}**\n` +
      `> 🎚️ BPM: **${bpm}**${audioLine}`
    );
  }

  // حذف أغنية بيانو <id>
  if (args[0] === "حذف" && args[1] === "أغنية" && args[2] === "بيانو") {
    const id = args[3];
    if (!id) return message.reply("> ❌ حدد ID الأغنية: `حذف أغنية بيانو <id>`");
    const songs = pianoModule.loadSongs();
    const idx   = songs.findIndex(s => s.id === id);
    if (idx === -1) return message.reply(`> ❌ لم يتم العثور على أغنية بالـ ID: \`${id}\``);
    const removed = songs.splice(idx, 1)[0];
    pianoModule.saveSongs(songs);
    return message.reply(`> ✅ تم حذف الأغنية ${removed.emoji} **${removed.name}**`);
  }
});

