async function invGet(userId) {
  return inventory.findOne({ id: userId });
}

async function invEnsure(userId) {
  let inv = await inventory.findOne({ id: userId });
  if (!inv) inv = await inventory.create({ id: userId, items: [] });
  return inv;
}

function invHasActive(inv, type) {
  if (!inv) return false;
  return inv.items.some((i) => {
    if (i.type !== type) return false;
    if (i.expiresAt && Date.now() > i.expiresAt) return false;
    return true;
  });
}

async function invConsume(userId, type) {
  const inv = await invGet(userId);
  if (!inv) return false;
  const idx = inv.items.findIndex(
    (i) => i.type === type && (!i.expiresAt || Date.now() <= i.expiresAt),
  );
  if (idx === -1) return false;
  inv.items.splice(idx, 1);
  inv.markModified("items");
  await inv.save();
  return true;
}

async function invAdd(userId, type) {
  const inv = await invEnsure(userId);
  const def = ABILITY_DEFS[type];
  if (!def) return;
  inv.items.push({
    type,
    emoji: def.emoji,
    name: def.name,
    acquiredAt: Date.now(),
    expiresAt: (type === "steal_blade" ? Date.now() + 86_400_000 : (type === "tax_shield" ? Date.now() + 10_800_000 : null)),
  });
  inv.markModified("items");
  await inv.save();
  return inv;
}

// ---- helper: finish bot game and settle coins (with ability system) ----
async function finishBotGame(userId, won, tied, amount, channelId = null) {
  let data = await db.findOne({ id: userId });
  if (!data)
    data = await db.create({ id: userId, coins: 0, status_playing: "no" });

  const inv = await invGet(userId);
  let effectiveWon = won;
  let effectiveTied = tied;
  let effectiveAmount = amount;
  const abilityMessages = [];

  // ── Defensive abilities on loss — balanced refunds only, NO win/draw conversion ──
  if (!effectiveWon && !effectiveTied) {
    // 1. Lucky Coin → 20% refund on loss (was: guaranteed win)
    if (invHasActive(inv, "lucky_coin")) {
      const refund = Math.floor(effectiveAmount * 0.20);
      effectiveAmount = effectiveAmount - refund;
      await invConsume(userId, "lucky_coin");
      abilityMessages.push(`🍀 **Lucky Coin** — استُرجع 20% من الخسارة! (+${refund.toLocaleString("en-US")} كوين)`);
      await logAbilityEvent(userId, "lucky_coin", "لعبة ضد البوت — استرجاع 20% خسارة", refund);
    }
    // 1b. Return by Death (Subaru) → 25% refund on loss (was: guaranteed win)
    if (invHasActive(inv, "rz_return_by_death")) {
      const refund = Math.floor(effectiveAmount * 0.25);
      effectiveAmount = effectiveAmount - refund;
      await invConsume(userId, "rz_return_by_death");
      abilityMessages.push(`⚔️ **Return by Death** — Subaru يعيد 25% من خسارتك! (+${refund.toLocaleString("en-US")} كوين)`);
      await logAbilityEvent(userId, "rz_return_by_death", "Re:Zero — استرجاع 25% خسارة", refund);
    }
    // 2. Counter Token → 20% refund on loss (was: convert to draw)
    if (invHasActive(inv, "counter_token")) {
      const refund = Math.floor(effectiveAmount * 0.20);
      effectiveAmount = effectiveAmount - refund;
      await invConsume(userId, "counter_token");
      abilityMessages.push(`⚡ **Counter Token** — استُرجع 20% من الخسارة! (+${refund.toLocaleString("en-US")} كوين)`);
      await logAbilityEvent(userId, "counter_token", "لعبة ضد البوت — استرجاع 20% خسارة", refund);
    }
    // 2b. Divine Protection (Priscilla) → 20% refund on loss (was: convert to draw)
    if (invHasActive(inv, "rz_divine_prot")) {
      const refund = Math.floor(effectiveAmount * 0.20);
      effectiveAmount = effectiveAmount - refund;
      await invConsume(userId, "rz_divine_prot");
      abilityMessages.push(`🌹 **Divine Protection** — Priscilla تسترجع 20% من خسارتك! (+${refund.toLocaleString("en-US")} كوين)`);
      await logAbilityEvent(userId, "rz_divine_prot", "Re:Zero — استرجاع 20% خسارة", refund);
    }
    // 3. Shield of Fortune → 15% refund on loss (was: absorb full loss)
    if (invHasActive(inv, "shield_of_fortune")) {
      const refund = Math.floor(effectiveAmount * 0.15);
      effectiveAmount = effectiveAmount - refund;
      await invConsume(userId, "shield_of_fortune");
      abilityMessages.push(`🛡️ **Shield of Fortune** — الدرع تسترجع 15% من خسارتك! (+${refund.toLocaleString("en-US")} كوين)`);
      await logAbilityEvent(userId, "shield_of_fortune", "لعبة ضد البوت — استرجاع 15% خسارة", refund);
    }
    // 3b. Frozen Forest (Emilia) → 25% refund on loss (was: absorb full loss)
    if (invHasActive(inv, "rz_frozen_forest")) {
      const refund = Math.floor(effectiveAmount * 0.25);
      effectiveAmount = effectiveAmount - refund;
      await invConsume(userId, "rz_frozen_forest");
      abilityMessages.push(`❄️ **Frozen Forest** — Emilia تسترجع 25% من خسارتك! (+${refund.toLocaleString("en-US")} كوين)`);
      await logAbilityEvent(userId, "rz_frozen_forest", "Re:Zero — استرجاع 25% خسارة", refund);
    }
    // 3c. Crystal Magic (Beatrice) → 25% refund on loss (was: absorb full loss)
    if (invHasActive(inv, "rz_crystal_magic")) {
      const refund = Math.floor(effectiveAmount * 0.25);
      effectiveAmount = effectiveAmount - refund;
      await invConsume(userId, "rz_crystal_magic");
      abilityMessages.push(`📚 **Crystal Magic** — Beatrice تسترجع 25% من خسارتك! (+${refund.toLocaleString("en-US")} كوين)`);
      await logAbilityEvent(userId, "rz_crystal_magic", "Re:Zero — استرجاع 25% خسارة", refund);
    }
    // Fortune Favor → 20% refund on loss (was: 30%)
    if (invHasActive(inv, "fortune_favor")) {
      const refund = Math.floor(effectiveAmount * 0.20);
      effectiveAmount = effectiveAmount - refund;
      await invConsume(userId, "fortune_favor");
      abilityMessages.push(`🎲 **Fortune Favor** — استُرجع 20% من الخسارة! (+${refund.toLocaleString("en-US")} كوين)`);
      await logAbilityEvent(userId, "fortune_favor", "لعبة ضد البوت — استرجاع 20%", refund);
    }
    // Witch Factor (Satella) → 25% refund on loss (was: 40%)
    if (invHasActive(inv, "rz_witch_factor")) {
      const refund = Math.floor(effectiveAmount * 0.25);
      effectiveAmount = effectiveAmount - refund;
      await invConsume(userId, "rz_witch_factor");
      abilityMessages.push(`🖤 **Witch Factor** — Satella تسترجع 25% من خسارتك! (+${refund.toLocaleString("en-US")} كوين)`);
      await logAbilityEvent(userId, "rz_witch_factor", "Re:Zero — استرجاع 25% خسارة", refund);
    }
    // Spirit Knight (Julius) → 30% loss reduction (was: 50%)
    if (invHasActive(inv, "rz_spirit_knight")) {
      const saved = Math.floor(effectiveAmount * 0.30);
      effectiveAmount = effectiveAmount - saved;
      await invConsume(userId, "rz_spirit_knight");
      abilityMessages.push(`⚜️ **Spirit Knight** — Julius يخفف 30% من خسارتك! (-${saved.toLocaleString("en-US")} كوين)`);
      await logAbilityEvent(userId, "rz_spirit_knight", "Re:Zero — خسارة خُففت 30%", saved);
    }
  }

  // 4. Double or Nothing → double the stakes (balanced — risks both ways)
  if (invHasActive(inv, "double_or_nothing")) {
    effectiveAmount = amount * 2;
    await invConsume(userId, "double_or_nothing");
    if (effectiveWon) abilityMessages.push("🎰 **Double or Nothing** — مبروك! الفوز تضاعف!");
    else if (!effectiveTied) abilityMessages.push("🎰 **Double or Nothing** — الرهان تضاعف... الخسارة أيضاً!");
  }

  // 5. Steal Blade → no tax on wins (time-based)
  let tax = Math.floor(effectiveAmount * taxRate);
  if (effectiveWon && invHasActive(inv, "steal_blade")) {
    tax = 0;
    abilityMessages.push("🗡️ **Steal Blade** — لا ضريبة على هذا الفوز!");
    await logAbilityEvent(userId, "steal_blade", "لعبة ضد البوت — الضريبة أُلغيت", effectiveAmount);
  }
  // 5b. Wind Reading (Crusch) → no tax on next win (one-time)
  if (effectiveWon && tax > 0 && invHasActive(inv, "rz_wind_reading")) {
    tax = 0;
    await invConsume(userId, "rz_wind_reading");
    abilityMessages.push("🌬️ **Wind Reading** — Crusch تُلغي الضريبة على هذا الفوز!");
    await logAbilityEvent(userId, "rz_wind_reading", "Re:Zero — ضريبة مُلغاة", effectiveAmount);
  }
  // 5c. Wind Blade (Ram) → 50% tax reduction (was: 75%)
  if (effectiveWon && tax > 0 && invHasActive(inv, "rz_wind_blade")) {
    tax = Math.floor(tax * 0.50);
    abilityMessages.push("🌸 **Wind Blade** — Ram تقلص الضريبة 50%!");
    await logAbilityEvent(userId, "rz_wind_blade", "Re:Zero — ضريبة مخفضة 50%", effectiveAmount);
  }
  // 6. Tax Shield → half tax on wins (3h)
  if (effectiveWon && tax > 0 && invHasActive(inv, "tax_shield")) {
    tax = Math.floor(tax * 0.5);
    abilityMessages.push("🪙 **Tax Shield** — الضريبة خُفّضت 50%!");
    await logAbilityEvent(userId, "tax_shield", "لعبة ضد البوت — ضريبة نصف", effectiveAmount);
  }

  // 7. Jackpot Token → 15% chance ×1.5 win (was: 20% chance ×2)
  if (effectiveWon && invHasActive(inv, "jackpot_token")) {
    await invConsume(userId, "jackpot_token");
    if (Math.random() < 0.15) {
      effectiveAmount = Math.floor(effectiveAmount * 1.5);
      abilityMessages.push(`🎟️ **Jackpot Token** — 🎰 حظّ عظيم! الفوز زاد 50%! (+${Math.floor(effectiveAmount * 0.5 / 1.5).toLocaleString("en-US")} كوين)`);
      await logAbilityEvent(userId, "jackpot_token", "لعبة ضد البوت — Jackpot! +50%", effectiveAmount);
    } else {
      abilityMessages.push("🎟️ **Jackpot Token** — للأسف لم تتفعّل هذه المرة!");
    }
  }
  // 7b. Water Demon Art (Rem) → +35% on win (was: guaranteed ×2)
  if (effectiveWon && invHasActive(inv, "rz_water_demon")) {
    const bonus = Math.floor(effectiveAmount * 0.35);
    effectiveAmount = effectiveAmount + bonus;
    await invConsume(userId, "rz_water_demon");
    abilityMessages.push(`💙 **Water Demon Art** — Rem تضيف 35% على فوزك! (+${bonus.toLocaleString("en-US")} كوين)`);
    await logAbilityEvent(userId, "rz_water_demon", "Re:Zero — فوز +35%", bonus);
  }
  // 7c. Great Magic (Roswaal) → +25% on win (was: +50%)
  if (effectiveWon && invHasActive(inv, "rz_great_magic")) {
    const bonus = Math.floor(effectiveAmount * 0.25);
    effectiveAmount = effectiveAmount + bonus;
    await invConsume(userId, "rz_great_magic");
    abilityMessages.push(`🎭 **Great Magic** — Roswaal يضيف 25% سحرية! (+${bonus.toLocaleString("en-US")} كوين)`);
    await logAbilityEvent(userId, "rz_great_magic", "Re:Zero — فوز +25%", bonus);
  }

  const prize = effectiveAmount - tax;

  if (effectiveWon) {
    data.coins = parseInt(data.coins) + prize;
  } else if (!effectiveTied) {
    data.coins = Math.max(0, parseInt(data.coins) - effectiveAmount);
    data.cashback = (parseInt(data.cashback) || 0) + Math.floor(effectiveAmount * 0.02);
  }

  data.status_playing = "no";
  await data.save();
  botChallenges.delete(userId);

  // Track win/loss/draw in profile stats
  if (effectiveWon) {
    await mafiaOnWin(userId, effectiveAmount).catch(() => {});
  } else if (!effectiveTied) {
    await mafiaOnLoss(userId, effectiveAmount).catch(() => {});
  } else {
    await mafiaOnDraw(userId).catch(() => {});
  }

  // Notify channel if abilities fired
  if (abilityMessages.length > 0 && channelId) {
    const ch = client.channels.cache.get(channelId);
    if (ch) {
      const notifEmbed = new Discord.MessageEmbed()
        .setColor("#032943")
        .setTitle("✨ تم تفعيل قدرة خاصة!")
        .setDescription(abilityMessages.join("\n"))
        .setFooter("نظام القدرات — Ability System");
      ch.send({ embeds: [notifEmbed] }).catch(() => {});
    }
  }

  return { prize, tax, won: effectiveWon, tied: effectiveTied };
}

