client.on("interactionCreate", async (interaction) => {
  if (!interaction.isButton()) return;
  if (!interaction.customId.startsWith("botdice_")) return;

  const userId = interaction.customId.replace("botdice_", "");
  if (interaction.user.id !== userId)
    return interaction.reply({
      content: "`❎` هذا التحدي ليس لك!",
      ephemeral: true,
    });

  const pending = botChallenges.get(userId);
  if (!pending || !pending.diceRolls)
    return interaction.reply({
      content: "`❎` لم يتم العثور على التحدي.",
      ephemeral: true,
    });

  await interaction.deferUpdate();

  const diceEmojis = ["⚀", "⚁", "⚂", "⚃", "⚄", "⚅"];
  const userRoll = Math.floor(Math.random() * 6) + 1;
  const botRoll = Math.floor(Math.random() * 6) + 1;
  pending.diceRolls.user.push(userRoll);
  pending.diceRolls.bot.push(botRoll);
  botChallenges.set(userId, pending);

  const rollCount = pending.diceRolls.user.length;
  const userSum = pending.diceRolls.user.reduce((a, b) => a + b, 0);
  const botSum = pending.diceRolls.bot.reduce((a, b) => a + b, 0);

  const userDisplay =
    pending.diceRolls.user.map((r) => diceEmojis[r - 1]).join(" ") +
    (rollCount < 3 ? " `؟`".repeat(3 - rollCount) : "");
  const botDisplay =
    pending.diceRolls.bot.map((r) => diceEmojis[r - 1]).join(" ") +
    (rollCount < 3 ? " `؟`".repeat(3 - rollCount) : "");

  if (rollCount < 3) {
    const embed = new Discord.MessageEmbed()
      .setColor("#032943")
      .setTitle("🎲 | لعبة النرد ضد البوت")
      .setDescription(
        `💰 **المبلغ:** \`${pending.amount.toLocaleString("en-US")}\`\n\n🎲 **الجولة ${rollCount} من 3**`,
      )
      .addFields(
        { name: "🤖 رميات البوت", value: botDisplay, inline: true },
        { name: "👤 رمياتك", value: userDisplay, inline: true },
        { name: "📊 المجموع الحالي", value: `🤖 البوت: \`${botSum}\`  |  👤 أنت: \`${userSum}\``, inline: false },
      )
      .setFooter(`${3 - rollCount} رميات متبقية`);

    const btn = new MessageButton()
      .setCustomId(`botdice_${userId}`)
      .setLabel(`🎲 ارمِ النرد (${rollCount}/3)`)
      .setStyle("PRIMARY");

    await interaction.editReply({
      embeds: [embed],
      components: [new MessageActionRow().addComponents(btn)],
    });
  } else {
    const won = userSum > botSum;
    const tied = userSum === botSum;
    const { prize, tax, won: fw, tied: ft } = await finishBotGame(
      userId,
      won,
      tied,
      pending.amount,
      interaction.channel.id,
    );

    const resultTitle = fw ? "🏆 فزتَ!" : ft ? "🤝 تعادل!" : "💀 خسرتَ!";
    const profitText = fw
      ? `+\`${prize.toLocaleString("en-US")}\` (بعد خصم ضريبة \`${tax.toLocaleString("en-US")}\`)`
      : ft
        ? "لا تغيير في رصيدك"
        : `-\`${pending.amount.toLocaleString("en-US")}\``;

    const embed = new Discord.MessageEmbed()
      .setColor(fw ? "#00FF7F" : ft ? "#FFA500" : "#FF4444")
      .setTitle(`🎲 | نتيجة النرد — ${resultTitle}`)
      .addFields(
        { name: "🤖 رميات البوت", value: botDisplay, inline: true },
        { name: "👤 رمياتك", value: userDisplay, inline: true },
        { name: "📊 النتيجة النهائية", value: `🤖 البوت: \`${botSum}\`  |  👤 أنت: \`${userSum}\``, inline: false },
        { name: "💰 المكسب / الخسارة", value: profitText, inline: false },
      )
      .setTimestamp();

    await interaction.editReply({ embeds: [embed], components: [] });
    await finalizePFGameSessionByChannel(
      interaction.channel.id,
      `dice userSum=${userSum} botSum=${botSum} won=${won ? "yes" : "no"} tied=${tied ? "yes" : "no"} amount=${pending.amount}`,
    );
  }
});

