// ── Bot takribi mode button handler ──
client.on("interactionCreate", async (interaction) => {
  if (!interaction.isButton()) return;
  if (!interaction.customId.startsWith("bottkmode_normal_") && !interaction.customId.startsWith("bottkmode_chorot_")) return;
  const isNormal = interaction.customId.startsWith("bottkmode_normal_");
  const userId   = interaction.customId.replace(isNormal ? "bottkmode_normal_" : "bottkmode_chorot_", "");
  if (interaction.user.id !== userId)
    return interaction.reply({ content: "`❎` هذا التحدي ليس لك!", ephemeral: true });
  const pending = botChallenges.get(userId);
  if (!pending)
    return interaction.reply({ content: "`❎` لم يتم العثور على التحدي.", ephemeral: true });
  if (isNormal) {
    await startBotTakribiGame(interaction, userId, pending);
  } else {
    await startBotTakribiChorotGame(interaction, userId, pending);
  }
});

// ── Bot Takribi Chorot Game ──
async function startBotTakribiChorotGame(interaction, userId, pending) {
  await interaction.deferUpdate();
  await createPFGameSessionFromContext({
    guildId: interaction.guild.id,
    channelId: interaction.channel.id,
    playerId: userId,
    opponentId: null,
    bet: pending.amount,
    gameType: "bot-takribi-chorot",
  });
  setActivePFGameType(interaction.channel.id, "الرقم التقريبي شروط");

  const nums = getTakribiNumbers();
  pending.takribi = {
    maxNum: nums.maxNum,
    a: nums.a, b: nums.b, c: nums.c, d: nums.d,
    userNumbers: [], userSum: 0, userDone: false,
    botNumbers: [], botSum: 0, botDone: false,
    currentTurn: "user",
    chorot: true,
    controlPhase: false,
    channelId: interaction.channel.id,
    msgId: null,
  };
  botChallenges.set(userId, pending);
  const tk = pending.takribi;
  const embed = buildBotTakribiChorotEmbed(pending);
  const msg = await interaction.editReply({
    content: "> 📊🔥 تقريبي شروط ضد البوت — دورك! اختر نطاقاً",
    embeds: [embed],
    components: buildBotTkChorotUserButtons(userId, tk),
  });
  tk.msgId = msg.id;
  botChallenges.set(userId, pending);
}

function buildBotTakribiChorotEmbed(pending) {
  const tk = pending.takribi;
  const userLine = tk.userNumbers.length
    ? `\`${tk.userNumbers.join(" + ")}\` = **${tk.userSum}**`
    : null;
  const botLine = tk.botNumbers.length
    ? `\`${tk.botNumbers.join(" + ")}\` = **${tk.botSum}**`
    : null;
  let userStatus, botStatus;
  if (tk.controlPhase) {
    userStatus = userLine
      ? `> ${userLine}\n> ❌ تجاوز — يتحكم في البوت!`
      : "> يتحكم في البوت!";
    botStatus = botLine
      ? `> ${botLine}\n> (يتحكم فيه اللاعب)`
      : "> (يتحكم فيه اللاعب)";
  } else if (tk.userDone) {
    userStatus = userLine ? `> ${userLine}\n> ✅ انتهى` : "> ✅ انتهى";
    botStatus = tk.botDone
      ? (botLine ? `> ${botLine}\n> ✅ انتهى` : "> ✅ انتهى")
      : (tk.currentTurn === "bot" ? (botLine ? `> ${botLine}\n> **Playing..**` : "> **Playing..**") : "> Waiting..");
  } else {
    userStatus = tk.currentTurn === "user"
      ? (userLine ? `> ${userLine}\n> **Playing..**` : "> **Playing..**")
      : (userLine ? `> ${userLine}\n> Waiting..` : "> Waiting..");
    botStatus = botLine ? `> ${botLine}\n> Waiting..` : "> Waiting..";
  }
  return new Discord.MessageEmbed()
    .setColor("#032943")
    .setTitle("📊🔥 تقريبي شروط ضد البوت")
    .setDescription(`اقصى رقم : **${tk.maxNum}**\nالمبلغ : **\`${pending.amount.toLocaleString("en-US")}\`**`)
    .addFields(
      { name: "👤 أنت", value: userStatus, inline: true },
      { name: "🤖 البوت", value: botStatus, inline: true },
    );
}

function buildBotTkChorotUserButtons(userId, tk) {
  return [
    new MessageActionRow().addComponents(
      new MessageButton().setCustomId(`bottk_low_${userId}`).setLabel(`${tk.a} - ${tk.b}`).setStyle("PRIMARY"),
      new MessageButton().setCustomId(`bottk_finish_${userId}`).setLabel("إنهاء دوري ✅").setStyle("SUCCESS"),
      new MessageButton().setCustomId(`bottk_high_${userId}`).setLabel(`${tk.c} - ${tk.d}`).setStyle("PRIMARY"),
    ),
  ];
}

function buildBotTkChorotControlButtons(userId, tk) {
  const canLow  = tk.a + tk.botSum <= tk.maxNum;
  const canHigh = tk.c + tk.botSum <= tk.maxNum;
  return [
    new MessageActionRow().addComponents(
      new MessageButton()
        .setCustomId(`bottk_low_${userId}`)
        .setLabel(`للبوت: ${tk.a} - ${tk.b}`)
        .setStyle(canLow ? "PRIMARY" : "DANGER")
        .setDisabled(!canLow),
      new MessageButton()
        .setCustomId(`bottk_finish_${userId}`)
        .setLabel("إنهاء دور البوت 🏳️")
        .setStyle("SECONDARY"),
      new MessageButton()
        .setCustomId(`bottk_high_${userId}`)
        .setLabel(`للبوت: ${tk.c} - ${tk.d}`)
        .setStyle(canHigh ? "PRIMARY" : "DANGER")
        .setDisabled(!canHigh),
    ),
  ];
}

async function resolveBotTakribiChorot(interaction, userId, pending) {
  const tk = pending.takribi;
  const { maxNum, userSum, botSum } = tk;
  const userOver = userSum > maxNum;
  const botOver  = botSum  > maxNum;

  let won = false, tied = false;
  if (userOver && botOver) {
    // both exceeded → draw
    tied = true;
  } else if (userOver && !botOver) {
    // user exceeded, user was controlling bot but didn't manage to tie → bot wins
    won = false;
  } else if (!userOver && botOver) {
    won = true;
  } else {
    // neither exceeded → compare totals
    const uDiff = maxNum - userSum;
    const bDiff = maxNum - botSum;
    if (uDiff < bDiff) won = true;
    else if (uDiff === bDiff) tied = true;
  }

  const { prize, tax, won: fw, tied: ft } = await finishBotGame(userId, won, tied, pending.amount, interaction ? interaction.channel.id : tk.channelId);
  const resultTitle = fw ? "🏆 فزتَ!" : ft ? "🤝 تعادل!" : "💀 خسرتَ!";
  const profitText  = fw
    ? `+\`${prize.toLocaleString("en-US")}\` (بعد خصم ضريبة \`${tax.toLocaleString("en-US")}\`)`
    : ft ? "لا تغيير في رصيدك" : `-\`${pending.amount.toLocaleString("en-US")}\``;

  const userDisplay = tk.userNumbers.length
    ? `\`${tk.userNumbers.join(" + ")}\` = **${userSum}**${userOver ? "  ✗ تجاوزت" : ""}`
    : "`—`";
  const botDisplay  = tk.botNumbers.length
    ? `\`${tk.botNumbers.join(" + ")}\` = **${botSum}**${botOver ? "  ✗ تجاوز" : ""}`
    : "`—`";

  const embed = new Discord.MessageEmbed()
    .setColor(fw ? "#57F287" : ft ? "#FEE75C" : "#ED4245")
    .setTitle(resultTitle)
    .setDescription(`اقصى رقم : **${maxNum}**\nالمبلغ : **\`${pending.amount.toLocaleString("en-US")}\`**`)
    .addFields(
      { name: "👤 أنت",   value: userDisplay, inline: true },
      { name: "🤖 البوت", value: botDisplay,  inline: true },
      { name: "الصافي",   value: profitText,  inline: false },
    )
    .setTimestamp();

  if (interaction) {
    await interaction.editReply({ embeds: [embed], components: [] });
  } else {
    await editBotTkMsg(tk, null, embed, []);
  }
  await finalizePFGameSessionByChannel(
    tk.channelId,
    `takribi-chorot userSum=${userSum} botSum=${botSum} max=${maxNum} won=${won ? "yes" : "no"} tied=${tied ? "yes" : "no"} amount=${pending.amount}`,
  );
}

