client.on("interactionCreate", async (interaction) => {
  if (!interaction.isButton()) return;
  if (!interaction.customId.startsWith("bothilo_")) return;

  const parts = interaction.customId.split("_");
  const userId = parts[1];
  const choice = parts[2];

  if (interaction.user.id !== userId)
    return interaction.reply({
      content: "`❎` هذا التحدي ليس لك!",
      ephemeral: true,
    });

  const pending = botChallenges.get(userId);
  if (!pending || !pending.hilo)
    return interaction.reply({
      content: "`❎` لم يتم العثور على التحدي.",
      ephemeral: true,
    });

  await interaction.deferUpdate();

  const hilo = pending.hilo;
  const next = Math.floor(Math.random() * 10) + 1;
  const correct =
    (choice === "higher" && next > hilo.current) ||
    (choice === "lower" && next < hilo.current);

  if (correct) hilo.correct++;
  hilo.round++;
  const prevNum = hilo.current;
  hilo.current = next;
  botChallenges.set(userId, pending);

  const choiceLabel = choice === "higher" ? "أعلى ↑" : "أقل ↓";
  const resultMark = correct ? "✅" : "✗";
  const resultLine = `${resultMark}  اخترت **${choiceLabel}** — الرقم كان **\`${next}\`**`;

  if (
    hilo.round > 3 ||
    hilo.correct >= 2 ||
    (hilo.round > 1 && 3 - hilo.round + 1 < 2 - hilo.correct)
  ) {
    const won = hilo.correct >= 2;
    const { prize, tax, won: fw } = await finishBotGame(
      userId,
      won,
      false,
      pending.amount,
      interaction.channel.id,
    );
    const profitText = fw
      ? `+\`${prize.toLocaleString("en-US")}\`  (ضريبة \`${tax.toLocaleString("en-US")}\`)`
      : `-\`${pending.amount.toLocaleString("en-US")}\``;

    const embed = new Discord.MessageEmbed()
      .setColor(fw ? "#57F287" : "#ED4245")
      .setTitle(`🔢  أعلى أم أقل — ${fw ? "فزتَ" : "خسرتَ"}`)
      .setDescription(
        `${resultLine}\n> 💰 المبلغ : **\`${pending.amount.toLocaleString("en-US")}\`**\n> 🎯 صواب : **${hilo.correct} / 3**\n━━━━━━━━━━━━━━━━━━━━`,
      )
      .addFields({ name: "الصافي", value: profitText, inline: false })
      .setTimestamp();

    await interaction.editReply({ embeds: [embed], components: [] });
    return await finalizePFGameSessionByChannel(
      interaction.channel.id,
      `hilo correct=${hilo.correct}/3 won=${won ? "yes" : "no"} amount=${pending.amount}`,
    );
  }

  const embed = new Discord.MessageEmbed()
    .setColor("#032943")
    .setTitle("🔢  أعلى أم أقل")
    .setDescription(
      `${resultLine}\n> 🎲 الرقم الحالي : **\`${next}\`**\n━━━━━━━━━━━━━━━━━━━━\nهل الرقم التالي أعلى أم أقل؟\nالجولة  **${hilo.round} / 3**  •  صواب : **${hilo.correct}**`,
    );

  const btnH = new MessageButton()
    .setCustomId(`bothilo_${userId}_higher`)
    .setLabel("أعلى ↑")
    .setStyle("SUCCESS");
  const btnL = new MessageButton()
    .setCustomId(`bothilo_${userId}_lower`)
    .setLabel("أقل ↓")
    .setStyle("DANGER");

  await interaction.editReply({
    embeds: [embed],
    components: [new MessageActionRow().addComponents(btnH, btnL)],
  });
});

