client.on("interactionCreate", async (interaction) => {
  if (!interaction.isButton()) return;
  if (!interaction.customId.startsWith("botroul_")) return;

  const parts = interaction.customId.split("_");
  const userId = parts[1];
  const choice = parts[2];

  if (interaction.user.id !== userId)
    return interaction.reply({
      content: "`❎` هذا التحدي ليس لك!",
      ephemeral: true,
    });

  const pending = botChallenges.get(userId);
  if (!pending)
    return interaction.reply({
      content: "`❎` لم يتم العثور على التحدي.",
      ephemeral: true,
    });

  await interaction.deferUpdate();

  const spin = Math.floor(Math.random() * 37);
  const color = spin === 0 ? "zero" : ROULETTE_RED.has(spin) ? "red" : "black";
  const isOdd = spin !== 0 && spin % 2 !== 0;

  const colorLabel =
    color === "red" ? "أحمر" : color === "black" ? "أسود" : "—";
  const parityLabel = spin === 0 ? "—" : isOdd ? "فردي" : "زوجي";
  const spinLabel =
    spin === 0 ? "`0`  (بيت)" : `\`${spin}\`  ${colorLabel} — ${parityLabel}`;
  const choiceLabel = choice === "odd" ? "فردي" : "زوجي";
  const won =
    spin !== 0 &&
    ((choice === "odd" && isOdd) || (choice === "even" && !isOdd));

  const { prize, tax, won: fw } = await finishBotGame(
    userId,
    won,
    false,
    pending.amount,
    interaction.channel.id,
  );
  const profitText = fw
    ? `+\`${prize.toLocaleString("en-US")}\`  (ضريبة \`${tax.toLocaleString("en-US")}\`)`
    : `-\`${pending.amount.toLocaleString("en-US")}\``;

  const resultLabel = spin === 0 ? "خسرتَ — البيت" : fw ? "فزتَ" : "خسرتَ";
  const embed = new Discord.MessageEmbed()
    .setColor(fw ? "#57F287" : "#ED4245")
    .setTitle(`🎡  الروليت — ${resultLabel}`)
    .setDescription(
      `> 🎰 الرقم الذي ظهر : ${spinLabel}\n> 🎯 اخترت : **${choiceLabel}**\n> 💰 المبلغ : **\`${pending.amount.toLocaleString("en-US")}\`**\n━━━━━━━━━━━━━━━━━━━━`,
    )
    .addFields({ name: "الصافي", value: profitText, inline: false })
    .setTimestamp();

  await interaction.editReply({ embeds: [embed], components: [] });
  await finalizePFGameSessionByChannel(
    interaction.channel.id,
    `roulette spin=${spin} choice=${choice} won=${won ? "yes" : "no"} amount=${pending.amount}`,
  );
});

