// ─── bj2_* : in-game buttons (all ephemeral) ─────────────────
client.on("interactionCreate", async (interaction) => {
  if (!interaction.isButton()) return;
  if (!interaction.customId.startsWith("bj2_")) return;

  // customId: bj2_{action}_{player}_{msgID}
  const rest = interaction.customId.slice("bj2_".length); // e.g. "hit_p1_123456"
  const parts = rest.split("_");
  const action = parts[0]; // hit | stand | view
  const player = parts[1]; // p1 | p2
  const msgID = parts.slice(2).join("_");

  const bj = pvpBJGames.get(msgID);
  if (!bj)
    return interaction.reply({
      content: "> ❌ اللعبة انتهت أو انتهت صلاحيتها.",
      ephemeral: true,
    });

  const isP1 = interaction.user.id === bj.p1id;
  const isP2 = interaction.user.id === bj.p2id;
  if (!isP1 && !isP2)
    return interaction.reply({
      content: "> ❌ هذه اللعبة ليست لك!",
      ephemeral: true,
    });
  if (player === "p1" && !isP1)
    return interaction.reply({
      content: "> ❌ هذا زر اللاعب الأول — ليس زرك!",
      ephemeral: true,
    });
  if (player === "p2" && !isP2)
    return interaction.reply({
      content: "> ❌ هذا زر اللاعب الثاني — ليس زرك!",
      ephemeral: true,
    });

  const isThisP1 = player === "p1";
  const myDone = isThisP1 ? bj.p1done : bj.p2done;
  const myHand = isThisP1 ? bj.p1hand : bj.p2hand;

  // View is always allowed
  if (action === "view")
    return interaction.reply({
      embeds: [bjMyHandEmbed(bj, isThisP1)],
      ephemeral: true,
    });

  if (myDone !== null)
    return interaction.reply({
      content: "> ✅ لقد وقفت بالفعل أو انهرت!",
      ephemeral: true,
    });

  await interaction.deferReply({ ephemeral: true });

  if (action === "hit") {
    myHand.push(bjDeal(bj.deck));
    const val = bjHandValue(myHand);
    if (val > 21) {
      if (isThisP1) bj.p1done = "bust";
      else bj.p2done = "bust";
    } else if (val === 21) {
      if (isThisP1) bj.p1done = "stand";
      else bj.p2done = "stand";
    }
  } else {
    if (isThisP1) bj.p1done = "stand";
    else bj.p2done = "stand";
  }

  pvpBJGames.set(msgID, bj);
  await interaction.editReply({ embeds: [bjMyHandEmbed(bj, isThisP1)] });

  // Update the public board
  const ch = client.channels.cache.get(bj.channelID);
  const msg1 = ch ? await ch.messages.fetch(msgID).catch(() => null) : null;

  if (bj.p1done && bj.p2done) {
    if (msg1)
      await msg1
        .edit({
          embeds: [bjPublicEmbed(bj)],
          components: [],
          content: "> ⏳ الديلر يلعب...",
        })
        .catch(() => {});
    setTimeout(() => bjDealerFinish(msgID, bj, ch), 2000);
  } else {
    if (msg1)
      await msg1
        .edit({
          embeds: [bjPublicEmbed(bj)],
          components: bjGameRows(msgID, bj),
          content: `> <@${bj.p1id}> <@${bj.p2id}> — اضغطوا أزرار اللعب! 🃏`,
        })
        .catch(() => {});
  }
});

// ─── Dealer plays + settle ────────────────────────────────────
async function bjDealerFinish(msgID, bj, ch) {
  while (bjHandValue(bj.dealerHand) < 17) bj.dealerHand.push(bjDeal(bj.deck));

  const winner = bjDetermineWinner(bj);
  const p1v = bjHandValue(bj.p1hand);
  const p2v = bjHandValue(bj.p2hand);
  const dv = bjHandValue(bj.dealerHand);
  const coins = parseInt(bj.coins);
  const bjWinnerId = winner === "p1" ? bj.p1id : winner === "p2" ? bj.p2id : null;
  const bjLoserId  = winner === "p1" ? bj.p2id : winner === "p2" ? bj.p1id : null;
  const tax = bjWinnerId ? await calcTax(bjWinnerId, coins) : Math.floor(coins * taxRate);
  const prize = coins - tax;

  let p1d = 0,
    p2d = 0;
  if (winner === "p1") {
    p1d = +prize;
    p2d = -coins;
  } else if (winner === "p2") {
    p1d = -coins;
    p2d = +prize;
  }

  let dp1 = await db.findOne({ id: bj.p1id });
  if (!dp1)
    dp1 = await db.create({ id: bj.p1id, coins: 0, status_playing: "no" });
  let dp2 = await db.findOne({ id: bj.p2id });
  if (!dp2)
    dp2 = await db.create({ id: bj.p2id, coins: 0, status_playing: "no" });
  dp1.coins = parseInt(dp1.coins) + p1d;
  dp1.status_playing = "no";
  await dp1.save();
  dp2.coins = parseInt(dp2.coins) + p2d;
  dp2.status_playing = "no";
  await dp2.save();

  if (bjWinnerId && bjLoserId) {
    await mafiaOnWin(bjWinnerId, coins).catch(() => {});
    await mafiaOnLoss(bjLoserId, coins).catch(() => {});
  } else if (winner === "draw") {
    await mafiaOnDraw(bj.p1id).catch(() => {});
    await mafiaOnDraw(bj.p2id).catch(() => {});
  }

  await game.findOneAndDelete({ msgID });
  pvpBJGames.delete(msgID);

  function vsD(pv, pbj) {
    if (pbj && !bjIsBlackjack(bj.dealerHand)) return "🃏 بلاك جاك";
    if (pv > 21) return "💥 انهار";
    if (dv > 21 || pv > dv) return "✅ فاز على الديلر";
    if (pv === dv) return "🤝 تعادل";
    return "❌ خسر للديلر";
  }
  function dStr(d) {
    if (d > 0) return `**+${d.toLocaleString("en-US")}** 🟢`;
    if (d < 0) return `**−${Math.abs(d).toLocaleString("en-US")}** 🔴`;
    return "**±0** ⚪";
  }

  const p1bj = bjIsBlackjack(bj.p1hand);
  const p2bj = bjIsBlackjack(bj.p2hand);
  const winLabel =
    winner === "p1"
      ? `🏆 ${bj.p1tag} يفوز!`
      : winner === "p2"
        ? `🏆 ${bj.p2tag} يفوز!`
        : "🤝 تعادل!";

  const finalEmbed = new Discord.MessageEmbed()
    .setColor(winner === "draw" ? "#E67E00" : "#FFD700")
    .setTitle(`🃏  نتيجة البلاك جاك — ${winLabel}`)
    .setDescription(
      `> 💰 **المبلغ:** \`${coins.toLocaleString("en-US")}\`  |  💸 **ضريبة:** \`${tax.toLocaleString("en-US")}\`\n\n` +
        `🏦 **الديلر:** ${bjHandStr(bj.dealerHand)}  **= ${dv}${dv > 21 ? " 💥" : ""}**\n` +
        `━━━━━━━━━━━━━━━━━━━━━━━━`,
    )
    .addFields(
      {
        name: `${winner === "p1" ? "🏆" : "👤"} ${bj.p1tag}`,
        value: `${bjHandStr(bj.p1hand)} = **${p1v}**\n${vsD(p1v, p1bj)} | ${dStr(p1d)}`,
        inline: true,
      },
      {
        name: `${winner === "p2" ? "🏆" : "👤"} ${bj.p2tag}`,
        value: `${bjHandStr(bj.p2hand)} = **${p2v}**\n${vsD(p2v, p2bj)} | ${dStr(p2d)}`,
        inline: true,
      },
    )
    .setTimestamp();

  const targetCh = ch || client.channels.cache.get(bj.channelID);
  if (targetCh) {
    const msg1 = await targetCh.messages.fetch(msgID).catch(() => null);
    if (msg1)
      await msg1
        .edit({
          embeds: [finalEmbed],
          components: [],
          content: `> || <@${bj.p1id}> | <@${bj.p2id}> ||`,
        })
        .catch(console.error);
  }

  await finalizePFGameSessionByChannel(
    bj.channelID,
    `blackjack winner=${winner} p1=${bj.p1tag} p2=${bj.p2tag} amount=${coins}`,
  );
}

// ================================================================
// MEMORY MATCH GAME - مطابقة الذاكرة
// ================================================================

const MM_EMOJIS = ["🍎", "🍊", "🍋", "🍇", "🎯", "🎲", "💎", "🃏"];

function mmShuffle() {
  const cards = [...MM_EMOJIS, ...MM_EMOJIS];
  for (let i = cards.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [cards[i], cards[j]] = [cards[j], cards[i]];
  }
  return cards;
}

function mmBuildRows(cards, matched, flippedIdx, msgID) {
  const rows = [];
  for (let r = 0; r < 4; r++) {
    const btns = [];
    for (let c = 0; c < 4; c++) {
      const i = r * 4 + c;
      const isMatched = matched[i] === 1;
      const isFlipped = i === flippedIdx;
      let label = isMatched || isFlipped ? cards[i] : "🎴";
      let style = isMatched ? "SUCCESS" : isFlipped ? "SECONDARY" : "PRIMARY";
      btns.push(
        new MessageButton()
          .setCustomId(`mmcard_${msgID}_${i}`)
          .setLabel(label)
          .setStyle(style)
          .setDisabled(isMatched),
      );
    }
    rows.push(new MessageActionRow().addComponents(btns));
  }
  return rows;
}

function mmBuildEmbed(score1, score2, p1tag, p2tag, currentTurnId, p1id) {
  const turnName = currentTurnId === p1id ? p1tag : p2tag;
  return new Discord.MessageEmbed()
    .setColor("#032943")
    .setTitle("🧠 لعبة مطابقة الذاكرة")
    .addFields(
      { name: p1tag, value: `> النقاط: **${score1}**`, inline: true },
      { name: p2tag, value: `> النقاط: **${score2}**`, inline: true },
      { name: "الدور الحالي", value: `> **${turnName}**`, inline: false },
    );
}

