// Memory Match — card flip handler
client.on("interactionCreate", async (interaction) => {
  if (!interaction.isButton()) return;
  if (!interaction.customId.startsWith("mmcard_")) return;

  const parts = interaction.customId.split("_");
  if (parts.length !== 3) return;
  const msgID = parts[1];
  const cardIdx = parseInt(parts[2]);

  // Race-condition lock
  if (processingGames.has(msgID)) {
    return interaction.reply({ content: "> ⏳ جاري معالجة النقرة السابقة، انتظر لحظة!", ephemeral: true });
  }
  processingGames.add(msgID);
  // Safety: auto-release lock after 8s no matter what
  const _mmLockTimer = setTimeout(() => processingGames.delete(msgID), 8000);
  const _mmRelease = () => { clearTimeout(_mmLockTimer); processingGames.delete(msgID); };

  // Defer IMMEDIATELY before any async work to stay within Discord's 3-second window
  try { await interaction.deferReply({ ephemeral: true }); } catch { _mmRelease(); return; }

  let mmdata = await mmgame.findOne({ msgID });
  if (!mmdata) { _mmRelease(); return; }

  if (interaction.user.id !== mmdata.currentTurn) {
    _mmRelease();
    return interaction.editReply({
      content: "> ⏳ انه ليس دورك!",
    });
  }

  if (mmdata.matched[cardIdx] === 1) {
    _mmRelease();
    return interaction.editReply({
      content: "> هذه البطاقة تم مطابقتها بالفعل!",
    });
  }

  if (mmdata.flippedIdx === cardIdx) {
    _mmRelease();
    return interaction.editReply({
      content: "> لا يمكنك اختيار نفس البطاقة مرتين!",
    });
  }

  let gdata = await game.findOne({ msgID });
  if (!gdata) {
    _mmRelease();
    return interaction.editReply({
      content: "> ❌ انتهت الجلسة.",
    });
  }

  gdata.time = timestamp(moment(ms("120s")) + Date.now());
  await gdata.save();

  const stusrgame = client.users.cache.get(mmdata.player1);
  const wthusrgame = client.users.cache.get(mmdata.player2);
  const cards = [...mmdata.cards];
  const matched = [...mmdata.matched];

  if (mmdata.flippedIdx === -1) {
    // First card of this turn — show it and wait for second
    mmdata.flippedIdx = cardIdx;
    mmdata.markModified("flippedIdx");
    await mmdata.save();

    const embed = mmBuildEmbed(
      mmdata.score1,
      mmdata.score2,
      stusrgame.tag,
      wthusrgame.tag,
      mmdata.currentTurn,
      mmdata.player1,
    );
    const rows = mmBuildRows(cards, matched, cardIdx, msgID);

    client.channels.cache
      .get(interaction.channel.id)
      .messages.fetch(msgID)
      .then((msg) =>
        msg.edit({
          embeds: [embed],
          content: `> <@${mmdata.currentTurn}> اكشف البطاقة الثانية!`,
          components: rows,
        }),
      )
      .catch((err) => console.error(err));

    await interaction.editReply({
      content: `> كشفت: **${cards[cardIdx]}** — اختر البطاقة الثانية!`,
      ephemeral: true,
    });
  } else {
    // Second card — check match
    const firstIdx = mmdata.flippedIdx;
    const isMatch = cards[firstIdx] === cards[cardIdx];

    if (isMatch) {
      matched[firstIdx] = 1;
      matched[cardIdx] = 1;
      const isPlayer1 = mmdata.currentTurn === mmdata.player1;
      if (isPlayer1) mmdata.score1 += 1;
      else mmdata.score2 += 1;

      mmdata.matched = matched;
      mmdata.markModified("matched");
      mmdata.flippedIdx = -1;
      await mmdata.save();

      const totalPairs = matched.filter((v) => v === 1).length / 2;

      if (totalPairs >= 8) {
        // Game over
        const winner =
          mmdata.score1 > mmdata.score2
            ? mmdata.player1
            : mmdata.score2 > mmdata.score1
              ? mmdata.player2
              : null;

        const finalEmbed = new Discord.MessageEmbed()
          .setColor("#032943")
          .setTitle("🧠 انتهت لعبة مطابقة الذاكرة!")
          .addFields(
            {
              name: stusrgame.tag,
              value: `> **${mmdata.score1}** أزواج`,
              inline: true,
            },
            {
              name: wthusrgame.tag,
              value: `> **${mmdata.score2}** أزواج`,
              inline: true,
            },
          );

        const finalRows = mmBuildRows(cards, matched, -1, msgID);
        let resultText;

        if (winner) {
          const loser = winner === mmdata.player1 ? mmdata.player2 : mmdata.player1;
          const bet = parseInt(gdata.coins);
          const taxAmt = await calcTax(winner, bet);
          const total = bet - taxAmt;

          let wData = await db.findOne({ id: winner });
          if (!wData)
            wData = await db.create({
              id: winner,
              coins: 0,
              status_playing: "no",
            });
          let lData = await db.findOne({ id: loser });
          if (!lData)
            lData = await db.create({
              id: loser,
              coins: 0,
              status_playing: "no",
            });

          wData.coins = parseInt(wData.coins) + parseInt(total);
          await wData.save();
          lData.coins = parseInt(lData.coins) - bet;
          await lData.save();
          wData.status_playing = "no";
          await wData.save();
          lData.status_playing = "no";
          await lData.save();
          await mafiaOnWin(winner, bet).catch(() => {});
          await mafiaOnLoss(loser, bet).catch(() => {});

          const winnerUser =
            winner === mmdata.player1 ? stusrgame : wthusrgame;
          const loserUser =
            loser === mmdata.player1 ? stusrgame : wthusrgame;
          const winScore =
            winner === mmdata.player1 ? mmdata.score1 : mmdata.score2;
          const loseScore =
            loser === mmdata.player1 ? mmdata.score1 : mmdata.score2;
          resultText = `🏆 ${winnerUser} فائزززز! بـ **${winScore}** أزواج!\n${loserUser} خسر بـ **${loseScore}** أزواج!\nاللعبة: **مطابقة الذاكرة**, المبلغ: **${bet.toLocaleString("en-US")}**\n> || ${stusrgame} | ${wthusrgame} ||`;
        } else {
          // Draw
          let d1 = await db.findOne({ id: mmdata.player1 });
          if (d1) {
            d1.status_playing = "no";
            await d1.save();
          }
          let d2 = await db.findOne({ id: mmdata.player2 });
          if (d2) {
            d2.status_playing = "no";
            await d2.save();
          }
          resultText = `🤝 تعادل! كلاهما حصل على **4 أزواج**!\nاللعبة: **مطابقة الذاكرة**, المبلغ: **${parseInt(gdata.coins).toLocaleString("en-US")}**\n> || ${stusrgame} | ${wthusrgame} ||`;
        }

        client.channels.cache
          .get(interaction.channel.id)
          .messages.fetch(msgID)
          .then((msg) =>
            msg.edit({
              embeds: [finalEmbed],
              content: resultText,
              components: finalRows,
            }),
          )
          .catch((err) => console.error(err));

        await finalizePFGameSessionByChannel(
          interaction.channel.id,
          resultText,
        );

        await mmgame.findOneAndDelete({ msgID });
        await game.findOneAndDelete({
          id: gdata.id,
          with: gdata.with,
          msgID,
        });

        await interaction.editReply({
          content: `> تطابق! 🎉 **${cards[cardIdx]}** — انتهت اللعبة!`,
          ephemeral: true,
        });
      } else {
        // Game continues — same player goes again on match
        const embed = mmBuildEmbed(
          mmdata.score1,
          mmdata.score2,
          stusrgame.tag,
          wthusrgame.tag,
          mmdata.currentTurn,
          mmdata.player1,
        );
        const rows = mmBuildRows(cards, matched, -1, msgID);

        client.channels.cache
          .get(interaction.channel.id)
          .messages.fetch(msgID)
          .then((msg) =>
            msg.edit({
              embeds: [embed],
              content: `> <@${mmdata.currentTurn}> تطابق! 🎉 دورك مجدداً!`,
              components: rows,
            }),
          )
          .catch((err) => console.error(err));

        await interaction.editReply({
          content: `> تطابق! 🎉 **${cards[firstIdx]}** = **${cards[cardIdx]}** — نقطة لك! استمر في دورك.`,
          ephemeral: true,
        });
      }
    } else {
      // No match — switch turn
      mmdata.flippedIdx = -1;
      mmdata.currentTurn =
        mmdata.currentTurn === mmdata.player1 ? mmdata.player2 : mmdata.player1;
      await mmdata.save();

      const newTurnUser = client.users.cache.get(mmdata.currentTurn);
      const embed = mmBuildEmbed(
        mmdata.score1,
        mmdata.score2,
        stusrgame.tag,
        wthusrgame.tag,
        mmdata.currentTurn,
        mmdata.player1,
      );
      const rows = mmBuildRows(cards, matched, -1, msgID);

      client.channels.cache
        .get(interaction.channel.id)
        .messages.fetch(msgID)
        .then((msg) =>
          msg.edit({
            embeds: [embed],
            content: `> ${newTurnUser} دورك الآن! 🎴`,
            components: rows,
          }),
        )
        .catch((err) => console.error(err));

      await interaction.editReply({
        content: `> لا تطابق! **${cards[firstIdx]}** ≠ **${cards[cardIdx]}** — انتهى دورك.`,
        ephemeral: true,
      });
    }
  }
  _mmRelease();
});

