// Split or Steal — choice handler (split)
client.on("interactionCreate", async (interaction) => {
  if (!interaction.isButton()) return;
  if (!interaction.customId.startsWith("sossplit_")) return;
  const msgID = interaction.customId.slice("sossplit_".length);
  await handleSOSChoice(interaction, msgID, "split");
});

// Split or Steal — choice handler (steal)
client.on("interactionCreate", async (interaction) => {
  if (!interaction.isButton()) return;
  if (!interaction.customId.startsWith("sossteal_")) return;
  const msgID = interaction.customId.slice("sossteal_".length);
  await handleSOSChoice(interaction, msgID, "steal");
});

async function handleSOSChoice(interaction, msgID, choice) {
  let sosdata = await sosGame.findOne({ msgID });
  if (!sosdata) return;

  const userId = interaction.user.id;
  const isPlayer1 = userId === sosdata.player1;
  const isPlayer2 = userId === sosdata.player2;

  if (!isPlayer1 && !isPlayer2) {
    return interaction.reply({
      content: "> ❌ أنت لست جزءاً من هذا التحدي!",
      ephemeral: true,
    });
  }

  // Check if they already chose
  if (isPlayer1 && sosdata.choice1 !== null) {
    return interaction.reply({
      content: "> ⚠️ لقد اخترت بالفعل! انتظر قرار الخصم.",
      ephemeral: true,
    });
  }
  if (isPlayer2 && sosdata.choice2 !== null) {
    return interaction.reply({
      content: "> ⚠️ لقد اخترت بالفعل! انتظر قرار الخصم.",
      ephemeral: true,
    });
  }

  await interaction.deferReply({ ephemeral: true });

  if (isPlayer1) {
    sosdata.choice1 = choice;
    sosdata.markModified("choice1");
  } else {
    sosdata.choice2 = choice;
    sosdata.markModified("choice2");
  }
  await sosdata.save();

  const choiceLabel = choice === "split" ? "تقاسم 🤝" : "سرقة 💰";
  await interaction.editReply({
    content: `> ✅ اخترت **${choiceLabel}**! انتظر قرار خصمك...`,
    ephemeral: true,
  });

  // Reload to get latest choices
  sosdata = await sosGame.findOne({ msgID });
  if (!sosdata) return;

  if (sosdata.choice1 !== null && sosdata.choice2 !== null) {
    // Both have chosen — resolve the game
    let gdata = await game.findOne({ msgID });
    if (!gdata) return;

    const stusrgame = client.users.cache.get(sosdata.player1);
    const wthusrgame = client.users.cache.get(sosdata.player2);
    const bet = parseInt(gdata.coins);
    const taxAmt = await calcTax(winnerId || sosdata.player1, bet);
    const afterTax = bet - taxAmt;

    const c1 = sosdata.choice1;
    const c2 = sosdata.choice2;

    let resultDesc, colorResult, winnerId, loserId, bothSplit, bothSteal;

    if (c1 === "split" && c2 === "split") {
      bothSplit = true;
      colorResult = "GREEN";
      const eachGets = Math.floor(afterTax / 2);
      resultDesc =
        `🤝 **كلاهما اختار التقاسم!**\n\n` +
        `${stusrgame.tag}: تقاسم 🤝\n` +
        `${wthusrgame.tag}: تقاسم 🤝\n\n` +
        `يحصل كل لاعب على **${eachGets.toLocaleString("en-US")}** (المبلغ ÷ 2 - ضريبة)\nاللعبة: **تقاسم أو سرقة**, المبلغ: **${bet.toLocaleString("en-US")}**`;
    } else if (c1 === "steal" && c2 === "steal") {
      bothSteal = true;
      colorResult = "RED";
      resultDesc =
        `⚔️ **كلاهما اختار السرقة!**\n\n` +
        `${stusrgame.tag}: سرقة 💰\n` +
        `${wthusrgame.tag}: سرقة 💰\n\n` +
        `لا أحد يحصل على شيء — يخسر الجميع المبلغ!\nاللعبة: **تقاسم أو سرقة**, المبلغ: **${bet.toLocaleString("en-US")}**`;
    } else if (c1 === "steal" && c2 === "split") {
      winnerId = sosdata.player1;
      loserId = sosdata.player2;
      colorResult = "ORANGE";
      resultDesc =
        `💰 **${stusrgame.tag} سرق!**\n\n` +
        `${stusrgame.tag}: سرقة 💰\n` +
        `${wthusrgame.tag}: تقاسم 🤝\n\n` +
        `${stusrgame.tag} يحصل على كل المبلغ: **${afterTax.toLocaleString("en-US")}**\n${wthusrgame.tag} لا يحصل على شيء!\nاللعبة: **تقاسم أو سرقة**, المبلغ: **${bet.toLocaleString("en-US")}**`;
    } else {
      // c1 === 'split' && c2 === 'steal'
      winnerId = sosdata.player2;
      loserId = sosdata.player1;
      colorResult = "ORANGE";
      resultDesc =
        `💰 **${wthusrgame.tag} سرق!**\n\n` +
        `${stusrgame.tag}: تقاسم 🤝\n` +
        `${wthusrgame.tag}: سرقة 💰\n\n` +
        `${wthusrgame.tag} يحصل على كل المبلغ: **${afterTax.toLocaleString("en-US")}**\n${stusrgame.tag} لا يحصل على شيء!\nاللعبة: **تقاسم أو سرقة**, المبلغ: **${bet.toLocaleString("en-US")}**`;
    }

    const resultEmbed = new Discord.MessageEmbed()
      .setColor(colorResult)
      .setTitle("🤝 نتيجة لعبة تقاسم أو سرقة!")
      .setDescription(resultDesc);

    client.channels.cache
      .get(gdata.channelID)
      .messages.fetch(msgID)
      .then((msg) =>
        msg.edit({
          embeds: [resultEmbed],
          content: `> || ${stusrgame} | ${wthusrgame} ||`,
          components: [],
        }),
      )
      .catch((err) => console.error(err));

    await finalizePFGameSessionByChannel(gdata.channelID, resultDesc);

    // Apply coin changes
    let d1 = await db.findOne({ id: sosdata.player1 });
    if (!d1)
      d1 = await db.create({
        id: sosdata.player1,
        coins: 0,
        status_playing: "no",
      });
    let d2 = await db.findOne({ id: sosdata.player2 });
    if (!d2)
      d2 = await db.create({
        id: sosdata.player2,
        coins: 0,
        status_playing: "no",
      });

    if (bothSplit) {
      // Each gets back half of afterTax — net each pays half tax
      const eachGets = Math.floor(afterTax / 2);
      d1.coins = parseInt(d1.coins) + eachGets - bet;
      d2.coins = parseInt(d2.coins) + eachGets - bet;
    } else if (bothSteal) {
      d1.coins = parseInt(d1.coins) - bet;
      d2.coins = parseInt(d2.coins) - bet;
    } else if (winnerId === sosdata.player1) {
      d1.coins = parseInt(d1.coins) + afterTax;
      d2.coins = parseInt(d2.coins) - bet;
    } else {
      d1.coins = parseInt(d1.coins) - bet;
      d2.coins = parseInt(d2.coins) + afterTax;
    }

    await d1.save();
    await d2.save();
    d1.status_playing = "no";
    await d1.save();
    d2.status_playing = "no";
    await d2.save();

    // Stats tracking for !profilo
    if (!bothSplit && !bothSteal && winnerId && loserId) {
      await mafiaOnWin(winnerId, bet).catch(() => {});
      await mafiaOnLoss(loserId, bet).catch(() => {});
    } else if (bothSplit || bothSteal) {
      await mafiaOnDraw(sosdata.player1).catch(() => {});
      await mafiaOnDraw(sosdata.player2).catch(() => {});
    }

    await sosGame.findOneAndDelete({ msgID });
    await game.findOneAndDelete({
      id: gdata.id,
      with: gdata.with,
      msgID,
    });
  }
}

client.on("messageCreate", async (message) => {
  const args = message.content.trim().split(/\s+/);
  if (args[0]?.toLowerCase() !== "tax") return;

  const parseAmountInput = (input) => {
    if (!input) return NaN;
    const clean = String(input).trim().toLowerCase().replace(/,/g, "");
    const match = clean.match(/^(\d+(?:\.\d+)?)([a-z\u0600-\u06FF]*)$/);
    if (!match) return NaN;
    const base = Number(match[1]);
    if (Number.isNaN(base) || base <= 0) return NaN;

    const suffix = match[2];
    if (!suffix) return Math.floor(base);

    if (suffix === "k" || suffix === "ك") return Math.floor(base * 1_000);
    if (suffix === "m" || suffix === "م") return Math.floor(base * 1_000_000);

    return NaN;
  };

  const amount = parseAmountInput(args[1]);
  if (Number.isNaN(amount) || amount <= 0) {
    return message.reply("`❌` الاستخدام: `tax <المبلغ>`\nمثال: `tax 100000`");
  }

  const probot = tax(amount);
  const probotTax = Number(probot?.protax || 0);
  const probotNet = Math.max(0, Math.floor(amount - probotTax));

  const botTax = Math.floor(amount * taxRate);
  const botNet = Math.max(0, Math.floor(amount - botTax));

  const embed = new Discord.MessageEmbed()
    .setColor("#032943")
    .setTitle("💸 حاسبة الضريبة")
    .setDescription(
      `> **المبلغ المدخل:** \`${Math.floor(amount).toLocaleString("en-US")}\`\n> **نسبة ضريبة البوت الحالية:** \`${(taxRate * 100).toFixed(2)}%\``,
    )
    .addFields(
      {
        name: "🔁 ضريبة تحويل بروبوت",
        value: `**الضريبة:** \`${probotTax.toLocaleString("en-US")}\`\n**الصافي بعد الضريبة:** \`${probotNet.toLocaleString("en-US")}\``,
        inline: true,
      },
      {
        name: "🎮 ضريبة ألعاب البوت",
        value: `**الضريبة:** \`${botTax.toLocaleString("en-US")}\`\n**الصافي بعد الضريبة:** \`${botNet.toLocaleString("en-US")}\``,
        inline: true,
      },
    )
    .setFooter(`طلب بواسطة ${message.author.tag}`)
    .setTimestamp();

  return message.reply({ embeds: [embed] });
});


// ================================================================
// MINES DUEL - حقل الألغام (PvP)
// ================================================================

function mdGenerateMines(count, size) {
  const positions = [];
  while (positions.length < count) {
    const pos = Math.floor(Math.random() * size);
    if (!positions.includes(pos)) positions.push(pos);
  }
  return positions;
}

function mdBuildEmbed(score1, score2, p1tag, p2tag, currentTurnId, p1id, safeLeft) {
  const turnName = currentTurnId === p1id ? p1tag : p2tag;
  return new Discord.MessageEmbed()
    .setColor("#032943")
    .setTitle("💣 حقل الألغام")
    .addFields(
      { name: p1tag, value: `> النقاط: **${score1}**`, inline: true },
      { name: p2tag, value: `> النقاط: **${score2}**`, inline: true },
      { name: "الدور الحالي", value: `> **${turnName}** 🎯`, inline: false },
      { name: "الخلايا الآمنة المتبقية", value: `> **${safeLeft}** خلية`, inline: false },
    );
}

function mdBuildRows(mines, revealedBy, msgID) {
  const rows = [];
  for (let r = 0; r < 4; r++) {
    const btns = [];
    for (let c = 0; c < 4; c++) {
      const i = r * 4 + c;
      const rev = revealedBy[i];
      let label, style, disabled;
      if (rev === 0) {
        label = "⬛";
        style = "PRIMARY";
        disabled = false;
      } else if (rev === -1) {
        label = "💣";
        style = "DANGER";
        disabled = true;
      } else if (rev === 1) {
        label = "✅";
        style = "SUCCESS";
        disabled = true;
      } else {
        label = "🔵";
        style = "SECONDARY";
        disabled = true;
      }
      btns.push(
        new MessageButton()
          .setCustomId(`mdtile_${msgID}_${i}`)
          .setLabel(label)
          .setStyle(style)
          .setDisabled(disabled),
      );
    }
    rows.push(new MessageActionRow().addComponents(btns));
  }
  return rows;
}

async function mdResolve(interaction, gdata, winnerID, loserID, reason) {
  const coins = parseInt(gdata.coins);
  const tax = await calcTax(winnerID, coins);
  const prize = coins - tax;

  let winnerData = await db.findOne({ id: winnerID });
  if (!winnerData) winnerData = await db.create({ id: winnerID, coins: 0, status_playing: "no" });
  let loserData = await db.findOne({ id: loserID });
  if (!loserData) loserData = await db.create({ id: loserID, coins: 0, status_playing: "no" });

  winnerData.coins = parseInt(winnerData.coins) + prize;
  loserData.coins = Math.max(0, parseInt(loserData.coins) - coins);
  loserData.cashback = (parseInt(loserData.cashback) || 0) + Math.floor(coins * 0.02);
  winnerData.status_playing = "no";
  loserData.status_playing = "no";
  await winnerData.save();
  await loserData.save();
  await mafiaOnWin(winnerID, coins).catch(() => {});
  await mafiaOnLoss(loserID, coins).catch(() => {});
  trackMission(winnerID, "win").catch(()=>{});
  trackMission(winnerID, "play").catch(()=>{});
  trackMission(loserID,  "play").catch(()=>{});
  trackMission(winnerID, "bet", coins).catch(()=>{});
  trackMission(loserID,  "bet", coins).catch(()=>{});

  const winUser = client.users.cache.get(winnerID);
  const loseUser = client.users.cache.get(loserID);

  const finalEmbed = new Discord.MessageEmbed()
    .setColor("#032943")
    .setTitle("💣 انتهت لعبة حقل الألغام!")
    .setDescription(
      `> ${reason}\n\n` +
      `> 🏆 **الفائز:** ${winUser}\n` +
      `> 💰 **الربح:** \`${prize.toLocaleString("en-US")}\` (بعد الضريبة)\n` +
      `> ━━━━━━━━━━━━━━━━━━━━`
    )
    .setTimestamp();

  await finalizePFGameSessionByChannel(
    interaction.channel.id,
    `mines-duel winner=${winnerID} loser=${loserID} amount=${coins} reason=${reason}`,
  );

  await minesDuelGame.findOneAndDelete({ msgID: gdata.msgID }).catch(() => {});
  await game.findOneAndDelete({ id: gdata.id, with: gdata.with, msgID: gdata.msgID }).catch(() => {});

  const ch = client.channels.cache.get(gdata.channelID || interaction.channel.id);
  if (ch) {
    const msg = await ch.messages.fetch(gdata.msgID).catch(() => null);
    if (msg) await msg.edit({ embeds: [finalEmbed], content: `> || ${winUser} | ${loseUser} ||`, components: [] }).catch(() => {});
  }
}

