  if (!interaction.isButton()) return;
  if (!interaction.customId.startsWith("yesmines_")) return;
  const msgID = interaction.customId.slice("yesmines_".length);

  let gdatawith = await game.findOne({ with: interaction.user.id, msgID });
  if (!gdatawith) return;

  await createPFGameSessionFromContext({
    guildId: interaction.guild.id,
    channelId: interaction.channel.id,
    playerId: gdatawith.id,
    opponentId: gdatawith.with,
    bet: gdatawith.coins,
    gameType: "pvp-mines-duel",
  });

  await interaction.deferReply({ ephemeral: true });

  const stusrgame = client.users.cache.get(gdatawith.id);
  const wthusrgame = client.users.cache.get(gdatawith.with);

  gdatawith.time = timestamp(moment(ms("120s")) + Date.now());
  await gdatawith.save();

  const mines = mdGenerateMines(4, 16);
  const revealedBy = Array(16).fill(0);
  const startingPlayer = [gdatawith.id, gdatawith.with][Math.floor(Math.random() * 2)];

  let existingMD = await minesDuelGame.findOne({ msgID });
