// Mines Duel — tile click
client.on("interactionCreate", async (interaction) => {
  if (!interaction.isButton()) return;
  if (!interaction.customId.startsWith("mdtile_")) return;

  const parts = interaction.customId.split("_");
  if (parts.length !== 3) return;
  const msgID = parts[1];
  const idx = parseInt(parts[2]);

  // Race-condition lock
  if (processingGames.has(msgID)) {
    return interaction.reply({ content: "> ⏳ جاري معالجة النقرة السابقة، انتظر لحظة!", ephemeral: true });
  }
  processingGames.add(msgID);
  const _mdLockTimer = setTimeout(() => processingGames.delete(msgID), 8000);
  const _mdRelease = () => { clearTimeout(_mdLockTimer); processingGames.delete(msgID); };

  let mddata = await minesDuelGame.findOne({ msgID });
  if (!mddata) { _mdRelease(); return; }

  if (interaction.user.id !== mddata.currentTurn) {
    _mdRelease();
    return interaction.reply({ content: "> ⏳ انتظر دورك!", ephemeral: true });
  }

  if (mddata.revealedBy[idx] !== 0) {
    _mdRelease();
    return interaction.reply({ content: "> هذه الخلية مكشوفة بالفعل!", ephemeral: true });
  }

  await interaction.deferUpdate();

  const gdatawith = await game.findOne({ msgID });
  if (!gdatawith) { _mdRelease(); return; }

  const isMine = mddata.mines.includes(idx);
  const isP1 = interaction.user.id === mddata.player1;

  mddata.revealedBy = [...mddata.revealedBy];

  if (isMine) {
    // Check Bomb Redirect ability FIRST
    const hasBombRedirect = await invConsume(interaction.user.id, "bomb_redirect");
    if (hasBombRedirect) {
      const opponentID = isP1 ? mddata.player2 : mddata.player1;
      mddata.revealedBy[idx] = -1;
      mddata.mines.forEach((mineIdx) => {
        if (mddata.revealedBy[mineIdx] === 0) mddata.revealedBy[mineIdx] = -1;
      });
      mddata.markModified("revealedBy");
      await mddata.save();

      const rows = mdBuildRows(mddata.mines, mddata.revealedBy, msgID);
      const ch2 = client.channels.cache.get(interaction.channel.id);
      if (ch2) {
        const msg2 = await ch2.messages.fetch(msgID).catch(() => null);
        if (msg2) await msg2.edit({ components: rows }).catch(() => {});
        ch2.send({
          embeds: [new Discord.MessageEmbed()
            .setColor("#032943")
            .setTitle("🧨 Bomb Redirect — تم توجيه اللغم!")
            .setDescription(
              `> <@${interaction.user.id}> فعّل **Bomb Redirect** 🧨\n> تم إعادة توجيه اللغم إلى <@${opponentID}>!\n> <@${opponentID}> خسر!`
            )]
        }).catch(() => {});
      }
      await mdResolve(interaction, gdatawith, interaction.user.id, opponentID, `🧨 ${interaction.user.tag} أعاد توجيه اللغم — الخصم وطأه!`);
      _mdRelease();
      return;
    }

    // Player stepped on mine — lose!
    mddata.revealedBy[idx] = -1;
    // Reveal all remaining mines
    mddata.mines.forEach((mineIdx) => {
      if (mddata.revealedBy[mineIdx] === 0) mddata.revealedBy[mineIdx] = -1;
    });
    mddata.markModified("revealedBy");
    await mddata.save();

    const rows = mdBuildRows(mddata.mines, mddata.revealedBy, msgID);
    const ch = client.channels.cache.get(interaction.channel.id);
    if (ch) {
      const msg = await ch.messages.fetch(msgID).catch(() => null);
      if (msg) await msg.edit({ components: rows }).catch(() => {});
    }

    const loserID = interaction.user.id;
    const winnerID = isP1 ? mddata.player2 : mddata.player1;
    await mdResolve(interaction, gdatawith, winnerID, loserID, `💥 ${interaction.user.tag} وطأ لغماً!`);
    _mdRelease();
  } else {
    // Safe tile
    mddata.revealedBy[idx] = isP1 ? 1 : 2;
    if (isP1) mddata.score1 += 1;
    else mddata.score2 += 1;

    const safeLeft = mddata.revealedBy.filter((v) => v === 0 && !mddata.mines.includes(mddata.revealedBy.indexOf(v))).length;
    // Count unrevealed safe tiles
    let safeTilesLeft = 0;
    for (let i = 0; i < 16; i++) {
      if (!mddata.mines.includes(i) && mddata.revealedBy[i] === 0) safeTilesLeft++;
    }

    mddata.currentTurn = isP1 ? mddata.player2 : mddata.player1;
    mddata.markModified("revealedBy");
    await mddata.save();

    const stUser = client.users.cache.get(mddata.player1);
    const wtUser = client.users.cache.get(mddata.player2);
    const nextUser = client.users.cache.get(mddata.currentTurn);

    if (safeTilesLeft === 0) {
      // All safe tiles revealed — highest score wins
      const rows = mdBuildRows(mddata.mines, mddata.revealedBy, msgID);
      const ch = client.channels.cache.get(interaction.channel.id);
      if (ch) {
        const msg = await ch.messages.fetch(msgID).catch(() => null);
        if (msg) await msg.edit({ components: rows }).catch(() => {});
      }
      let winnerID, loserID, reason;
      if (mddata.score1 > mddata.score2) {
        winnerID = mddata.player1; loserID = mddata.player2;
        reason = `🏆 ${stUser.tag} فاز بـ ${mddata.score1} نقطة مقابل ${mddata.score2}`;
      } else if (mddata.score2 > mddata.score1) {
        winnerID = mddata.player2; loserID = mddata.player1;
        reason = `🏆 ${wtUser.tag} فاز بـ ${mddata.score2} نقطة مقابل ${mddata.score1}`;
      } else {
        // Draw — return coins, no tax
        let d1 = await db.findOne({ id: gdatawith.id }); if (d1) { d1.status_playing = "no"; await d1.save(); }
        let d2 = await db.findOne({ id: gdatawith.with }); if (d2) { d2.status_playing = "no"; await d2.save(); }
        await minesDuelGame.findOneAndDelete({ msgID }).catch(() => {});
        await game.findOneAndDelete({ id: gdatawith.id, with: gdatawith.with, msgID }).catch(() => {});
        await finalizePFGameSessionByChannel(interaction.channel.id, `mines-duel DRAW score=${mddata.score1}-${mddata.score2}`);
        await mafiaOnDraw(mddata.player1).catch(() => {});
        await mafiaOnDraw(mddata.player2).catch(() => {});
        const drawEmbed = new Discord.MessageEmbed().setColor("#032943").setTitle("💣 حقل الألغام — تعادل!").setDescription(`> **تعادل!** النتيجة ${mddata.score1} - ${mddata.score2}\n> لا أحد يخسر أو يكسب.`);
        const ch2 = client.channels.cache.get(interaction.channel.id);
        if (ch2) { const m = await ch2.messages.fetch(msgID).catch(() => null); if (m) await m.edit({ embeds: [drawEmbed], content: `> || <@${mddata.player1}> | <@${mddata.player2}> ||`, components: [] }).catch(() => {}); }
        _mdRelease();
        return;
      }
      await mdResolve(interaction, gdatawith, winnerID, loserID, reason);
      _mdRelease();
      return;
    }

    const embed = mdBuildEmbed(mddata.score1, mddata.score2, stUser.tag, wtUser.tag, mddata.currentTurn, mddata.player1, safeTilesLeft);
    const rows = mdBuildRows(mddata.mines, mddata.revealedBy, msgID);
    client.channels.cache
      .get(interaction.channel.id)
      .messages.fetch(msgID)
      .then((msg) => msg.edit({ embeds: [embed], content: `> 💣 دور ${nextUser} — اختر خلية...`, components: rows }))
      .catch((err) => console.error(err));
    _mdRelease();
  }
});

// ================================================================
// RUSSIAN ROULETTE PVP - الروليت الروسي (PvP)
// ================================================================

function rrBuildChamberDisplay(currentChamber) {
  let display = "";
  for (let i = 1; i <= 6; i++) {
    if (i < currentChamber) display += "⭕ ";
    else if (i === currentChamber) display += "🔫 ";
    else display += "⬛ ";
  }
  return display.trim();
}

function rrBuildEmbed(p1tag, p2tag, currentTurnId, p1id, currentChamber) {
  const turnName = currentTurnId === p1id ? p1tag : p2tag;
  const chamberDisplay = rrBuildChamberDisplay(currentChamber);
  return new Discord.MessageEmbed()
    .setColor("#032943")
    .setTitle("🔫 الروليت الروسي")
    .setDescription(
      `> **المسدس:** ${chamberDisplay}\n> الطلقة الحية في واحدة من الغرف الستة!\n━━━━━━━━━━━━━━━━━━━━`
    )
    .addFields(
      { name: p1tag, value: `> اللاعب الأول`, inline: true },
      { name: p2tag, value: `> اللاعب الثاني`, inline: true },
      { name: "الدور الحالي", value: `> **${turnName}** 🎯`, inline: false },
      { name: "الغرفة الحالية", value: `> **${currentChamber}** من **6**`, inline: false },
    );
}

