  if (interaction.customId !== `poker_${interaction.user.id}`) return;

  let gdata = await game.findOne({ id: interaction.user.id });
  if (!gdata) return;
  if (!gdata.coins || !gdata.with || !gdata.msgID) return;

  gdata.game = "poker";
  await gdata.save();
  await interaction.deferReply({ ephemeral: true });

  let usraccano = interaction.guild.members.cache.find((s) => s.id == gdata.with);
  if (!usraccano)
    return interaction.editReply({ content: "`❎` **لم استطيع إيجاد خصمك في الخادم**", ephemeral: true });

  gdata.time = timestamp(moment(ms("40s")) + Date.now());
  await gdata.save();

  const embed = new Discord.MessageEmbed()
    .setColor("#032943")
    .setTitle("🃏 البوكر")
