  const stusrgame = client.users.cache.get(gdata.id);
  const wthusrgame = client.users.cache.get(gdata.with);

  client.channels.cache
    .get(interaction.channel.id)
    .messages.fetch(msgID)
    .then((msg) => msg.edit({ embeds: [], content: `> تم رفض تحدي **البوكر 🃏** بنجاح ${interaction.user}!\n> || ${stusrgame} | ${wthusrgame} ||`, components: [] }))
    .catch((err) => console.error(err));

  await game.findOneAndDelete({ id: gdata.id, with: gdata.with, msgID });
