  const isP1 = interaction.user.id === pdata.player1;
  const isP2 = interaction.user.id === pdata.player2;
  if (!isP1 && !isP2) return interaction.reply({ content: "> أنت لست جزءًا من هذه اللعبة.", ephemeral: true });
  if (isP1 && pdata.choice1) return interaction.reply({ content: "> لقد اخترت بالفعل!", ephemeral: true });
  if (isP2 && pdata.choice2) return interaction.reply({ content: "> لقد اخترت بالفعل!", ephemeral: true });

  await interaction.deferUpdate();

  if (isP1) pdata.choice1 = "show";
  else pdata.choice2 = "show";
  await pdata.save();

  const gdatawith = await game.findOne({ msgID });
  if (!gdatawith) return;
  const stUser = client.users.cache.get(pdata.player1);
  const wtUser = client.users.cache.get(pdata.player2);

  if (pdata.choice1 && pdata.choice2) {
    return pokerResolveGame(interaction, msgID, pdata, gdatawith);
  }

  // Still waiting on the other player
  const embed = pokerBuildEmbed(stUser.tag, wtUser.tag, pdata.choice1, pdata.choice2);
