const BM_ITEMS = [
  { name: "⚔️ سيف المحارب الأسطوري", desc: "سلاح قديم وجد في كهف مجهول عميق في جبال الشرق", min: 2_000_000, max: 15_000_000 },
  { name: "💎 الماسة الزرقاء النادرة", desc: "حجر كريم نادر من أعماق البحار الجنوبية", min: 5_000_000, max: 25_000_000 },
  { name: "🏺 إبريق فرعوني أصلي", desc: "وجد في مقبرة ملكية تعود لأكثر من 3000 سنة", min: 1_000_000, max: 8_000_000 },
  { name: "🗝️ مفتاح الكنز المفقود", desc: "يُقال أنه يفتح خزينة لا تُقدر بثمن", min: 500_000, max: 30_000_000 },
  { name: "📜 مخطوطة سرية نادرة", desc: "مكتوبة بلغة لا يعرفها أحد على وجه الأرض", min: 800_000, max: 6_000_000 },
  { name: "🧪 زجاجة الإكسير المجهول", desc: "علماء الكيمياء عجزوا عن تحليل محتواها منذ قرون", min: 300_000, max: 20_000_000 },
  { name: "👑 تاج الملك المنسي", desc: "تاج ذهبي مرصع بجواهر من ممالك بائدة وأمجاد ضائعة", min: 10_000_000, max: 50_000_000 },
  { name: "🔮 كرة التنبؤ الكريستالية", desc: "يُقال أن من يمتلكها يرى خطوط المستقبل بوضوح", min: 1_500_000, max: 12_000_000 },
  { name: "🗿 تمثال غامض مجهول الهوية", desc: "لا أحد يعرف من نحته أو ما يرمز إليه", min: 200_000, max: 5_000_000 },
  { name: "📦 صندوق مختوم بشمع أحمر", desc: "لا أحد يعرف ما بداخله... هل أنت مستعد للمجازفة؟", min: 100_000, max: 40_000_000 },
];

const blackMarketAuctions = new Map();

function bmBuildEmbed(auction) {
  const { item, currentBid, highestBidder, endsAt, bidders } = auction;
  const secsLeft = Math.max(0, Math.ceil((endsAt - Date.now()) / 1000));
  const bidderStr = highestBidder ? `<@${highestBidder.id}>` : "لا أحد بعد";
  const bidderCount = bidders ? bidders.size : 0;
  return new Discord.MessageEmbed()
    .setColor("#032943")
    .setTitle("🏴‍☠️ السوق السوداء — مزاد حصري!")
    .setDescription(
      `> **العنصر:** ${item.name}\n` +
      `> **الوصف:** *${item.desc}*\n` +
      `> ━━━━━━━━━━━━━━━━━━━━\n` +
      `> 💰 **السعر الحقيقي:** \`??? مجهول حتى نهاية المزاد\`\n` +
      `> 🏷️ **أعلى عرض:** \`${currentBid.toLocaleString("en-US")}\`\n` +
      `> 👤 **أعلى مزايد:** ${bidderStr}\n` +
      `> 👥 **المزايدون:** ${bidderCount} مشارك\n` +
      `> ⏱️ **الوقت المتبقي:** \`${secsLeft} ثانية\`\n` +
      `> ━━━━━━━━━━━━━━━━━━━━\n` +
      `> ⚠️ *الفائز يختار: احتفظ بالعنصر كقدرة أو بعه بسعر مجهول!*`
    )
    .setFooter("السوق السوداء — قرارك على مسؤوليتك!")
    .setTimestamp();
}

function bmBuildRow(channelId) {
  return new MessageActionRow().addComponents(
    new MessageButton().setCustomId(`bmbid_${channelId}_50000`).setLabel("+50K").setStyle("SECONDARY"),
    new MessageButton().setCustomId(`bmbid_${channelId}_500000`).setLabel("+500K").setStyle("PRIMARY"),
    new MessageButton().setCustomId(`bmbid_${channelId}_5000000`).setLabel("+5M").setStyle("SUCCESS"),
    new MessageButton().setCustomId(`bmbid_${channelId}_50000000`).setLabel("+50M").setStyle("DANGER"),
  );
}

async function bmEndAuction(channelId) {
  const auction = blackMarketAuctions.get(channelId);
  if (!auction || auction.ended) return;
  auction.ended = true;
  blackMarketAuctions.set(channelId, auction);

  // Release all bidders from "in auction" status immediately
  if (auction.bidders) auction.bidders.forEach((id) => bmActivePlayers.delete(id));

  const ch = client.channels.cache.get(channelId);
  if (!ch) return;
  const msg = await ch.messages.fetch(auction.msgId).catch(() => null);

  if (!auction.highestBidder) {
    const noOneEmbed = new Discord.MessageEmbed()
      .setColor("#032943")
      .setTitle("🏴‍☠️ السوق السوداء — انتهى المزاد")
      .setDescription("> لم يتقدم أحد بعرض! المزاد انتهى دون فائز.")
      .setTimestamp();
    if (msg) await msg.edit({ embeds: [noOneEmbed], components: [] }).catch(() => {});
    blackMarketAuctions.delete(channelId);
    return;
  }

  const { item, currentBid, highestBidder, itemIndex } = auction;
  const realPrice = item.min + Math.floor(Math.random() * (item.max - item.min + 1));
  auction.realPrice = realPrice;
  auction.resolved = false;
  blackMarketAuctions.set(channelId, auction);

  const abilityType = BM_ITEM_ABILITIES[itemIndex];
  const abilityDef = ABILITY_DEFS[abilityType] || { emoji: "🎁", name: "قدرة مجهولة" };

  const decisionEmbed = new Discord.MessageEmbed()
    .setColor("#032943")
    .setTitle("🏴‍☠️ السوق السوداء — فزتَ بالمزاد!")
    .setDescription(
      `> 🏆 **الفائز:** <@${highestBidder.id}>\n` +
      `> 🏷️ **عرضك الفائز:** \`${currentBid.toLocaleString("en-US")}\`\n` +
      `> ${item.name}\n` +
      `> ━━━━━━━━━━━━━━━━━━━━\n` +
      `> **القدرة المخفية داخل العنصر:** ${abilityDef.emoji} **${abilityDef.name}**\n` +
      `> ━━━━━━━━━━━━━━━━━━━━\n` +
      `> 🎒 **احتفظ** ← ادفع عرضك واحصل على القدرة مباشرةً (السعر يبقى مجهولاً)\n` +
      `> 💰 **بيع** ← اكشف السعر الحقيقي واحصل على الفرق (قد تربح أو تخسر)\n` +
      `> ⏱️ **لديك 60 ثانية للقرار — وإلا تُباع تلقائياً!**`
    )
    .setTimestamp();

  const btnKeep = new MessageButton()
    .setCustomId(`bmkeep_${channelId}`)
    .setLabel("🎒 احتفظ بالعنصر")
    .setStyle("PRIMARY");
  const btnSell = new MessageButton()
    .setCustomId(`bmsell_${channelId}`)
    .setLabel("💰 بيع واكشف السعر")
    .setStyle("SECONDARY");
  const row = new MessageActionRow().addComponents(btnKeep, btnSell);

  if (msg) await msg.edit({ embeds: [decisionEmbed], components: [row] }).catch(() => {});

  // Crystal Vision — send real price to winner via DM before they decide
  const winnerInv = await invGet(highestBidder.id);
  if (invHasActive(winnerInv, "crystal_vision")) {
    await invConsume(highestBidder.id, "crystal_vision");
    await logAbilityEvent(highestBidder.id, "crystal_vision", "مزاد السوق السوداء — كشف السعر الحقيقي", realPrice);
    const winnerUser = client.users.cache.get(highestBidder.id);
    if (winnerUser) {
      const net = realPrice - currentBid;
      winnerUser.send({
        embeds: [new Discord.MessageEmbed()
          .setColor("#032943")
          .setTitle("🔮 Crystal Vision — رأيتَ ما خُفي!")
          .setDescription(
            `> السعر الحقيقي لـ **${item.name}** هو:\n` +
            `> 💰 \`${realPrice.toLocaleString("en-US")}\`\n` +
            `> عرضك: \`${currentBid.toLocaleString("en-US")}\`\n` +
            `> الفرق: ${net >= 0 ? `✅ +\`${net.toLocaleString("en-US")}\`` : `❌ \`${net.toLocaleString("en-US")}\``}\n` +
            `> اختر بحكمة! 🔮`
          )]
      }).catch(() => {});
    }
  }

  // Auto-sell after 60 seconds if winner doesn't decide
  auction.decisionTimer = setTimeout(async () => {
    const cur = blackMarketAuctions.get(channelId);
    if (cur && !cur.resolved) await bmDoSell(channelId, true);
  }, 60_000);
  blackMarketAuctions.set(channelId, auction);
}

async function bmDoSell(channelId, auto = false) {
  const auction = blackMarketAuctions.get(channelId);
  if (!auction || auction.resolved) return;
  auction.resolved = true;
  blackMarketAuctions.set(channelId, auction);

  const { item, currentBid, highestBidder, realPrice } = auction;
  const net = realPrice - currentBid;
  const didProfit = net >= 0;

  let winnerData = await db.findOne({ id: highestBidder.id });
  if (!winnerData) winnerData = await db.create({ id: highestBidder.id, coins: 0, status_playing: "no" });
  winnerData.coins = Math.max(0, parseInt(winnerData.coins) + net);
  await winnerData.save();

  const ch = client.channels.cache.get(channelId);
  const msg = ch ? await ch.messages.fetch(auction.msgId).catch(() => null) : null;

  const resultEmbed = new Discord.MessageEmbed()
    .setColor(didProfit ? "GOLD" : "RED")
    .setTitle(`🏴‍☠️ السوق السوداء — ${auto ? "بيع تلقائي!" : "تم البيع!"}`)
    .setDescription(
      `> 🏆 **الفائز:** <@${highestBidder.id}>\n` +
      `> 🏷️ **ما دفعه:** \`${currentBid.toLocaleString("en-US")}\`\n` +
      `> ━━━━━━━━━━━━━━━━━━━━\n` +
      `> ${item.name}\n` +
      `> 💰 **القيمة الحقيقية:** \`${realPrice.toLocaleString("en-US")}\`\n` +
      `> ━━━━━━━━━━━━━━━━━━━━\n` +
      (didProfit
        ? `> ✅ **ربح صافٍ:** \`+${net.toLocaleString("en-US")}\` — صفقة رابحة! 🎉`
        : `> ❌ **خسارة:** \`${net.toLocaleString("en-US")}\` — دفع أكثر من قيمته! 💸`)
    )
    .setTimestamp();

  if (msg) await msg.edit({ embeds: [resultEmbed], components: [] }).catch(() => {});
  await logBMEvent({
    action: "sell",
    winnerId: highestBidder.id,
    itemName: item.name,
    paid: currentBid,
    realPrice,
    profit: net,
  });
  blackMarketAuctions.delete(channelId);
}

async function bmDoKeep(channelId) {
  const auction = blackMarketAuctions.get(channelId);
  if (!auction || auction.resolved) return;
  auction.resolved = true;
  blackMarketAuctions.set(channelId, auction);

  const { item, currentBid, highestBidder, itemIndex } = auction;

  let winnerData = await db.findOne({ id: highestBidder.id });
  if (!winnerData) winnerData = await db.create({ id: highestBidder.id, coins: 0, status_playing: "no" });
  winnerData.coins = Math.max(0, parseInt(winnerData.coins) - currentBid);
  await winnerData.save();

  const abilityType = BM_ITEM_ABILITIES[itemIndex];
  await invAdd(highestBidder.id, abilityType);
  const abilityDef = ABILITY_DEFS[abilityType] || { emoji: "🎁", name: "قدرة مجهولة" };

  const ch = client.channels.cache.get(channelId);
  const msg = ch ? await ch.messages.fetch(auction.msgId).catch(() => null) : null;

  const keepEmbed = new Discord.MessageEmbed()
    .setColor("#032943")
    .setTitle("🎒 السوق السوداء — احتُفظ بالعنصر!")
    .setDescription(
      `> 🏆 **الفائز:** <@${highestBidder.id}>\n` +
      `> 🏷️ **ما دُفع:** \`${currentBid.toLocaleString("en-US")}\`\n` +
      `> ━━━━━━━━━━━━━━━━━━━━\n` +
      `> ${item.name}\n` +
      `> ✅ **القدرة المكتسبة:** ${abilityDef.emoji} **${abilityDef.name}**\n` +
      `> ━━━━━━━━━━━━━━━━━━━━\n` +
      `> 💡 السعر الحقيقي بقي مجهولاً — حكمة أم فرصة ضائعة؟\n` +
      `> استخدم \`!inventory\` لرؤية قدراتك.`
    )
    .setTimestamp();

  if (msg) await msg.edit({ embeds: [keepEmbed], components: [] }).catch(() => {});
  await logBMEvent({
    action: "keep",
    winnerId: highestBidder.id,
    itemName: item.name,
    paid: currentBid,
    abilityEmoji: abilityDef.emoji,
    abilityName: abilityDef.name,
  });
  blackMarketAuctions.delete(channelId);
}

// Black Market — !black command
client.on("messageCreate", async (message) => {
  if (message.author.bot || !message.guild) return;
  const trigger = message.content.trim().toLowerCase();
  if (trigger !== "!black") return;

  const isOwner = owners.includes(message.author.id);
  const hasPerm = permStore.canUseCommand(message.author.id, "black");
  if (!isOwner && !hasPerm) {
    return message.reply("> ❌ ليس لديك صلاحية لاستخدام هذا الأمر.\nطلب من الإدارة: `!giveperm black @user`");
  }

  if (blackMarketAuctions.has(message.channel.id))
    return message.reply("> ❌ يوجد مزاد جارٍ في هذا الروم بالفعل!");

  const itemIndex = Math.floor(Math.random() * BM_ITEMS.length);
  const item = BM_ITEMS[itemIndex];
  const startingBid = Math.floor(item.min * (0.05 + Math.random() * 0.15));
  const duration = 90_000;

  const auction = {
    item,
    itemIndex,
    currentBid: startingBid,
    highestBidder: null,
    bidders: new Set(),
    endsAt: Date.now() + duration,
    msgId: null,
    ended: false,
    resolved: false,
    timer: null,
    decisionTimer: null,
    realPrice: null,
  };

  const embed = bmBuildEmbed(auction);
  const row = bmBuildRow(message.channel.id);
  const sentMsg = await message.channel.send({ embeds: [embed], components: [row] });
  auction.msgId = sentMsg.id;
  auction.timer = setTimeout(() => bmEndAuction(message.channel.id), duration);
  blackMarketAuctions.set(message.channel.id, auction);

  // Insider Info — notify channel members who have it
  const channelMembers = message.guild.members.cache.filter(
    (m) => !m.user.bot && message.channel.permissionsFor(m).has("VIEW_CHANNEL"),
  );
  for (const [memberId] of channelMembers) {
    const memberInv = await invGet(memberId);
    if (invHasActive(memberInv, "insider_info")) {
      await invConsume(memberId, "insider_info");
      await logAbilityEvent(memberId, "insider_info", "مزاد جديد — تلميح مسبق بالسعر");
      const memberUser = client.users.cache.get(memberId);
      if (memberUser) {
        const slack = (item.max - item.min) * 0.2;
        const hint = Math.floor(
          item.min + Math.random() * (item.max - item.min) + (Math.random() - 0.5) * slack,
        );
        memberUser.send({
          embeds: [new Discord.MessageEmbed()
            .setColor("#032943")
            .setTitle("👁️ Insider Info — معلومة سرية!")
            .setDescription(
              `> عنصر المزاد الحالي: **${item.name}**\n` +
              `> 💡 **تقدير السعر الحقيقي:** \`${Math.max(item.min, Math.min(item.max, hint)).toLocaleString("en-US")}\`\n` +
              `> *(تلميح تقريبي من مصدر موثوق)*`
            )]
        }).catch(() => {});
      }
    }
  }
});

// Black Market — bid button
client.on("interactionCreate", async (interaction) => {
  if (!interaction.isButton()) return;
  if (!interaction.customId.startsWith("bmbid_")) return;

  const parts = interaction.customId.split("_");
  if (parts.length !== 3) return;
  const channelId = parts[1];
  const increment = parseInt(parts[2]);

  const auction = blackMarketAuctions.get(channelId);
  if (!auction || auction.ended)
    return interaction.reply({ content: "> ❌ المزاد انتهى أو لا يوجد مزاد نشط.", ephemeral: true });

  const newBid = auction.currentBid + increment;

  let userData = await db.findOne({ id: interaction.user.id });
  if (!userData) userData = await db.create({ id: interaction.user.id, coins: 0, status_playing: "no" });

  if (parseInt(userData.coins) < newBid)
    return interaction.reply({
      content: `> ❌ **رصيدك لا يكفي!** تحتاج \`${newBid.toLocaleString("en-US")}\` ورصيدك \`${parseInt(userData.coins).toLocaleString("en-US")}\``,
      ephemeral: true,
    });

  // Track this bidder as "in auction"
  if (!auction.bidders.has(interaction.user.id)) {
    auction.bidders.add(interaction.user.id);
    bmActivePlayers.add(interaction.user.id);
  }

  auction.currentBid = newBid;
  auction.highestBidder = { id: interaction.user.id, tag: interaction.user.tag };
  auction.endsAt = Date.now() + 30_000;

  if (auction.timer) clearTimeout(auction.timer);
  auction.timer = setTimeout(() => bmEndAuction(channelId), 30_000);
  blackMarketAuctions.set(channelId, auction);

  const embed = bmBuildEmbed(auction);
  const row = bmBuildRow(channelId);
  await interaction.update({ embeds: [embed], components: [row] });
});

// Black Market — KEEP button
client.on("interactionCreate", async (interaction) => {
  if (!interaction.isButton()) return;
  if (!interaction.customId.startsWith("bmkeep_")) return;
  const channelId = interaction.customId.slice("bmkeep_".length);

  const auction = blackMarketAuctions.get(channelId);
  if (!auction || !auction.ended || auction.resolved)
    return interaction.reply({ content: "> ❌ لا يوجد قرار معلق حالياً.", ephemeral: true });
  if (interaction.user.id !== auction.highestBidder.id)
    return interaction.reply({ content: "> ❌ هذا القرار ليس لك!", ephemeral: true });

  if (auction.decisionTimer) clearTimeout(auction.decisionTimer);
  await interaction.deferUpdate();
  await bmDoKeep(channelId);
});

