// ================================================================
// INVENTORY COMMAND — !inventory / حقيبتي
// ================================================================
client.on("messageCreate", async (message) => {
  if (message.author.bot || !message.guild) return;
  const content = message.content.trim();
  if (content !== "!inventory" && !content.startsWith("!inventory ") &&
      content !== "حقيبتي" && !content.startsWith("حقيبتي ")) return;

  const target = message.mentions.users.first() || message.author;
  const inv = await invGet(target.id);

  // Remove expired items first
  if (inv && inv.items.length > 0) {
    const now = Date.now();
    const before = inv.items.length;
    inv.items = inv.items.filter((i) => !i.expiresAt || now <= i.expiresAt);
    if (inv.items.length !== before) { inv.markModified("items"); await inv.save(); }
  }

  if (!inv || inv.items.length === 0) {
    return message.reply({
      embeds: [new Discord.MessageEmbed()
        .setColor("#032943")
        .setTitle("🎒 الحقيبة فارغة")
        .setDescription(
          `> **${target.tag}** لا يمتلك أي قدرات حالياً.\n` +
          `> يمكن الحصول على قدرات عبر **السوق السوداء** \`!black\``
        )]
    });
  }

  // Group same ability types for stacked display
  const grouped = [];
  for (const item of inv.items) {
    const existing = grouped.find((g) => g.type === item.type && g.expiresAt === item.expiresAt);
    if (existing) { existing.count++; }
    else { grouped.push({ ...item, count: 1 }); }
  }
  const itemsList = grouped.map((item, i) => {
    const expStr = item.expiresAt
      ? `⏳ تنتهي <t:${Math.floor(item.expiresAt / 1000)}:R>`
      : `🎯 استخدام واحد`;
    const countStr = item.count > 1 ? ` **x ${item.count}**` : "";
    return `> **${i + 1}.** ${item.emoji || "🎁"} **${item.name}**${countStr}\n>   ${expStr}`;
  }).join("\n\n");

  return message.reply({
    embeds: [new Discord.MessageEmbed()
      .setColor("#032943")
      .setTitle(`🎒 حقيبة ${target.tag}`)
      .setDescription(
        `> **عدد العناصر:** ${inv.items.length} (نوع ${grouped.length})\n` +
        `> ━━━━━━━━━━━━━━━━━━━━\n\n${itemsList}\n\n` +
        `> ━━━━━━━━━━━━━━━━━━━━\n` +
        `> 💡 \`!use mysterybox\` أو \`!use whisper\` أو \`!use crystal\` للاستخدام اليدوي\n` +
        `> القدرات الأخرى تتفعل تلقائياً في اللحظة المناسبة.`
      )
      .setThumbnail(target.displayAvatarURL({ dynamic: true }))
    ]
  });
});

// ================================================================
// USE ITEM COMMAND — !use / استخدم
// ================================================================
client.on("messageCreate", async (message) => {
  if (message.author.bot || !message.guild) return;
  const args = message.content.trim().split(/\s+/);
  if (args[0] !== "!use" && args[0] !== "استخدم") return;

  const sub = args[1]?.toLowerCase();
  if (!sub)
    return message.reply(
      "> ❌ حدد العنصر.\n> `!use mysterybox` — فتح صندوق المفاجآت\n> `!use whisper` — تلميح مزاد ناشط\n> `!use crystal` — كشف السعر في مزاد ناشط"
    );

  const userId = message.author.id;
  const inv = await invGet(userId);

  // Mystery Box
  if (sub === "mysterybox" || sub === "mystery" || sub === "صندوق") {
    if (!invHasActive(inv, "mystery_box"))
      return message.reply("> ❌ لا تمتلك **Mystery Box** في حقيبتك!");
    await invConsume(userId, "mystery_box");
    const randomType = MYSTERY_BOX_POOL[Math.floor(Math.random() * MYSTERY_BOX_POOL.length)];
    await invAdd(userId, randomType);
    const def = ABILITY_DEFS[randomType];
    return message.reply({
      embeds: [new Discord.MessageEmbed()
        .setColor("#032943")
        .setTitle("🎁 Mystery Box — تم فتح الصندوق!")
        .setDescription(
          `> حصلتَ على:\n> ${def.emoji} **${def.name}**\n` +
          `> تحقق من حقيبتك: \`!inventory\``
        )]
    });
  }

  // Whisper Dealer
  if (sub === "whisper" || sub === "تلميح") {
    if (!invHasActive(inv, "whisper_dealer"))
      return message.reply("> ❌ لا تمتلك **Whisper Dealer** في حقيبتك!");

    const activeAuction = [...blackMarketAuctions.values()].find((a) => !a.ended && a.msgId);
    if (!activeAuction)
      return message.reply("> ❌ لا يوجد مزاد ناشط حالياً في الخادم.");

    await invConsume(userId, "whisper_dealer");
    await logAbilityEvent(userId, "whisper_dealer", "استخدام يدوي — تلميح مزاد ناشط");

    // 60% real hint (within ±20% of real range), 40% fake
    const isReal = Math.random() < 0.6;
    const { item } = activeAuction;
    let hintPrice;
    if (isReal) {
      const slack = (item.max - item.min) * 0.2;
      hintPrice = item.min + Math.random() * (item.max - item.min);
      hintPrice = Math.max(item.min, Math.min(item.max, hintPrice + (Math.random() - 0.5) * slack));
    } else {
      hintPrice = item.min * 0.3 + Math.random() * item.max * 1.8;
    }
    const hintLabel = isReal ? "📊 (مصدر موثوق)" : "🎭 (قد يكذب التاجر...)";

    return message.reply({
      embeds: [new Discord.MessageEmbed()
        .setColor("#032943")
        .setTitle("💬 Whisper Dealer — همس التاجر")
        .setDescription(
          `> التاجر يهمس في أذنك:\n` +
          `> 💰 **تقدير السعر:** \`${Math.floor(hintPrice).toLocaleString("en-US")}\`\n` +
          `> ${hintLabel}`
        )]
    });
  }

  // Crystal Vision
  if (sub === "crystal" || sub === "crystalvision" || sub === "رؤية") {
    if (!invHasActive(inv, "crystal_vision"))
      return message.reply("> ❌ لا تمتلك **Crystal Vision** في حقيبتك!");

    const activeAuction = [...blackMarketAuctions.values()].find((a) => !a.ended && a.msgId);
    if (!activeAuction)
      return message.reply("> ❌ لا يوجد مزاد ناشط حالياً في الخادم.");

    await invConsume(userId, "crystal_vision");
    await logAbilityEvent(userId, "crystal_vision", "استخدام يدوي — كشف السعر");

    const { item } = activeAuction;
    const revealedPrice = item.min + Math.floor(Math.random() * (item.max - item.min + 1));

    return message.reply({
      embeds: [new Discord.MessageEmbed()
        .setColor("#032943")
        .setTitle("🔮 Crystal Vision — رأيتَ ما خُفي!")
        .setDescription(
          `> تكشف لك الكرة الكريستالية:
` +
          `> **العنصر:** ${item.name}
` +
          `> 💰 **السعر الحقيقي التقديري:** \`${revealedPrice.toLocaleString("en-US")}\`
` +
          `> *(تقدير دقيق من نطاق السعر الحقيقي — اختر بحكمة!)*`
        )]
    });
  }

  // ── Re:Zero Character Abilities ─────────────────────────────
  const RZ_ABILITY_MAP = {
    subaru:    { charId: "subaru",    abilityType: "rz_return_by_death", emoji: "⚔️",  name: "Subaru Natsuki",     abilityName: "Return by Death" },
    emilia:    { charId: "emilia",    abilityType: "rz_frozen_forest",   emoji: "❄️",  name: "Emilia",             abilityName: "Frozen Forest" },
    satella:   { charId: "satella",   abilityType: "rz_witch_factor",    emoji: "🖤",  name: "Witch of Envy",      abilityName: "Witch Factor" },
    rem:       { charId: "rem",       abilityType: "rz_water_demon",     emoji: "💙",  name: "Rem",                abilityName: "Water Demon Art" },
    ram:       { charId: "ram",       abilityType: "rz_wind_blade",      emoji: "🌸",  name: "Ram",                abilityName: "Wind Blade",    expiresIn: 7_200_000 },
    beatrice:  { charId: "beatrice",  abilityType: "rz_crystal_magic",   emoji: "📚",  name: "Beatrice",           abilityName: "Crystal Magic" },
    roswaal:   { charId: "roswaal",   abilityType: "rz_great_magic",     emoji: "🎭",  name: "Roswaal L. Mathers", abilityName: "Great Magic" },
    crusch:    { charId: "crusch",    abilityType: "rz_wind_reading",    emoji: "🌬️", name: "Crusch Karsten",     abilityName: "Wind Reading" },
    priscilla: { charId: "priscilla", abilityType: "rz_divine_prot",     emoji: "🌹",  name: "Priscilla Barielle", abilityName: "Divine Protection" },
    julius:    { charId: "julius",    abilityType: "rz_spirit_knight",   emoji: "⚜️",  name: "Julius Juukulius",   abilityName: "Spirit Knight" },
  };

  const rzChar = RZ_ABILITY_MAP[sub];
  if (rzChar) {
    // Check inventory for that character card
    const invData = await inventory.findOne({ id: userId });
    const charItem = invData?.items?.find(i => i.type === `rezero_${rzChar.charId}`);
    if (!charItem) {
      return message.reply(
        `> ❌ لا تمتلك شخصية **${rzChar.name}** في مجموعتك!\n` +
        `> اذهب إلى صفحة Re:Zero على الموقع وافتح البوابة للحصول عليها.`
      );
    }
    // Check if ability already active
    const invFull = await invGet(userId);
    if (invHasActive(invFull, rzChar.abilityType)) {
      return message.reply(
        `> ⚠️ قدرة **${rzChar.abilityName}** مفعّلة بالفعل! انتظر حتى تُستهلك.`
      );
    }
    // Remove one copy of the character card from inventory
    const idx = invData.items.findIndex(i => i.type === `rezero_${rzChar.charId}`);
    if (idx !== -1) {
      invData.items.splice(idx, 1);
      invData.markModified("items");
      await invData.save();
    }
    // Add the ability buff
    const inv2 = await invEnsure(userId);
    const expiresAt = rzChar.expiresIn ? Date.now() + rzChar.expiresIn : null;
    inv2.items.push({
      type: rzChar.abilityType,
      emoji: rzChar.emoji,
      name: ABILITY_DEFS[rzChar.abilityType]?.name || rzChar.abilityName,
      acquiredAt: Date.now(),
      expiresAt,
    });
    inv2.markModified("items");
    await inv2.save();

    const def = ABILITY_DEFS[rzChar.abilityType];
    return message.reply({
      embeds: [new Discord.MessageEmbed()
        .setColor("#7c3aed")
        .setTitle(`${rzChar.emoji} Re:Zero — تفعيل القدرة!`)
        .setDescription(
          `> استُهلكت بطاقة **${rzChar.name}** من مجموعتك.\n` +
          `> ✨ **${rzChar.abilityName}** مفعّلة الآن!\n` +
          `> ${def?.name || ""}\n` +
          (rzChar.expiresIn ? `> ⏱️ تنتهي خلال: **${Math.floor(rzChar.expiresIn/3600000)} ساعة**` : `> ⚡ تُستهلك في اللعبة القادمة تلقائياً`)
        )
        .setFooter("Re:Zero Ability System")]
    });
  }

  return message.reply(
    "> ❌ عنصر غير معروف للاستخدام اليدوي.\n> `!use mysterybox` أو `!use whisper` أو `!use crystal`\n> **Re:Zero:** `!use subaru` / `!use emilia` / `!use rem` / `!use ram` / `!use satella` / `!use beatrice` / `!use roswaal` / `!use crusch` / `!use priscilla` / `!use julius`"
  );
});

// ================================================================
// ADMIN: !giveitem @user <type>
// ================================================================
client.on("messageCreate", async (message) => {
  if (message.author.bot || !message.guild) return;
  if (!message.content.startsWith("!giveitem")) return;

  const isOwner = owners.includes(message.author.id);
  const hasPerm = permStore.canUseCommand(message.author.id, "giveitem");
  if (!isOwner && !hasPerm) {
    return message.reply("> ❌ ليس لديك صلاحية لاستخدام هذا الأمر.\nطلب من الإدارة: `!giveperm giveitem @user`");
  }

  const args = message.content.trim().split(/\s+/);
  const target = message.mentions.users.first();
  const itemType = args[2]?.toLowerCase();

  if (!target || !itemType)
    return message.reply(
      `> ❌ الاستخدام: \`!giveitem @user <نوع_العنصر>\`\n` +
      `> الأنواع المتاحة: ${Object.keys(ABILITY_DEFS).join(", ")}`
    );

  if (!ABILITY_DEFS[itemType])
    return message.reply(
      `> ❌ نوع \`${itemType}\` غير موجود.\n> الأنواع: ${Object.keys(ABILITY_DEFS).join(", ")}`
    );

  await invAdd(target.id, itemType);
  const def = ABILITY_DEFS[itemType];
  return message.reply({
    embeds: [new Discord.MessageEmbed()
      .setColor("#032943")
      .setTitle("✅ تم منح القدرة")
      .setDescription(
        `> ${def.emoji} **${def.name}**\n` +
        `> مُنحت لـ ${target}\n` +
        `> يمكنهم رؤيتها بـ \`!inventory\``
      )]
  });
});

