// ================================================================
// !top abilities — rarest abilities leaderboard
// ================================================================
client.on("messageCreate", async (message) => {
  if (message.author.bot || !message.guild) return;
  if (message.content.trim().toLowerCase() !== "!top abilities") return;

  const now = Date.now();
  const allInvs = await inventory.find({});

  // Build: ability type → array of userIds who hold it
  const holders = {};
  for (const inv of allInvs) {
    if (!inv.items || inv.items.length === 0) continue;
    const active = inv.items.filter((i) => !i.expiresAt || now <= i.expiresAt);
    const typesHeld = new Set(active.map((i) => i.type));
    for (const type of typesHeld) {
      if (!holders[type]) holders[type] = [];
      holders[type].push(inv.id);
    }
  }

  const entries = Object.entries(holders);
  if (entries.length === 0) {
    return message.reply({
      embeds: [new Discord.MessageEmbed()
        .setColor("#032943")
        .setTitle("🏆 لوحة أندر القدرات")
        .setDescription("> لا يوجد أحد يمتلك قدرات حالياً في السيرفر.")]
    });
  }

  // Sort rarest first (fewest holders)
  entries.sort(([, a], [, b]) => a.length - b.length);

  const rarityEmojis = ["🥇", "🥈", "🥉", "4️⃣", "5️⃣", "6️⃣", "7️⃣", "8️⃣", "9️⃣", "🔟"];
  const lines = entries.map(([type, holderIds], idx) => {
    const def = ABILITY_DEFS[type];
    if (!def) return null;
    const abilityName = def.name.split(" — ")[0];
    const holderMentions = holderIds.slice(0, 5).map((id) => `<@${id}>`).join(" ");
    const extra = holderIds.length > 5 ? ` +${holderIds.length - 5} آخرين` : "";
    const rank = rarityEmojis[idx] || `${idx + 1}.`;
    return (
      `${rank} ${def.emoji} **${abilityName}** — \`${holderIds.length} لاعب\`\n` +
      `> ${holderMentions}${extra}`
    );
  }).filter(Boolean);

  const embed = new Discord.MessageEmbed()
    .setColor("#032943")
    .setTitle("🏆 أندر القدرات في السيرفر")
    .setDescription(
      "> مرتبة من **الأندر** إلى الأكثر انتشاراً.\n" +
      "> للحصول على قدرات: **السوق السوداء** `!black`\n" +
      "━━━━━━━━━━━━━━━━━━━━\n\n" +
      lines.join("\n\n")
    )
    .setFooter({ text: `إجمالي اللاعبين بقدرات: ${allInvs.filter(i => i.items?.length > 0).length}` })
    .setTimestamp();

  return message.reply({ embeds: [embed] });
});

