const botolaSessions = new Map(); // channelId → BotolaSession

function botolaLobbyEmbed(session) {
  const playersList = session.players.length > 0
    ? session.players.map((p, i) => `> **${i + 1}.** <@${p.id}>`).join('\n')
    : '> *لا يوجد لاعبون بعد*';
  return new Discord.MessageEmbed()
    .setColor("#032943")
    .setTitle("🏆 بطولة كوكبة — انتظار اللاعبين!")
    .setDescription(
      `> 💰 **رسوم الدخول:** \`${session.fee.toLocaleString("en-US")}\`\n` +
      `> 🏅 **الجائزة الكبرى:** \`${session.prize.toLocaleString("en-US")}\`\n` +
      `> 👥 **اللاعبون:** ${session.players.length} / ${session.maxPlayers}\n` +
      `> ━━━━━━━━━━━━━━━━━━━━\n` +
      `${playersList}\n` +
      `> ━━━━━━━━━━━━━━━━━━━━\n` +
      `> اضغط **انضم** لدخول البطولة وسيُخصم \`${session.fee.toLocaleString("en-US")}\` من رصيدك!`
    )
    .setFooter({ text: "الأونر يبدأ البطولة بعد اكتمال اللاعبين" })
    .setTimestamp();
}

function botolaLobbyRow(channelId) {
  return new MessageActionRow().addComponents(
    new MessageButton().setCustomId(`btl_join_${channelId}`).setLabel("انضم للبطولة 🎮").setStyle("SUCCESS"),
    new MessageButton().setCustomId(`btl_start_${channelId}`).setLabel("ابدأ البطولة ▶️").setStyle("PRIMARY"),
    new MessageButton().setCustomId(`btl_cancel_${channelId}`).setLabel("إلغاء ❌").setStyle("DANGER"),
  );
}

// !botola <fee> <maxplayers> <prize>
client.on("messageCreate", async (message) => {
  if (message.author.bot || !message.guild) return;
  const args = message.content.trim().split(/\s+/);
  if (args[0] !== "!botola") return;

  const isOwner = owners.includes(message.author.id);
  const hasPerm = permStore.canUseCommand(message.author.id, "botola");
  if (!isOwner && !hasPerm) {
    return message.reply("> ❌ ليس لديك صلاحية لاستخدام هذا الأمر.\nطلب من الإدارة: `!giveperm botola @user`");
  }

  const fee    = parseInt(args[1]);
  const maxPl  = parseInt(args[2]);
  const prize  = parseInt(args[3]);

  if (!fee || !maxPl || !prize || fee < 1 || maxPl < 2 || prize < 1)
    return message.reply(
      "> ❌ الاستخدام: `!botola <رسوم_الدخول> <عدد_اللاعبين> <الجائزة>`\n" +
      "> مثال: `!botola 50000 8 5000000`"
    );

  if (botolaSessions.has(message.channel.id))
    return message.reply("> ❌ يوجد بطولة جارية في هذا الروم بالفعل!");

  const session = {
    id: message.channel.id,
    ownerId: message.author.id,
    fee, maxPlayers: maxPl, prize,
    gameType: null,
    players: [],
    msgId: null,
    started: false,
    ended: false,
    taqribiSecret: null,
    taqribiGuesses: {},
  };

  const sent = await message.channel.send({
    embeds: [botolaLobbyEmbed(session)],
    components: [botolaLobbyRow(message.channel.id)],
  });
  session.msgId = sent.id;
  botolaSessions.set(message.channel.id, session);
});

// JOIN button
client.on("interactionCreate", async (interaction) => {
  if (!interaction.isButton()) return;
  if (!interaction.customId.startsWith("btl_join_")) return;
  const channelId = interaction.customId.slice("btl_join_".length);
  const session = botolaSessions.get(channelId);

  if (!session || session.started)
    return interaction.reply({ content: "> ❌ البطولة لم تعد متاحة للانضمام.", ephemeral: true });
  if (session.players.find(p => p.id === interaction.user.id))
    return interaction.reply({ content: "> ❌ أنت مسجل بالفعل في البطولة!", ephemeral: true });
  if (session.players.length >= session.maxPlayers)
    return interaction.reply({ content: "> ❌ البطولة ممتلئة!", ephemeral: true });

  let userData = await db.findOne({ id: interaction.user.id });
  if (!userData) userData = await db.create({ id: interaction.user.id, coins: 0, status_playing: "no" });
  if (parseInt(userData.coins) < session.fee)
    return interaction.reply({
      content: `> ❌ رصيدك لا يكفي! تحتاج \`${session.fee.toLocaleString("en-US")}\` ورصيدك \`${parseInt(userData.coins).toLocaleString("en-US")}\``,
      ephemeral: true,
    });

  userData.coins = parseInt(userData.coins) - session.fee;
  userData.status_playing = "yes";
  await userData.save();

  session.players.push({ id: interaction.user.id, tag: interaction.user.tag });
  botolaSessions.set(channelId, session);

  const ch = client.channels.cache.get(channelId);
  const msg = ch ? await ch.messages.fetch(session.msgId).catch(() => null) : null;
  if (msg) await msg.edit({ embeds: [botolaLobbyEmbed(session)], components: [botolaLobbyRow(channelId)] }).catch(() => {});

  await interaction.reply({
    content: `> ✅ انضممت للبطولة! خُصم \`${session.fee.toLocaleString("en-US")}\` من رصيدك.`,
    ephemeral: true,
  });

  });

// START button (owner only)
client.on("interactionCreate", async (interaction) => {
  if (!interaction.isButton()) return;
  if (!interaction.customId.startsWith("btl_start_")) return;
  const channelId = interaction.customId.slice("btl_start_".length);
  const session = botolaSessions.get(channelId);

  if (!session) return interaction.reply({ content: "> ❌ لا توجد بطولة.", ephemeral: true });
  if (interaction.user.id !== session.ownerId)
    return interaction.reply({ content: "> ❌ فقط الأونر يمكنه بدء البطولة!", ephemeral: true });
  if (session.started)
    return interaction.reply({ content: "> ❌ البطولة بدأت بالفعل.", ephemeral: true });
  if (session.players.length < 2)
    return interaction.reply({ content: "> ❌ تحتاج لاعبين على الأقل (2) للبدء!", ephemeral: true });

  await interaction.deferUpdate();
  const ch = client.channels.cache.get(channelId);
  await botolaShowGameSelect(ch, session);
});

// CANCEL button (owner only)
client.on("interactionCreate", async (interaction) => {
  if (!interaction.isButton()) return;
  if (!interaction.customId.startsWith("btl_cancel_")) return;
  const channelId = interaction.customId.slice("btl_cancel_".length);
  const session = botolaSessions.get(channelId);

  if (!session) return interaction.reply({ content: "> ❌ لا توجد بطولة.", ephemeral: true });
  if (interaction.user.id !== session.ownerId)
    return interaction.reply({ content: "> ❌ فقط الأونر يمكنه الإلغاء!", ephemeral: true });
  if (session.started)
    return interaction.reply({ content: "> ❌ البطولة بدأت، لا يمكن إلغاؤها.", ephemeral: true });

  for (const p of session.players) {
    let ud = await db.findOne({ id: p.id });
    if (ud) { ud.coins = parseInt(ud.coins) + session.fee; ud.status_playing = "no"; await ud.save(); }
  }
  botolaSessions.delete(channelId);
  await interaction.deferUpdate();
  const ch = client.channels.cache.get(channelId);
  const msg = ch ? await ch.messages.fetch(session.msgId).catch(() => null) : null;
  if (msg) await msg.edit({
    embeds: [new Discord.MessageEmbed()
      .setColor("#032943").setTitle("❌ تم إلغاء البطولة")
      .setDescription("> تم استرداد رسوم الدخول لجميع اللاعبين المسجلين.")],
    components: [],
  }).catch(() => {});
});

async function botolaShowGameSelect(ch, session) {
  session.started = true;
  botolaSessions.set(session.id, session);
  const embed = new Discord.MessageEmbed()
    .setColor("#032943")
    .setTitle("🏆 بطولة كوكبة — اختر نوع اللعبة!")
    .setDescription(
      `> **اللاعبون (${session.players.length}):** ${session.players.map(p => `<@${p.id}>`).join(' ')}\n` +
      `> 🏅 **الجائزة:** \`${session.prize.toLocaleString("en-US")}\`\n` +
      `> ━━━━━━━━━━━━━━━━━━━━\n` +
      `> اختر اللعبة لبدء البطولة!`
    )
    .setTimestamp();
  const row = new MessageActionRow().addComponents(
    new MessageButton().setCustomId(`btl_game_taqribi_${session.id}`).setLabel("🔢 تقريبي").setStyle("PRIMARY"),
    new MessageButton().setCustomId(`btl_game_uno_${session.id}`).setLabel("🃏 UNO").setStyle("SUCCESS"),
  );
  const msg = ch ? await ch.messages.fetch(session.msgId).catch(() => null) : null;
  if (msg) await msg.edit({ embeds: [embed], components: [row] }).catch(() => {});
}

// Game type — Taqribi
