// ================================================================
// Spy Glass — reveal opponent score in bracket taqribi match
// ================================================================
client.on("interactionCreate", async (interaction) => {
  if (!interaction.isButton()) return;
  if (!interaction.customId.startsWith("btq_spy_")) return;
  const matchId = interaction.customId.slice("btq_spy_".length);
  const match   = btqMatches.get(matchId);
  if (!match)
    return interaction.reply({ content: "> ❌ المباراة انتهت.", ephemeral: true });

  const isP1 = interaction.user.id === match.p1;
  const isP2 = interaction.user.id === match.p2;
  if (!isP1 && !isP2)
    return interaction.reply({ content: "> ❌ أنت لست في هذه المباراة.", ephemeral: true });

  const inv = await invGet(interaction.user.id);
  if (!invHasActive(inv, "spy_glass"))
    return interaction.reply({ content: "> ❌ ليس لديك Spy Glass في مخزونك!", ephemeral: true });

  await invConsume(interaction.user.id, "spy_glass");
  await logAbilityEvent(interaction.user.id, "spy_glass", "تقريبي بطولة — كشف نقاط الخصم");

  const oppId    = isP1 ? match.p2 : match.p1;
  const oppScore = isP1 ? match.p2Score : match.p1Score;
  const oppNums  = isP1 ? match.p2Numbers : match.p1Numbers;
  const numStr   = oppNums.length ? oppNums.join(" + ") : "0";

  await interaction.reply({
    content: `> 🔭 **Spy Glass:** نقاط <@${oppId}> الآن:\n> **${oppScore}** نقطة (${numStr})`,
    ephemeral: true,
  });
});
// ================================================================
// ================================================================
// MATCH BETTING SYSTEM — نظام الرهانات على المباريات
// ================================================================
// ================================================================

// ── match ID counter ──────────────────────────────────────────
const MB_COUNTER_FILE = path.join(__dirname, "matchCounter.json");
function mbNextId() {
  let data = { n: 0 };
  try { data = JSON.parse(fs.readFileSync(MB_COUNTER_FILE, "utf8")); } catch {}
  data.n = (data.n || 0) + 1;
  fs.writeFileSync(MB_COUNTER_FILE, JSON.stringify(data));
  return `M${String(data.n).padStart(3, "0")}`;
}

// ── helpers ───────────────────────────────────────────────────
function mbTeamTotal(match, side) {
  return match.bets.filter(b => b.side === side).reduce((s, b) => s + b.amount, 0);
}
function mbTeamCount(match, side) {
  return match.bets.filter(b => b.side === side).length;
}
function mbTotalPot(match) { return mbTeamTotal(match, 1) + mbTeamTotal(match, 2); }

function mbOdds(match, side) {
  const total = mbTotalPot(match);
  const sideTotal = mbTeamTotal(match, side);
  if (sideTotal === 0 || total === 0) return "—";
  return (total / sideTotal).toFixed(2) + "x";
}

function mbStatusEmoji(status) {
  return { open: "🟢 مفتوح", closed: "🔴 مغلق", finished: "🏁 انتهت", cancelled: "❌ ملغى" }[status] || status;
}

function mbBuildEmbed(match) {
  const t1Total  = mbTeamTotal(match, 1);
  const t2Total  = mbTeamTotal(match, 2);
  const pot      = t1Total + t2Total;
  const t1Count  = mbTeamCount(match, 1);
  const t2Count  = mbTeamCount(match, 2);
  const t1Odds   = mbOdds(match, 1);
  const t2Odds   = mbOdds(match, 2);
  const deadlineStr = match.deadline > 0
    ? `> ⏱️ **إغلاق الرهانات:** <t:${Math.floor(match.deadline / 1000)}:R>\n`
    : "";

  let resultLine = "";
  if (match.result !== null) {
    if (match.result === 0)        resultLine = `> 🤝 **النتيجة: تعادل — تم إرجاع جميع الرهانات!**\n`;
    else if (match.result === 1)   resultLine = `> 🏆 **الفائز: ${match.team1}**\n`;
    else                           resultLine = `> 🏆 **الفائز: ${match.team2}**\n`;
  }

  const color = match.status === "open" ? "#2ECC71"
    : match.status === "closed" ? "#E74C3C"
    : match.status === "finished" ? "#F1C40F"
    : "#95A5A6";

  return new Discord.MessageEmbed()
    .setColor(color)
    .setTitle(`🏟️ مباراة ${match.matchId} — ${match.team1}  vs  ${match.team2}`)
    .setDescription(
      (match.description ? `> 📝 ${match.description}\n> ━━━━━━━━━━━━━━━━━━━━\n` : "") +
      `> 📊 **الحالة:** ${mbStatusEmoji(match.status)}\n` +
      deadlineStr + resultLine +
      `> ━━━━━━━━━━━━━━━━━━━━\n` +
      `> 🔵 **${match.team1}**\n` +
      `> 💰 \`${t1Total.toLocaleString("en-US")}\` | 👥 ${t1Count} رهان | 📈 معامل: \`${t1Odds}\`\n` +
      `> ━━━━━━━━━━━━━━━━━━━━\n` +
      `> 🔴 **${match.team2}**\n` +
      `> 💰 \`${t2Total.toLocaleString("en-US")}\` | 👥 ${t2Count} رهان | 📈 معامل: \`${t2Odds}\`\n` +
      `> ━━━━━━━━━━━━━━━━━━━━\n` +
      `> 💵 **إجمالي البوت:** \`${pot.toLocaleString("en-US")}\``
    )
    .setFooter({ text: `${match.matchId} • الرهان على مسؤوليتك` })
    .setTimestamp(match.createdAt);
}

function mbBuildRow(matchId, status) {
  if (status !== "open") return null;
  return new MessageActionRow().addComponents(
    new MessageButton().setCustomId(`mb_bet1_${matchId}`).setLabel("راهن على الفريق 1 🔵").setStyle("PRIMARY"),
    new MessageButton().setCustomId(`mb_bet2_${matchId}`).setLabel("راهن على الفريق 2 🔴").setStyle("DANGER"),
    new MessageButton().setCustomId(`mb_mybets_${matchId}`).setLabel("رهاناتي 📋").setStyle("SECONDARY"),
  );
}

async function mbUpdateEmbed(match) {
  const ch  = client.channels.cache.get(match.channelId);
  if (!ch || !match.msgId) return;
  const msg = await ch.messages.fetch(match.msgId).catch(() => null);
  if (!msg) return;
  const row = mbBuildRow(match.matchId, match.status);
  await msg.edit({ embeds: [mbBuildEmbed(match)], components: row ? [row] : [] }).catch(() => {});
}

async function mbPostLog(match, payoutLines) {
  const logCh = client.channels.cache.get(SERVER_SETTINGS.channels.allBetsLogId);
  if (!logCh) return;
  const t1Total = mbTeamTotal(match, 1);
  const t2Total = mbTeamTotal(match, 2);
  const pot     = t1Total + t2Total;
  let resultStr = match.result === 0 ? "تعادل (استرداد كامل)" : match.result === 1 ? `فاز ${match.team1}` : `فاز ${match.team2}`;

  const embed = new Discord.MessageEmbed()
    .setColor(match.result === null ? "#95A5A6" : "#F1C40F")
    .setTitle(`📋 سجل رهانات — ${match.matchId} | ${match.team1} vs ${match.team2}`)
    .setDescription(
      `> 📊 **النتيجة:** ${resultStr}\n` +
      `> 💵 **البوت الكلي:** \`${pot.toLocaleString("en-US")}\`\n` +
      `> 🔵 ${match.team1}: \`${t1Total.toLocaleString("en-US")}\` (${mbTeamCount(match, 1)} رهان)\n` +
      `> 🔴 ${match.team2}: \`${t2Total.toLocaleString("en-US")}\` (${mbTeamCount(match, 2)} رهان)\n` +
      `> ━━━━━━━━━━━━━━━━━━━━\n` +
      (payoutLines.length > 0
        ? `> **المدفوعات:**\n${payoutLines.slice(0, 25).join("\n")}`
        : `> *لا توجد فائزون / تعادل أو إلغاء*`)
    )
    .setTimestamp();
  await logCh.send({ embeds: [embed] }).catch(() => {});
}

// ── auto deadline checker ──────────────────────────────────────
setInterval(async () => {
  try {
    const openMatches = await matchBet.find({ status: "open", deadline: { $gt: 0 } });
    for (const match of openMatches) {
      if (Date.now() >= match.deadline) {
        match.status = "closed";
        await match.save();
        await mbUpdateEmbed(match);
        const ch = client.channels.cache.get(match.channelId);
        if (ch) await ch.send({ content: `> 🔴 **أُغلق الرهان على مباراة ${match.matchId}** — ${match.team1} vs ${match.team2}` }).catch(() => {});
      }
    }
  } catch {}
}, 30_000);

// ── !addmatch ─────────────────────────────────────────────────
// Usage: !addmatch <team1> vs <team2> | [description] | [deadline_minutes]
client.on("messageCreate", async (message) => {
  if (message.author.bot || !message.guild) return;
  const content = message.content.trim();
  if (!content.toLowerCase().startsWith("!addmatch")) return;
  
  // Check permission: owner OR has "addmatch" permission
  const isOwner = owners.includes(message.author.id);
  const hasPermission = permStore.canUseCommand(message.author.id, "addmatch");
  
  if (!isOwner && !hasPermission) {
    return message.reply("> ❌ أنت لا تملك صلاحية استخدام هذا الأمر. اطلب من الإدارة: `!giveperm addmatch @user`");
  }

  const raw = content.slice("!addmatch".length).trim();
  // Format: Team1 vs Team2 | description | deadline_minutes
  const parts    = raw.split("|").map(s => s.trim());
  const vsParts  = (parts[0] || "").split(/\s+vs\s+/i).map(s => s.trim());
  if (vsParts.length < 2 || !vsParts[0] || !vsParts[1])
    return message.reply("> ❌ الاستخدام: `!addmatch <الفريق1> vs <الفريق2> | [وصف] | [دقائق_الإغلاق]`\n> مثال: `!addmatch الهلال vs النصر | دوري روشن | 60`");

  const team1       = vsParts[0];
  const team2       = vsParts[1];
  const description = parts[1] || "";
  const deadlineMins = parts[2] ? parseInt(parts[2]) : 0;
  const deadline    = deadlineMins > 0 ? Date.now() + deadlineMins * 60_000 : 0;

  const matchId = mbNextId();
  const newMatch = await matchBet.create({
    matchId, team1, team2, description,
    channelId: message.channel.id,
    deadline,
    createdBy: message.author.id,
  });

  const embed = mbBuildEmbed(newMatch);
  const row   = mbBuildRow(matchId, "open");
  const sent  = await message.channel.send({ embeds: [embed], components: [row] });
  newMatch.msgId = sent.id;
  await newMatch.save();

  await message.reply({ content: `> ✅ تم إنشاء مباراة **${matchId}** — ${team1} vs ${team2}!` });
});

// ── !closebets ────────────────────────────────────────────────
client.on("messageCreate", async (message) => {
  if (message.author.bot || !message.guild) return;
  const args = message.content.trim().split(/\s+/);
  if (args[0].toLowerCase() !== "!closebets") return;
  const isOwner = owners.includes(message.author.id);
  const hasPerm = permStore.canUseCommand(message.author.id, "closebets");
  if (!isOwner && !hasPerm) return message.reply("> ❌ ليس لديك صلاحية لاستخدام هذا الأمر.\nطلب من الإدارة: `!giveperm closebets @user`");

  const matchId = (args[1] || "").toUpperCase();
  if (!matchId) return message.reply("> ❌ الاستخدام: `!closebets <رقم_المباراة>`");

  const match = await matchBet.findOne({ matchId });
  if (!match) return message.reply(`> ❌ لم يتم إيجاد المباراة **${matchId}**.`);
  if (match.status !== "open") return message.reply(`> ❌ المباراة ليست مفتوحة (الحالة: ${match.status}).`);

  match.status = "closed";
  await match.save();
  await mbUpdateEmbed(match);
  await message.reply(`> 🔴 تم إغلاق الرهانات على مباراة **${matchId}** — ${match.team1} vs ${match.team2}.`);
});

// ── !result ───────────────────────────────────────────────────
// Usage: !result <matchId> <1|2|draw>
client.on("messageCreate", async (message) => {
  if (message.author.bot || !message.guild) return;
  const args = message.content.trim().split(/\s+/);
  if (args[0].toLowerCase() !== "!result") return;
  const isOwner = owners.includes(message.author.id);
  const hasPerm = permStore.canUseCommand(message.author.id, "result");
  if (!isOwner && !hasPerm) return message.reply("> ❌ ليس لديك صلاحية لاستخدام هذا الأمر.\nطلب من الإدارة: `!giveperm result @user`");

  const matchId   = (args[1] || "").toUpperCase();
  const resultArg = (args[2] || "").toLowerCase();

  if (!matchId || !resultArg) return message.reply("> ❌ الاستخدام: `!result <رقم_المباراة> <1|2|draw>`");
  if (!["1","2","draw","تعادل"].includes(resultArg)) return message.reply("> ❌ النتيجة يجب أن تكون `1` أو `2` أو `draw`.");

  const match = await matchBet.findOne({ matchId });
  if (!match) return message.reply(`> ❌ لم يتم إيجاد المباراة **${matchId}**.`);
  if (match.status === "finished") return message.reply(`> ❌ المباراة **${matchId}** انتهت مسبقاً.`);
  if (match.status === "cancelled") return message.reply(`> ❌ المباراة **${matchId}** ملغاة.`);

  const result = resultArg === "1" ? 1 : resultArg === "2" ? 2 : 0;
  match.result = result;
  match.status = "finished";
  await match.save();

  const payoutLines = [];
  const pot         = mbTotalPot(match);

  if (result === 0) {
    // Draw — full refund, no tax
    const refundMap = {};
    for (const b of match.bets) {
      refundMap[b.userId] = (refundMap[b.userId] || 0) + b.amount;
    }
    for (const [uid, amt] of Object.entries(refundMap)) {
      let ud = await db.findOne({ id: uid });
      if (!ud) ud = await db.create({ id: uid, coins: 0, status_playing: "no" });
      ud.coins = parseInt(ud.coins) + amt;
      await ud.save();
      payoutLines.push(`> 🔄 <@${uid}> ← استرداد \`${amt.toLocaleString("en-US")}\``);
    }
  } else {
    // One side wins — pool payout
    const winningSide = result;
    const winningTotal = mbTeamTotal(match, winningSide);

    if (winningTotal === 0) {
      // Nobody bet on the winning side — refund everyone
      for (const b of match.bets) {
        let ud = await db.findOne({ id: b.userId });
        if (!ud) ud = await db.create({ id: b.userId, coins: 0, status_playing: "no" });
        ud.coins = parseInt(ud.coins) + b.amount;
        await ud.save();
      }
      payoutLines.push(`> ℹ️ لا أحد راهن على الفريق الفائز — تم إرجاع جميع الرهانات.`);
    } else {
      const tax    = Math.floor(pot * taxRate);
      const netPot = pot - tax;

      // Group bets by userId on winning side
      const winnerMap = {};
      for (const b of match.bets.filter(b => b.side === winningSide)) {
        winnerMap[b.userId] = (winnerMap[b.userId] || 0) + b.amount;
      }

      for (const [uid, userBet] of Object.entries(winnerMap)) {
        const prize = Math.floor((userBet / winningTotal) * netPot);
        let ud = await db.findOne({ id: uid });
        if (!ud) ud = await db.create({ id: uid, coins: 0, status_playing: "no" });
        ud.coins = parseInt(ud.coins) + prize;
        await ud.save();
        const profit = prize - userBet;
        payoutLines.push(`> 🏆 <@${uid}> ← \`${prize.toLocaleString("en-US")}\` (ربح +\`${profit.toLocaleString("en-US")}\`)`);
      }
    }
  }

  await mbUpdateEmbed(match);
  await mbPostLog(match, payoutLines);

  const resultStr = result === 0 ? "تعادل 🤝" : result === 1 ? `فاز **${match.team1}** 🏆` : `فاز **${match.team2}** 🏆`;
  const ch = client.channels.cache.get(match.channelId);
  if (ch) {
    await ch.send({
      content: `> 🏁 **نتيجة مباراة ${matchId}:** ${resultStr}\n` +
               (payoutLines.length > 0
                 ? `> 💰 **تم توزيع الأرباح على ${Object.keys(
                     payoutLines.filter(l => l.includes("🏆")).reduce((a, _) => a, {})
                   ).length || payoutLines.filter(l => !l.includes("ℹ️")).length} فائز!**`
                 : ""),
    }).catch(() => {});
  }

  await message.reply(`> ✅ تم تسجيل نتيجة مباراة **${matchId}** وتوزيع الأرباح تلقائياً!`);
});

// ── !refundmatch ──────────────────────────────────────────────
client.on("messageCreate", async (message) => {
  if (message.author.bot || !message.guild) return;
  const args = message.content.trim().split(/\s+/);
  if (args[0].toLowerCase() !== "!refundmatch") return;
  const isOwner = owners.includes(message.author.id);
  const hasPerm = permStore.canUseCommand(message.author.id, "refundmatch");
  if (!isOwner && !hasPerm) return message.reply("> ❌ ليس لديك صلاحية لاستخدام هذا الأمر.\nطلب من الإدارة: `!giveperm refundmatch @user`");

  const matchId = (args[1] || "").toUpperCase();
  if (!matchId) return message.reply("> ❌ الاستخدام: `!refundmatch <رقم_المباراة>`");

  const match = await matchBet.findOne({ matchId });
  if (!match) return message.reply(`> ❌ لم يتم إيجاد المباراة **${matchId}**.`);
  if (match.status === "finished") return message.reply(`> ❌ المباراة انتهت مسبقاً، لا يمكن إلغاؤها.`);
  if (match.status === "cancelled") return message.reply(`> ❌ المباراة ملغاة مسبقاً.`);

  match.status = "cancelled";
  await match.save();

  const refundMap = {};
  for (const b of match.bets) {
    refundMap[b.userId] = (refundMap[b.userId] || 0) + b.amount;
  }
  const payoutLines = [];
  for (const [uid, amt] of Object.entries(refundMap)) {
    let ud = await db.findOne({ id: uid });
    if (!ud) ud = await db.create({ id: uid, coins: 0, status_playing: "no" });
    ud.coins = parseInt(ud.coins) + amt;
    await ud.save();
    payoutLines.push(`> 🔄 <@${uid}> ← استرداد \`${amt.toLocaleString("en-US")}\``);
  }

  await mbUpdateEmbed(match);
  await mbPostLog(match, payoutLines);
  await message.reply(`> ✅ تم إلغاء مباراة **${matchId}** واسترداد جميع الرهانات (${Object.keys(refundMap).length} مراهن).`);
});

// ── match feed channel config ─────────────────────────────────
const MB_FEED_FILE = path.join(__dirname, "matchFeedChannel.json");
function mbGetFeedChannel() {
  try { return JSON.parse(fs.readFileSync(MB_FEED_FILE, "utf8")).channelId || null; }
  catch { return null; }
}
function mbSetFeedChannel(id) {
  fs.writeFileSync(MB_FEED_FILE, JSON.stringify({ channelId: id }));
}

// ── !setmatchchannel ──────────────────────────────────────────
client.on("messageCreate", async (message) => {
  if (message.author.bot || !message.guild) return;
  if (!message.content.trim().toLowerCase().startsWith("!setmatchchannel")) return;
  const isOwner = owners.includes(message.author.id);
  const hasPerm = permStore.canUseCommand(message.author.id, "setmatchchannel");
  if (!isOwner && !hasPerm) return message.reply("> ❌ ليس لديك صلاحية لاستخدام هذا الأمر.\nطلب من الإدارة: `!giveperm setmatchchannel @user`");
  mbSetFeedChannel(message.channel.id);
  await message.reply(`> ✅ تم تعيين هذا الروم كـ **قناة رصد المباريات التلقائي**!\n> الآن أي رسالة بصيغة \`فريق1 vs فريق2\` ستُضاف تلقائياً كمباراة جديدة.`);
});

// ── auto-detect match from feed channel ───────────────────────
// Format: Team1 vs Team2
//     or: Team1 vs Team2 | description
//     or: Team1 vs Team2 | description | deadline_minutes
client.on("messageCreate", async (message) => {
  if (message.author.bot || !message.guild) return;
  if (!owners.includes(message.author.id)) return;
  const feedChannelId = mbGetFeedChannel();
  if (!feedChannelId || message.channel.id !== feedChannelId) return;
  // Skip lines that look like bot commands
  if (message.content.trim().startsWith("!")) return;

  const raw    = message.content.trim();
  const parts  = raw.split("|").map(s => s.trim());
  const vsMatch = parts[0].match(/^(.+?)\s+vs\s+(.+)$/i);
  if (!vsMatch) return; // doesn't match pattern — ignore

  const team1        = vsMatch[1].trim();
  const team2        = vsMatch[2].trim();
  const description  = parts[1] || "";
  const deadlineMins = parts[2] ? parseInt(parts[2]) : 0;
  const deadline     = deadlineMins > 0 ? Date.now() + deadlineMins * 60_000 : 0;

  if (!team1 || !team2) return;

  const matchId  = mbNextId();
  const newMatch = await matchBet.create({
    matchId, team1, team2, description,
    channelId: message.channel.id,
    deadline,
    createdBy: message.author.id,
  });

  const embed = mbBuildEmbed(newMatch);
  const row   = mbBuildRow(matchId, "open");
  const sent  = await message.channel.send({ embeds: [embed], components: [row] });
  newMatch.msgId = sent.id;
  await newMatch.save();

  await message.react("✅").catch(() => {});
  // After 3 s delete the original message to keep channel clean
  setTimeout(() => message.delete().catch(() => {}), 3000);
});

// ── !matches — owner management panel ────────────────────────
client.on("messageCreate", async (message) => {
  if (message.author.bot || !message.guild) return;
  if (message.content.trim().toLowerCase() !== "!matches") return;
  const isOwner = owners.includes(message.author.id);
  const hasPerm = permStore.canUseCommand(message.author.id, "matches");
  if (!isOwner && !hasPerm)
    return message.reply("> ❌ ليس لديك صلاحية لاستخدام هذا الأمر.\nطلب من الإدارة: `!giveperm matches @user`");

  const allMatches = await matchBet
    .find({ status: { $in: ["open", "closed"] } })
    .sort({ createdAt: -1 })
    .limit(10);

  if (allMatches.length === 0)
    return message.reply("> 📭 لا توجد مباريات نشطة حالياً. أضف مباراة في قناة الرصد أو استخدم `!addmatch`.");

  await message.reply({ content: "> 🏟️ **لوحة إدارة المباريات** — اضغط على الأزرار لإدارة كل مباراة:" });

  for (const m of allMatches) {
    const t1Total = mbTeamTotal(m, 1);
    const t2Total = mbTeamTotal(m, 2);
    const pot     = t1Total + t2Total;
    const dl      = m.deadline > 0 ? `<t:${Math.floor(m.deadline / 1000)}:R>` : "بلا وقت";

    const panelEmbed = new Discord.MessageEmbed()
      .setColor(m.status === "open" ? "#2ECC71" : "#E74C3C")
      .setTitle(`🏟️ ${m.matchId} — ${m.team1}  vs  ${m.team2}`)
      .setDescription(
        (m.description ? `> 📝 ${m.description}\n` : "") +
        `> 📊 **الحالة:** ${mbStatusEmoji(m.status)}\n` +
        `> ⏱️ **الإغلاق:** ${dl}\n` +
        `> ━━━━━━━━━━━━━━━━━━━━\n` +
        `> 🔵 **${m.team1}:** \`${t1Total.toLocaleString("en-US")}\` | 👥 ${mbTeamCount(m, 1)} رهان | 📈 ${mbOdds(m, 1)}\n` +
        `> 🔴 **${m.team2}:** \`${t2Total.toLocaleString("en-US")}\` | 👥 ${mbTeamCount(m, 2)} رهان | 📈 ${mbOdds(m, 2)}\n` +
        `> 💵 **البوت الكلي:** \`${pot.toLocaleString("en-US")}\``
      );

    const row1 = new MessageActionRow().addComponents(
      new MessageButton().setCustomId(`mbp_close_${m.matchId}`).setLabel("🔴 إغلاق الرهانات").setStyle("SECONDARY").setDisabled(m.status !== "open"),
      new MessageButton().setCustomId(`mbp_log_${m.matchId}`).setLabel("📋 السجل").setStyle("SECONDARY"),
    );
    const row2 = new MessageActionRow().addComponents(
      new MessageButton().setCustomId(`mbp_r1_${m.matchId}`).setLabel(`🏆 فاز ${m.team1}`).setStyle("PRIMARY"),
      new MessageButton().setCustomId(`mbp_r2_${m.matchId}`).setLabel(`🏆 فاز ${m.team2}`).setStyle("DANGER"),
      new MessageButton().setCustomId(`mbp_draw_${m.matchId}`).setLabel("🤝 تعادل").setStyle("SECONDARY"),
      new MessageButton().setCustomId(`mbp_refund_${m.matchId}`).setLabel("↩️ استرداد").setStyle("DANGER"),
    );

    await message.channel.send({ embeds: [panelEmbed], components: [row1, row2] });
  }
});

