// ── panel button: show log ────────────────────────────────────
client.on("interactionCreate", async (interaction) => {
  if (!interaction.isButton()) return;
  if (!interaction.customId.startsWith("mbp_log_")) return;
  if (!owners.includes(interaction.user.id))
    return interaction.reply({ content: "> ❌ للإدارة فقط.", ephemeral: true });
  const matchId = interaction.customId.slice("mbp_log_".length);
  const match   = await matchBet.findOne({ matchId });
  if (!match) return interaction.reply({ content: "> ❌ المباراة غير موجودة.", ephemeral: true });

  const t1Total = mbTeamTotal(match, 1);
  const t2Total = mbTeamTotal(match, 2);
  const pot     = t1Total + t2Total;
  const t1Lines = match.bets.filter(b => b.side === 1).map(b => `> 🔵 <@${b.userId}> — \`${b.amount.toLocaleString("en-US")}\``);
  const t2Lines = match.bets.filter(b => b.side === 2).map(b => `> 🔴 <@${b.userId}> — \`${b.amount.toLocaleString("en-US")}\``);
  const all = [...t1Lines.slice(0, 12), t1Lines.length > 0 && t2Lines.length > 0 ? `> ───────────` : "", ...t2Lines.slice(0, 12)].filter(Boolean);

  const embed = new Discord.MessageEmbed()
    .setColor("#032943")
    .setTitle(`📋 سجل ${matchId} — ${match.team1} vs ${match.team2}`)
    .setDescription(
      `> 🔵 **${match.team1}:** \`${t1Total.toLocaleString("en-US")}\` | معامل ${mbOdds(match, 1)}\n` +
      `> 🔴 **${match.team2}:** \`${t2Total.toLocaleString("en-US")}\` | معامل ${mbOdds(match, 2)}\n` +
      `> 💵 **البوت:** \`${pot.toLocaleString("en-US")}\`\n` +
      `> ━━━━━━━━━━━━━━━━━━━━\n` +
      (all.length > 0 ? all.join("\n") : "> *لا توجد رهانات بعد*")
    )
    .setTimestamp();

  await interaction.reply({ embeds: [embed], ephemeral: true });
});

// ── panel button: declare result (team1 / team2 / draw / refund) ─
async function mbHandlePanelResult(interaction, matchId, result) {
  if (!owners.includes(interaction.user.id))
    return interaction.reply({ content: "> ❌ للإدارة فقط.", ephemeral: true });

  const match = await matchBet.findOne({ matchId });
  if (!match) return interaction.reply({ content: "> ❌ المباراة غير موجودة.", ephemeral: true });
  if (match.status === "finished") return interaction.reply({ content: "> ❌ المباراة انتهت مسبقاً.", ephemeral: true });
  if (match.status === "cancelled") return interaction.reply({ content: "> ❌ المباراة ملغاة مسبقاً.", ephemeral: true });

  await interaction.deferReply({ ephemeral: false });

  const isRefund = result === "refund";
  match.status = isRefund ? "cancelled" : "finished";
  if (!isRefund) match.result = result; // 0, 1, or 2
  await match.save();

  const payoutLines = [];
  const pot         = mbTotalPot(match);

  if (isRefund || result === 0) {
    const refundMap = {};
    for (const b of match.bets) refundMap[b.userId] = (refundMap[b.userId] || 0) + b.amount;
    for (const [uid, amt] of Object.entries(refundMap)) {
      let ud = await db.findOne({ id: uid });
      if (!ud) ud = await db.create({ id: uid, coins: 0, status_playing: "no" });
      ud.coins = parseInt(ud.coins) + amt; await ud.save();
      payoutLines.push(`> 🔄 <@${uid}> ← استرداد \`${amt.toLocaleString("en-US")}\``);
    }
  } else {
    const winningSide  = result;
    const winningTotal = mbTeamTotal(match, winningSide);
    if (winningTotal === 0) {
      for (const b of match.bets) {
        let ud = await db.findOne({ id: b.userId });
        if (!ud) ud = await db.create({ id: b.userId, coins: 0, status_playing: "no" });
        ud.coins = parseInt(ud.coins) + b.amount; await ud.save();
      }
      payoutLines.push(`> ℹ️ لا أحد راهن على الفريق الفائز — تم إرجاع جميع الرهانات.`);
    } else {
      const netPot    = pot - Math.floor(pot * taxRate);
      const winnerMap = {};
      for (const b of match.bets.filter(b => b.side === winningSide))
        winnerMap[b.userId] = (winnerMap[b.userId] || 0) + b.amount;
      for (const [uid, userBet] of Object.entries(winnerMap)) {
        const prize  = Math.floor((userBet / winningTotal) * netPot);
        const profit = prize - userBet;
        let ud = await db.findOne({ id: uid });
        if (!ud) ud = await db.create({ id: uid, coins: 0, status_playing: "no" });
        ud.coins = parseInt(ud.coins) + prize; await ud.save();
        payoutLines.push(`> 🏆 <@${uid}> ← \`${prize.toLocaleString("en-US")}\` (+\`${profit.toLocaleString("en-US")}\`)`);
      }
    }
  }

  await mbUpdateEmbed(match);
  await mbPostLog(match, payoutLines);

  const winnerCount = payoutLines.filter(l => l.includes("🏆")).length;
  let resultStr;
  if (isRefund)       resultStr = "↩️ تم الإلغاء واسترداد الرهانات";
  else if (result===0) resultStr = "🤝 تعادل — تم إرجاع الرهانات";
  else if (result===1) resultStr = `🏆 فاز **${match.team1}**`;
  else                 resultStr = `🏆 فاز **${match.team2}**`;

  const ch = client.channels.cache.get(match.channelId);
  if (ch && !isRefund) {
    await ch.send({
      content: `> 🏁 **نتيجة ${matchId}:** ${resultStr}` +
        (winnerCount > 0 ? ` | 💰 تم الدفع لـ **${winnerCount}** فائز!` : ""),
    }).catch(() => {});
  }

  await interaction.editReply({
    content: `> ✅ **${matchId}:** ${resultStr} — تم توزيع الأرباح تلقائياً!\n` +
      payoutLines.slice(0, 15).join("\n"),
  });
}

client.on("interactionCreate", async (interaction) => {
  if (!interaction.isButton()) return;
  if (interaction.customId.startsWith("mbp_r1_"))     await mbHandlePanelResult(interaction, interaction.customId.slice("mbp_r1_".length), 1);
  else if (interaction.customId.startsWith("mbp_r2_")) await mbHandlePanelResult(interaction, interaction.customId.slice("mbp_r2_".length), 2);
  else if (interaction.customId.startsWith("mbp_draw_"))   await mbHandlePanelResult(interaction, interaction.customId.slice("mbp_draw_".length), 0);
  else if (interaction.customId.startsWith("mbp_refund_")) await mbHandlePanelResult(interaction, interaction.customId.slice("mbp_refund_".length), "refund");
});

// ── !missions ─────────────────────────────────────────────────
client.on("messageCreate", async (message) => {
  if (message.author.bot || !message.guild) return;
  if (message.content.trim().toLowerCase() !== "!missions") return;

  const userId = message.author.id;
  const date = missionToday();
  let doc = await dailyMission.findOne({ userId, date }).catch(()=>null);
  if (!doc) {
    doc = await dailyMission.create({
      userId, date,
      missions: [...BOT_MISSION_DEFS.map(m=>({id:m.id,progress:0,claimed:false})),
                 {id:"login_site",progress:0,claimed:false}]
    }).catch(()=>null);
  }

  const LABELS = { play_3:"🎮 Play 3 Games", win_2:"🏆 Win 2 Games", bet_5000:"💰 Bet 5,000 Coins", login_site:"🌐 Login to Website" };
  const REWARDS = { play_3:500, win_2:1000, bet_5000:750, login_site:200 };
  const TARGETS = { play_3:3, win_2:2, bet_5000:5000, login_site:1 };
  const allDefs = ["play_3","win_2","bet_5000","login_site"];

  const fields = allDefs.map(id => {
    const prog = doc?.missions?.find(m=>m.id===id)||{progress:0,claimed:false};
    const target = TARGETS[id];
    const pct = Math.min(100, Math.floor((prog.progress/target)*100));
    const bar = "█".repeat(Math.floor(pct/10))+"░".repeat(10-Math.floor(pct/10));
    const status = prog.claimed?"✅ Claimed":prog.progress>=target?"🎁 Ready to Claim (visit website)":"⏳ In Progress";
    return {
      name: `${LABELS[id]} — +${REWARDS[id]} 💰`,
      value: `> \`[${bar}]\` ${Math.min(prog.progress,target)}/${target}\n> ${status}`,
      inline: false
    };
  });

  const embed = new Discord.MessageEmbed()
    .setColor("#032943")
    .setTitle("📋 Daily Missions")
    .setDescription(`> Missions reset every day at midnight UTC.\n> Claim rewards on the website!`)
    .addFields(fields)
    .setFooter({ text: `${message.author.tag} • ${date}` })
    .setTimestamp();

  await message.reply({ embeds: [embed] });
});

// ── !mybets ───────────────────────────────────────────────────
client.on("messageCreate", async (message) => {
  if (message.author.bot || !message.guild) return;
  if (message.content.trim().toLowerCase() !== "!mybets") return;

  const allMatches = await matchBet.find({ "bets.userId": message.author.id, status: { $in: ["open","closed","finished"] } })
    .sort({ createdAt: -1 }).limit(15);

  if (allMatches.length === 0)
    return message.reply("> 📭 ليس لديك أي رهانات سابقة.");

  const lines = [];
  for (const m of allMatches) {
    const userBets = m.bets.filter(b => b.userId === message.author.id);
    const totalBet = userBets.reduce((s, b) => s + b.amount, 0);
    const side     = userBets[0]?.side;
    const teamName = side === 1 ? m.team1 : side === 2 ? m.team2 : "—";
    let statusIcon = mbStatusEmoji(m.status);
    if (m.status === "finished") {
      if (m.result === 0) statusIcon = "🤝 تعادل (استرداد)";
      else if (m.result === side) statusIcon = "✅ فزت";
      else statusIcon = "❌ خسرت";
    }
    lines.push(`> **${m.matchId}** — ${m.team1} vs ${m.team2}\n> رهانك: \`${totalBet.toLocaleString("en-US")}\` على **${teamName}** | ${statusIcon}`);
  }

  const embed = new Discord.MessageEmbed()
    .setColor("#032943")
    .setTitle(`📋 رهاناتي — ${message.author.tag}`)
    .setDescription(lines.join("\n> ─────────────────────\n"))
    .setTimestamp();

  await message.reply({ embeds: [embed] });
});

