// ── shared bet placement logic ────────────────────────────────
async function mbParsAmount(raw) {
  const cleaned = raw
    .replace(/,/g, "")
    .replace(/k/gi, "000")
    .replace(/m/gi, "000000")
    .replace(/ك/g, "000")
    .replace(/م/g, "000000");
  const num = parseFloat(cleaned);
  if (isNaN(num) || num <= 0) return null;
  return Math.floor(num);
}

async function mbPlaceBet(message, match, side, amtRaw) {
  const amount = await mbParsAmount(amtRaw);
  if (!amount || amount < 1000)
    return message.reply("> ❌ المبلغ غير صحيح. الحد الأدنى للرهان هو `1,000`.");

  let userData = await db.findOne({ id: message.author.id });
  if (!userData) userData = await db.create({ id: message.author.id, coins: 0, status_playing: "no" });
  if (parseInt(userData.coins) < amount)
    return message.reply(`> ❌ رصيدك غير كافٍ! لديك \`${parseInt(userData.coins).toLocaleString("en-US")}\` وتحتاج \`${amount.toLocaleString("en-US")}\`.`);

  userData.coins = parseInt(userData.coins) - amount;
  await userData.save();

  match.bets.push({ userId: message.author.id, amount, side });
  await match.save();
  await mbUpdateEmbed(match);

  const teamName = side === 1 ? match.team1 : match.team2;
  const pot      = mbTotalPot(match);
  const userTotal= match.bets.filter(b => b.userId === message.author.id && b.side === side)
    .reduce((s, b) => s + b.amount, 0);
  const sideTotal= mbTeamTotal(match, side);
  const projectedPrize = sideTotal > 0 ? Math.floor((userTotal / sideTotal) * (pot * (1 - taxRate))) : 0;

  return message.reply(
    `> ✅ **تم تسجيل رهانك!**\n` +
    `> 🏟️ **المباراة:** ${match.matchId} — ${match.team1} vs ${match.team2}\n` +
    `> ⚽ **فريقك:** ${teamName}\n` +
    `> 💰 **رهانك:** \`${amount.toLocaleString("en-US")}\`\n` +
    `> 🎯 **الربح المتوقع لو فزت:** \`${projectedPrize.toLocaleString("en-US")}\``
  );
}

