// ════════════════════════════════════════════════════════════
// 🎁  BONUS SYSTEM (Modified for multi-bank support)
// ════════════════════════════════════════════════════════════
const BONUS_CFG_FILE    = path.join(__dirname, "bonusConfig.json");
const BONUS_LEDGER_FILE = path.join(__dirname, "bonusLedger.json");

function bonusReadCfg() {
  try { return JSON.parse(fs.readFileSync(BONUS_CFG_FILE, "utf8")); }
  catch { return { active: false, min: 0, max: 0, endsAt: 0, logChannelId: "" }; }
}
function bonusWriteCfg(data) { fs.writeFileSync(BONUS_CFG_FILE, JSON.stringify(data, null, 2)); }

function bonusReadLedger() {
  try { return JSON.parse(fs.readFileSync(BONUS_LEDGER_FILE, "utf8")); }
  catch { return {}; }
}
function bonusWriteLedger(data) { fs.writeFileSync(BONUS_LEDGER_FILE, JSON.stringify(data, null, 2)); }

function bonusIsActive() {
  const cfg = bonusReadCfg();
  return cfg.active && cfg.endsAt > Date.now();
}

// Apply bonus after a deposit — called from both deposit paths
// Returns bonus info so calling code can add it to the deposit total
async function applyBonus(userId, depositAmount, channelOrNull) {
  if (!bonusIsActive()) return { bonusAmount: 0, pct: 0 };

  const cfg = bonusReadCfg();
  const pct = parseFloat((Math.random() * (cfg.max - cfg.min) + cfg.min).toFixed(2));
  const bonusAmount = Math.floor(depositAmount * pct / 100);

  if (bonusAmount < 1) return { bonusAmount: 0, pct: 0 };

  // Apply coins directly to DB immediately
  let ud = await db.findOne({ id: userId }).catch(() => null);
  if (!ud) ud = await db.create({ id: userId, coins: 0, status_playing: "no" }).catch(() => null);
  if (ud) {
    ud.coins = parseInt(ud.coins || 0) + bonusAmount;
    await ud.save().catch(() => {});
  }

  // Notify user in the deposit channel if provided
  if (channelOrNull) {
    const notifEmbed = new Discord.MessageEmbed()
      .setColor("#032943")
      .setTitle("🎁 بونص مفعّل!")
      .setDescription(
        `> 🎲 **نسبتك العشوائية:** \`${pct}%\`\n` +
        `> 💰 **مبلغ البونص:** \`${bonusAmount.toLocaleString("en-US")}\`\n` +
        `> ✅ **تمت إضافة البونص فوراً لرصيدك!**`
      )
      .setFooter({ text: "🎁 البونص العشوائي • Diamond Casino" })
      .setTimestamp();
    channelOrNull.send({ content: `<@${userId}>`, embeds: [notifEmbed] }).catch(() => {});
  }

  // Log to bonus channel
  const logCh = client.channels.cache.get(cfg.logChannelId || "");
  if (logCh) {
    const logEmbed = new Discord.MessageEmbed()
      .setColor("#032943")
      .setTitle("📋 سجل البونص")
      .setDescription(
        `> 👤 **العضو:** <@${userId}>\n` +
        `> 💵 **مبلغ الشحن:** \`${depositAmount.toLocaleString("en-US")}\`\n` +
        `> 🎲 **النسبة:** \`${pct}%\`\n` +
        `> 🎁 **البونص:** \`${bonusAmount.toLocaleString("en-US")}\`\n` +
        `> ✅ **أُضيف للرصيد فوراً**`
      )
      .setTimestamp();
    logCh.send({ embeds: [logEmbed] }).catch(() => {});
  }

  return { bonusAmount, pct };
}

// Make applyBonus available globally for self.js
global.applyBonus = applyBonus;

// Auto-unlock interval — every 60 seconds, move unlocked bonuses into user coins
setInterval(async () => {
  try {
    const ledger = bonusReadLedger();
    const cfg    = bonusReadCfg();
    let changed  = false;
    for (const [userId, entries] of Object.entries(ledger)) {
      const now     = Date.now();
      const unlocked = entries.filter(e => e.unlocksAt <= now);
      if (unlocked.length === 0) continue;

      const totalBonus = unlocked.reduce((s, e) => s + e.amount, 0);
      let ud = await db.findOne({ id: userId });
      if (!ud) ud = await db.create({ id: userId, coins: 0, status_playing: "no" });
      ud.coins = parseInt(ud.coins) + totalBonus;
      await ud.save();

      ledger[userId] = entries.filter(e => e.unlocksAt > now);
      changed = true;

      // Notify user
      try {
        const user = await client.users.fetch(userId);
        if (user) {
          user.send({
            embeds: [
              new Discord.MessageEmbed()
                .setColor("#032943")
                .setTitle("🔓 تم فتح البونص!")
                .setDescription(
                  `> 🎁 **البونص:** \`${totalBonus.toLocaleString("en-US")}\` تمت إضافته لرصيدك!\n` +
                  `> 💰 **رصيدك الجديد:** \`${parseInt(ud.coins).toLocaleString("en-US")}\``
                )
                .setFooter({ text: "🎁 البونص العشوائي • Diamond Casino" })
                .setTimestamp(),
            ],
          }).catch(() => {});
        }
      } catch {}

      // Log unlock
      const logCh = client.channels.cache.get(cfg.logChannelId || "");
      if (logCh) {
        logCh.send({
          embeds: [
            new Discord.MessageEmbed()
              .setColor("#032943")
              .setTitle("🔓 بونص مُفتح")
              .setDescription(
                `> 👤 **العضو:** <@${userId}>\n` +
                `> 🎁 **البونص المُضاف:** \`${totalBonus.toLocaleString("en-US")}\`\n` +
                `> ✅ **تمت الإضافة للرصيد تلقائياً**`
              )
              .setTimestamp(),
          ],
        }).catch(() => {});
      }
    }
    if (changed) bonusWriteLedger(ledger);
  } catch {}
}, 60_000);

// ── !bonus — owner only ───────────────────────────────────────
// Usage: !bonus <min>-<max> <duration>
// Example: !bonus 0.1-300 1h | !bonus 10-50 30m | !bonus 5-200 2h
client.on("messageCreate", async (message) => {
  if (message.author.bot || !message.guild) return;
  if (!message.content.trim().toLowerCase().startsWith("!bonus ")) return;
  const isOwner = owners.includes(message.author.id);
  const hasPerm = permStore.canUseCommand(message.author.id, "bonus");
  if (!isOwner && !hasPerm) {
    return message.reply("> ❌ ليس لديك صلاحية لاستخدام هذا الأمر.\nطلب من الإدارة: `!giveperm bonus @user`");
  }

  const args = message.content.trim().split(/\s+/);
  if (args.length < 3)
    return message.reply("> ❌ الاستخدام: `!bonus <min>-<max> <مدة>`\n> مثال: `!bonus 0.1-300 1h` أو `!bonus 10-50 30m`");

  const rangePart = args[1];
  const durPart   = args[2];

  const rangeSplit = rangePart.split("-");
  if (rangeSplit.length !== 2) return message.reply("> ❌ النطاق يجب أن يكون بصيغة `min-max` مثال: `0.1-300`");
  const minPct = parseFloat(rangeSplit[0]);
  const maxPct = parseFloat(rangeSplit[1]);
  if (isNaN(minPct) || isNaN(maxPct) || minPct < 0 || maxPct <= minPct)
    return message.reply("> ❌ النطاق غير صحيح. min يجب أن يكون أصغر من max وكلاهما أرقام موجبة.");

  const durMs = ms(durPart);
  if (!durMs || durMs < 60_000)
    return message.reply("> ❌ المدة غير صحيحة. الحد الأدنى دقيقة واحدة. مثال: `30m` `1h` `2h` `1d`");

  const endsAt = Date.now() + durMs;
  const cfg    = bonusReadCfg();
  bonusWriteCfg({ ...cfg, active: true, min: minPct, max: maxPct, endsAt });

  const embed = new Discord.MessageEmbed()
    .setColor("#032943")
    .setTitle("🎁 تفعيل بونص عام عشوائي!")
    .setDescription(
      "```\n╔══════════════════════════════════╗\n║    تم تفعيل البونص العام بنجاح!   ║\n╚══════════════════════════════════╝\n```"
    )
    .addFields(
      { name: "🎲 النسب العشوائية", value: `> كل عملية شحن ستحصل على نسبة عشوائية جديدة!`, inline: false },
      { name: "📊 نطاق النسبة الجديد", value: `\`\`\`\n${minPct}% — ${maxPct}%\n\`\`\``, inline: true },
      { name: "⏱️ ينتهي البونص", value: `<t:${Math.floor(endsAt / 1000)}:R>`, inline: true },
      { name: "🔓 يمكن سحب البونص بعد", value: `> **2 ساعة من الشحن**`, inline: false },
      { name: "💡 ملاحظة", value: `> كل مستخدم يشحن سيحصل على نسبة عشوائية ضمن النطاق المحدد!`, inline: false },
    )
    .setFooter({ text: `✅ فُعِّل بواسطة ${message.author.tag} • Diamond Casino` })
    .setTimestamp();

  await message.reply({ embeds: [embed] });

  // Log to bonus channel
  const logCh = client.channels.cache.get(cfg.logChannelId || "");
  if (logCh) {
    logCh.send({
      embeds: [
        new Discord.MessageEmbed()
          .setColor("#032943")
          .setTitle("🎁 بونص جديد مُفعَّل")
          .setDescription(
            `> 👑 **فُعِّل بواسطة:** ${message.author}\n` +
            `> 📊 **النطاق:** \`${minPct}% — ${maxPct}%\`\n` +
            `> ⏱️ **ينتهي:** <t:${Math.floor(endsAt / 1000)}:F>\n` +
            `> 🔒 **قفل السحب:** 2 ساعة من كل شحن`
          )
          .setTimestamp(),
      ],
    }).catch(() => {});
  }
});

