// ================================================================
// CASE BATTLE — معركة الصناديق (PvP)
// ================================================================
// !casebattle @user <amount> — كل لاعب يفتح صندوقاً، أعلى قيمة تفوز
// ================================================================

const CB_ITEMS = [
  { name: "بندقية ذهبية",   emoji: "🔫", tier: "legendary", weight: 1,  minPct: 700, maxPct: 1000 },
  { name: "سيف الأبطال",    emoji: "⚔️",  tier: "legendary", weight: 2,  minPct: 500, maxPct: 700  },
  { name: "درع الملوك",     emoji: "🛡️",  tier: "epic",      weight: 5,  minPct: 300, maxPct: 500  },
  { name: "قنبلة يدوية",    emoji: "💣",  tier: "epic",      weight: 8,  minPct: 200, maxPct: 300  },
  { name: "سكين المصارع",   emoji: "🗡️",  tier: "rare",      weight: 15, minPct: 120, maxPct: 200  },
  { name: "ضربة الفارس",    emoji: "🏹",  tier: "rare",      weight: 15, minPct: 80,  maxPct: 120  },
  { name: "درع المقاتل",    emoji: "🪖",  tier: "uncommon",  weight: 30, minPct: 40,  maxPct: 80   },
  { name: "حذاء السرعة",    emoji: "👟",  tier: "uncommon",  weight: 30, minPct: 20,  maxPct: 40   },
  { name: "صخرة",           emoji: "🪨",  tier: "common",    weight: 50, minPct: 5,   maxPct: 20   },
  { name: "قطعة خشب",       emoji: "🪵",  tier: "common",    weight: 60, minPct: 1,   maxPct: 10   },
];

const CB_TIER_COLORS = {
  legendary: "🟡", epic: "🟠", rare: "🔵", uncommon: "⚪", common: "⬛"
};

function cbPickItem() {
  const total = CB_ITEMS.reduce((s, i) => s + i.weight, 0);
  let rng = Math.random() * total;
  for (const item of CB_ITEMS) {
    rng -= item.weight;
    if (rng <= 0) {
      const pct = item.minPct + Math.random() * (item.maxPct - item.minPct);
      return { ...item, pct: Math.round(pct) };
    }
  }
  return { ...CB_ITEMS[CB_ITEMS.length - 1], pct: 5 };
}

const cbGames = new Map(); // msgId → { p1id, p2id, betAmt, p1opened, p2opened, p1item, p2item }

// ── !casebattle command ────────────────────────────────────────
client.on("messageCreate", async (message) => {
  if (message.author.bot || !message.guild) return;
  const args = message.content.trim().split(/\s+/);
  if (args[0].toLowerCase() !== "!casebattle") return;

  const target = message.mentions.users.first();
  if (!target || target.bot || target.id === message.author.id)
    return message.reply("> ❌ **يجب تحديد عضو آخر للتحدي.**\n> المثال: `!casebattle @عضو 5000`");

  const betStr = args[2] || args[1]; // allow !casebattle @x 5000 or !casebattle 5000 @x
  const betAmt = parseInt(String(betStr).replace(/[^0-9]/g, ""));
  if (!betAmt || betAmt < 1000)
    return message.reply("> ❌ **الحد الأدنى للرهان هو 1,000 عملة.**");

  const p1data = await db.findOne({ id: message.author.id });
  if (!p1data || parseInt(p1data.coins) < betAmt)
    return message.reply("> ❌ **رصيدك لا يكفي لهذا التحدي.**");
  if (p1data.status_playing === "yes")
    return message.reply("> ❌ **أنت في لعبة أخرى حالياً.**");

  const p2data = await db.findOne({ id: target.id });
  if (!p2data || parseInt(p2data.coins) < betAmt)
    return message.reply(`> ❌ **رصيد ${target} لا يكفي للتحدي.**`);
  if (p2data.status_playing === "yes")
    return message.reply(`> ❌ **${target} في لعبة أخرى حالياً.**`);

  const challengeEmbed = new Discord.MessageEmbed()
    .setColor("#032943")
    .setTitle("📦 تحدي معركة الصناديق!")
    .setDescription(
      `> 🧑 **المتحدي:** ${message.author}\n` +
      `> 🎯 **المتحدَى:** ${target}\n` +
      `> 💰 **الرهان:** \`${betAmt.toLocaleString("en-US")}\` عملة لكل لاعب\n` +
      `> 🏆 **الجائزة:** \`${(betAmt * 2).toLocaleString("en-US")}\` (قبل الضريبة)\n` +
      `> ━━━━━━━━━━━━━━━━━━━━\n` +
      `> كل لاعب يفتح صندوقاً عشوائياً — صاحب أعلى نسبة يفوز بالكل!`
    )
    .setFooter({ text: "معركة الصناديق • Diamond Casino" })
    .setTimestamp();

  const row = new Discord.MessageActionRow().addComponents(
    new Discord.MessageButton().setCustomId("cb_accept_PLACEHOLDER").setLabel("✅ قبول التحدي").setStyle("SUCCESS"),
    new Discord.MessageButton().setCustomId("cb_reject_PLACEHOLDER").setLabel("❌ رفض").setStyle("DANGER"),
  );

  const sent = await message.channel.send({ content: `> 📦 ${target} — لديك تحدي!`, embeds: [challengeEmbed], components: [row] });

  // Set correct msgId in buttons
  const row2 = new Discord.MessageActionRow().addComponents(
    new Discord.MessageButton().setCustomId(`cb_accept_${sent.id}`).setLabel("✅ قبول التحدي").setStyle("SUCCESS"),
    new Discord.MessageButton().setCustomId(`cb_reject_${sent.id}`).setLabel("❌ رفض").setStyle("DANGER"),
  );
  await sent.edit({ components: [row2] });

  cbGames.set(sent.id, {
    msgId: sent.id, channelId: message.channel.id,
    p1id: message.author.id, p2id: target.id,
    betAmt, p1opened: false, p2opened: false,
    p1item: null, p2item: null,
  });

  // Timeout after 60s
  setTimeout(async () => {
    const g = cbGames.get(sent.id);
    if (!g) return;
    cbGames.delete(sent.id);
    await sent.edit({ content: "> ⏰ **انتهت مهلة قبول التحدي.**", embeds: [], components: [] }).catch(() => {});
  }, 60000);
});

// ── cb_reject ──────────────────────────────────────────────────
client.on("interactionCreate", async (interaction) => {
  if (!interaction.isButton()) return;
  if (!interaction.customId.startsWith("cb_reject_")) return;
  const msgId = interaction.customId.slice("cb_reject_".length);
  const g = cbGames.get(msgId);
  if (!g) return interaction.reply({ content: "> ❌ التحدي انتهى.", ephemeral: true });
  if (interaction.user.id !== g.p2id && interaction.user.id !== g.p1id)
    return interaction.reply({ content: "> ❌ هذا التحدي ليس لك.", ephemeral: true });
  cbGames.delete(msgId);
  await interaction.update({ content: `> ❌ **تم رفض التحدي.**`, embeds: [], components: [] });
});

// ── cb_accept ──────────────────────────────────────────────────
client.on("interactionCreate", async (interaction) => {
  if (!interaction.isButton()) return;
  if (!interaction.customId.startsWith("cb_accept_")) return;
  const msgId = interaction.customId.slice("cb_accept_".length);
  const g = cbGames.get(msgId);
  if (!g) return interaction.reply({ content: "> ❌ التحدي انتهى.", ephemeral: true });
  if (interaction.user.id !== g.p2id)
    return interaction.reply({ content: "> ❌ هذا التحدي ليس لك.", ephemeral: true });

  // Lock funds from both players
  let d1 = await db.findOne({ id: g.p1id });
  let d2 = await db.findOne({ id: g.p2id });
  if (!d1 || parseInt(d1.coins) < g.betAmt)
    return interaction.reply({ content: "> ❌ رصيد المتحدي لم يعد كافياً.", ephemeral: true });
  if (!d2 || parseInt(d2.coins) < g.betAmt)
    return interaction.reply({ content: "> ❌ رصيدك لم يعد كافياً.", ephemeral: true });

  d1.coins = parseInt(d1.coins) - g.betAmt; d1.status_playing = "yes"; await d1.save();
  d2.coins = parseInt(d2.coins) - g.betAmt; d2.status_playing = "yes"; await d2.save();

  const gameEmbed = new Discord.MessageEmbed()
    .setColor("#032943")
    .setTitle("📦 معركة الصناديق — بدأت!")
    .setDescription(
      `> 💰 **البوت:** \`${(g.betAmt * 2).toLocaleString("en-US")}\`\n` +
      `> ━━━━━━━━━━━━━━━━━━━━\n` +
      `> 📦 <@${g.p1id}> — ${g.p1opened ? "✅ فتح الصندوق" : "⏳ لم يفتح بعد"}\n` +
      `> 📦 <@${g.p2id}> — ${g.p2opened ? "✅ فتح الصندوق" : "⏳ لم يفتح بعد"}\n` +
      `> ━━━━━━━━━━━━━━━━━━━━\n` +
      `> اضغط **فتح الصندوق** لكشف جائزتك!`
    )
    .setFooter({ text: "معركة الصناديق • Diamond Casino" })
    .setTimestamp();

  const openRow = new Discord.MessageActionRow().addComponents(
    new Discord.MessageButton().setCustomId(`cb_open_${msgId}`).setLabel("📦 فتح الصندوق!").setStyle("PRIMARY"),
  );

  await interaction.update({ content: `> || <@${g.p1id}> | <@${g.p2id}> ||`, embeds: [gameEmbed], components: [openRow] });
});

// ── cb_open — player opens their case ──────────────────────────
client.on("interactionCreate", async (interaction) => {
  if (!interaction.isButton()) return;
  if (!interaction.customId.startsWith("cb_open_")) return;
  const msgId = interaction.customId.slice("cb_open_".length);
  const g = cbGames.get(msgId);
  if (!g) return interaction.reply({ content: "> ❌ اللعبة انتهت.", ephemeral: true });

  const isP1 = interaction.user.id === g.p1id;
  const isP2 = interaction.user.id === g.p2id;
  if (!isP1 && !isP2) return interaction.reply({ content: "> ❌ أنت لست في هذه اللعبة.", ephemeral: true });

  if (isP1 && g.p1opened) return interaction.reply({ content: "> ⚠️ لقد فتحت صندوقك بالفعل!", ephemeral: true });
  if (isP2 && g.p2opened) return interaction.reply({ content: "> ⚠️ لقد فتحت صندوقك بالفعل!", ephemeral: true });

  const item = cbPickItem();
  if (isP1) { g.p1opened = true; g.p1item = item; }
  else       { g.p2opened = true; g.p2item = item; }
  cbGames.set(msgId, g);

  const tierLabel = { legendary: "أسطوري 🟡", epic: "ملحمي 🟠", rare: "نادر 🔵", uncommon: "غير شائع ⚪", common: "عادي ⬛" };
  await interaction.reply({
    content:
      `> 📦 **فتحت صندوقك!**\n` +
      `> ${item.emoji} **${item.name}** — ${tierLabel[item.tier]}\n` +
      `> 📊 **قيمتك:** \`${item.pct}%\`\n` +
      `> ⏳ بانتظار الخصم الآخر...`,
    ephemeral: true,
  });

  // Update the public game embed
  const ch = client.channels.cache.get(g.channelId);
  const msg = ch ? await ch.messages.fetch(msgId).catch(() => null) : null;
  if (msg) {
    const updEmbed = new Discord.MessageEmbed()
      .setColor("#032943")
      .setTitle("📦 معركة الصناديق — بدأت!")
      .setDescription(
        `> 💰 **البوت:** \`${(g.betAmt * 2).toLocaleString("en-US")}\`\n` +
        `> ━━━━━━━━━━━━━━━━━━━━\n` +
        `> 📦 <@${g.p1id}> — ${g.p1opened ? "✅ فتح الصندوق" : "⏳ لم يفتح بعد"}\n` +
        `> 📦 <@${g.p2id}> — ${g.p2opened ? "✅ فتح الصندوق" : "⏳ لم يفتح بعد"}\n` +
        `> ━━━━━━━━━━━━━━━━━━━━\n` +
        `> اضغط **فتح الصندوق** لكشف جائزتك!`
      )
      .setFooter({ text: "معركة الصناديق • Diamond Casino" })
      .setTimestamp();
    const openRow = new Discord.MessageActionRow().addComponents(
      new Discord.MessageButton().setCustomId(`cb_open_${msgId}`).setLabel("📦 فتح الصندوق!").setStyle("PRIMARY"),
    );
    await msg.edit({ embeds: [updEmbed], components: [openRow] }).catch(() => {});
  }

  // Both opened — resolve
  if (!g.p1opened || !g.p2opened) return;
  cbGames.delete(msgId);

  const p1 = g.p1item, p2 = g.p2item;
  const pot  = g.betAmt * 2;
  const tax  = Math.floor(pot * taxRate);
  const prize = pot - tax;

  let winnerId, loserId, winItem, loseItem;
  let resultLine = "";

  if (p1.pct === p2.pct) {
    // Draw — refund both
    let db1 = await db.findOne({ id: g.p1id }); if (!db1) db1 = await db.create({ id: g.p1id, coins: 0, status_playing: "no" });
    let db2 = await db.findOne({ id: g.p2id }); if (!db2) db2 = await db.create({ id: g.p2id, coins: 0, status_playing: "no" });
    db1.coins = parseInt(db1.coins) + g.betAmt; db1.status_playing = "no"; await db1.save();
    db2.coins = parseInt(db2.coins) + g.betAmt; db2.status_playing = "no"; await db2.save();
    resultLine = `> 🤝 **تعادل تام!** تم إعادة الرصيد للاعبَين.`;
  } else {
    winnerId = p1.pct >= p2.pct ? g.p1id : g.p2id;
    loserId  = winnerId === g.p1id ? g.p2id : g.p1id;
    winItem  = winnerId === g.p1id ? p1 : p2;
    loseItem = winnerId === g.p1id ? p2 : p1;
    let wd = await db.findOne({ id: winnerId }); if (!wd) wd = await db.create({ id: winnerId, coins: 0, status_playing: "no" });
    let ld = await db.findOne({ id: loserId });  if (!ld)  ld  = await db.create({ id: loserId, coins: 0, status_playing: "no" });
    wd.coins = parseInt(wd.coins) + prize; wd.status_playing = "no"; await wd.save();
    ld.status_playing = "no"; await ld.save();
    resultLine =
      `> 🏆 **الفائز:** <@${winnerId}> — ${winItem.emoji} **${winItem.name}** (\`${winItem.pct}%\`)\n` +
      `> 💀 **الخاسر:** <@${loserId}> — ${loseItem.emoji} **${loseItem.name}** (\`${loseItem.pct}%\`)`;
  }

  const resultEmbed = new Discord.MessageEmbed()
    .setColor(winnerId ? "GOLD" : "GREY")
    .setTitle("📦 معركة الصناديق — النتيجة!")
    .setDescription(
      `> ━━━━━━━━━━━━━━━━━━━━\n` +
      `> 📦 <@${g.p1id}>: ${p1.emoji} **${p1.name}** — \`${p1.pct}%\` (${CB_TIER_COLORS[p1.tier]} ${p1.tier})\n` +
      `> 📦 <@${g.p2id}>: ${p2.emoji} **${p2.name}** — \`${p2.pct}%\` (${CB_TIER_COLORS[p2.tier]} ${p2.tier})\n` +
      `> ━━━━━━━━━━━━━━━━━━━━\n` +
      `${resultLine}\n` +
      `> ━━━━━━━━━━━━━━━━━━━━\n` +
      `> 💵 **البوت:** \`${pot.toLocaleString("en-US")}\`\n` +
      (winnerId ? `> 🏆 **جائزة الفائز:** \`${prize.toLocaleString("en-US")}\` (بعد الضريبة)` : "")
    )
    .setFooter({ text: "معركة الصناديق • Diamond Casino" })
    .setTimestamp();

  if (msg) await msg.edit({ content: `> || <@${g.p1id}> | <@${g.p2id}> ||`, embeds: [resultEmbed], components: [] }).catch(() => {});
  await finalizePFGameSessionByChannel(g.channelId, `casebattle winner=${winnerId || "draw"} pot=${pot}`).catch(() => {});
});

