async function mafiaGetOrCreate(userId) {
  let mp = await mafiaPlayer.findOne({ id: userId });
  if (!mp) mp = await mafiaPlayer.create({ id: userId });
  return mp;
}

async function mafiaOnWin(userId, earnedAmount) {
  try {
    const mp = await mafiaGetOrCreate(userId);
    mp.wins++;
    mp.challenges++;
    mp.totalEarned = (mp.totalEarned || 0) + earnedAmount;
    await mp.save();
    if (mp.famiglia_id) {
      const fam = await mafiaFamiglia.findOne({ name: mp.famiglia_id });
      if (fam) { fam.vault += Math.floor(earnedAmount * 0.01); await fam.save(); }
    }
  } catch (e) { console.error("[mafiaOnWin]", e); }
}

async function mafiaOnLoss(userId, lostAmount) {
  try {
    const mp = await mafiaGetOrCreate(userId);
    mp.losses++;
    mp.challenges++;
    await mp.save();
    const contract = hitContractsMap.get(userId);
    if (contract && contract.expires > Date.now()) {
      const payout = Math.floor(lostAmount * contract.pct);
      let cdb = await db.findOne({ id: contract.by });
      if (!cdb) cdb = await db.create({ id: contract.by, coins: 0, status_playing: "no" });
      cdb.coins = parseInt(cdb.coins) + payout;
      await cdb.save();
      hitContractsMap.delete(userId);
      const contractor = await client.users.fetch(contract.by).catch(() => null);
      if (contractor) contractor.send({ content: `> 🎯 **عقد الإزالة نُفّذ!** الهدف <@${userId}> خسر، تحصل على **\`${payout.toLocaleString("en-US")}\`** عملة!` }).catch(() => {});
    }
  } catch (e) { console.error("[mafiaOnLoss]", e); }
}

async function mafiaOnDraw(userId) {
  try {
    const mp = await mafiaGetOrCreate(userId);
    mp.draws++;
    mp.challenges++;
    await mp.save();
  } catch (e) { console.error("[mafiaOnDraw]", e); }
}


const hitContractsMap = new Map(); // targetId → { by, paidAmount, pct, expires }
const sabotageMap     = new Map(); // targetId → { by, paidAmount, expires }
const exileVotesMap   = new Map(); // targetId → Set<DonId>

// ── Rank ladder ──────────────────────────────────────────────────────
const MAFIA_RANKS = [
  { name: "Street Dealer",    ar: "موزع شوارع",     emoji: "🚲", min: 0          },
  { name: "Lab Assistant",    ar: "مساعد مختبر",     emoji: "🧪", min: 1_000_000    },
  { name: "Cook",             ar: "طباخ كيميائي",    emoji: "⚗️", min: 10_000_000    },
  { name: "Distributor",      ar: "موزع معتمد",     emoji: "🚚", min: 20_000_000  },
  { name: "Cartel Enforcer",  ar: "منفذ الكارتيل",   emoji: "🪓", min: 40_000_000 },
  { name: "Heisenberg",       ar: "هايزنبيرغ",      emoji: "🎩", min: 50_000_000 },
];

function getMafiaRank(totalEarned) {
  for (let i = MAFIA_RANKS.length - 1; i >= 0; i--)
    if (totalEarned >= MAFIA_RANKS[i].min) return MAFIA_RANKS[i];
  return MAFIA_RANKS[0];
}
function getMafiaLevel(totalEarned)  { return Math.min(100, Math.floor(totalEarned / 100_000)); }
function getMafiaXPProgress(totalEarned) {
  const rank = getMafiaRank(totalEarned);
  const idx  = MAFIA_RANKS.indexOf(rank);
  const next = MAFIA_RANKS[idx + 1];
  if (!next) return { pct: 1, current: totalEarned, needed: rank.min };
  const cur = totalEarned - rank.min;
  const ned = next.min - rank.min;
  return { pct: Math.min(1, cur / ned), current: cur, needed: ned };
}


// ================================================================

// ── Chess / Penalty payout callback ──────────────────────────────────
async function pvpPayoutFn({ winnerId, loserId, betAmount, player1, player2 }) {
  try {
    const bet = parseInt(betAmount) || 0;
    if (bet <= 0) {
      if (player1) { const u = await db.findOne({ id: player1 }).catch(()=>null); if(u){ u.status_playing="no"; await u.save().catch(()=>{}); } }
      if (player2) { const u = await db.findOne({ id: player2 }).catch(()=>null); if(u){ u.status_playing="no"; await u.save().catch(()=>{}); } }
      return;
    }
    if (winnerId && loserId) {
      const tax = await calcTax(winnerId, bet);
      const total = bet - tax;
      const winnerDoc = await db.findOne({ id: winnerId }).catch(()=>null);
      if (winnerDoc) {
        winnerDoc.coins = parseInt(winnerDoc.coins || 0) + total;
        winnerDoc.status_playing = "no";
        await winnerDoc.save().catch(()=>{});
      }
      const loserDoc = await db.findOne({ id: loserId }).catch(()=>null);
      if (loserDoc) {
        loserDoc.coins = parseInt(loserDoc.coins || 0) - bet;
        loserDoc.cashback = (parseInt(loserDoc.cashback) || 0) + Math.floor(bet * 0.02);
        loserDoc.status_playing = "no";
        await loserDoc.save().catch(()=>{});
      }
      await mafiaOnWin(winnerId, bet).catch(() => {});
      await mafiaOnLoss(loserId, bet).catch(() => {});
    } else {
      if (player1) { const u = await db.findOne({ id: player1 }).catch(()=>null); if(u){ u.status_playing="no"; await u.save().catch(()=>{}); } }
      if (player2) { const u = await db.findOne({ id: player2 }).catch(()=>null); if(u){ u.status_playing="no"; await u.save().catch(()=>{}); } }
      if (player1) await mafiaOnDraw(player1).catch(() => {});
      if (player2) await mafiaOnDraw(player2).catch(() => {});
    }
    if (player1) await game.findOneAndDelete({ id: player1 }).catch(()=>{});
    if (player2) await game.findOneAndDelete({ id: player2 }).catch(()=>{});
  } catch(e) { console.error("[pvpPayoutFn]", e); }
}

