const RESET_DB_MODELS = [
  db, game, nrd, nrdusr, takribi, tkusr, mmgame, sosGame,
  minesDuelGame, rrouletteGame, pokerGame, matchBet, tqsShorout,
  ChessGame, PenaltyGame, ParkourGame,
  WatchRoom, WatchLog, AdminLog,
  dailyMission, inventory,
];

client.on("messageCreate", async (message) => {
  if (message.author.bot || !message.guild) return;
  const args = message.content.trim().split(/\s+/);
  if ((args[0] || "").toLowerCase() !== "!resetdb") return;
  const isOwner = owners.includes(message.author.id);
  const hasPerm = permStore.canUseCommand(message.author.id, "resetdb");
  if (!isOwner && !hasPerm) return message.reply("> ❌ ليس لديك صلاحية لاستخدام هذا الأمر.\nطلب من الإدارة: `!giveperm resetdb @user`");
  if ((args[1] || "").toUpperCase() !== "CONFIRM") {
    return message.reply("> ⚠️ للتأكيد استخدد: `!resetdb CONFIRM`");
  }

  try {
    for (const model of RESET_DB_MODELS) {
      await model.deleteMany({});
    }
    await message.reply("> ✅ Database reset completed.");
  } catch (error) {
    console.error("Error while resetting database:", error);
    await message.reply("> ❌ فشل في إعادة تصفير قاعدة البيانات.");
  }
});


function buildTqsEmbed(data, p1User, p2User) {
  const p1Line = data.p1Numbers && data.p1Numbers.length
    ? `${data.p1Numbers.join(" + ")} = **${data.p1Total}**`
    : "لم يلعب بعد";
  const p2Line = data.p2Numbers && data.p2Numbers.length
    ? `${data.p2Numbers.join(" + ")} = **${data.p2Total}**`
    : "لم يلعب بعد";

  let phaseLabel = "";
  if (data.phase === "p1")
    phaseLabel = `> 🎯 دور **${p1User ? p1User.tag : "؟"}** — اختر نطاق`;
  else if (data.phase === "p2")
    phaseLabel = `> 🎯 دور **${p2User ? p2User.tag : "؟"}** — اختر نطاق`;
  else if (data.phase === "control")
    phaseLabel = `> 🎮 **${p1User ? p1User.tag : "؟"}** يتحكم في دور **${p2User ? p2User.tag : "؟"}** — اختر نطاقاً لصديقك`;

  return new Discord.MessageEmbed()
    .setColor("#032943")
    .setTitle("📊 تقريبي شروط")
    .setDescription(
      `> **الحد الأقصى:** \`${data.maxNum}\`\n` +
      `> **نطاق A:** \`${data.rangeA1} - ${data.rangeA2}\`  |  **نطاق B:** \`${data.rangeB1} - ${data.rangeB2}\`\n` +
      `━━━━━━━━━━━━━━━━━━━━\n${phaseLabel}`
    )
    .addFields(
      {
        name: `👤 ${p1User ? p1User.tag : "اللاعب الأول"}`,
        value: `> ${p1Line}${data.p1Exceeded ? " ❌ تجاوز!" : ""}`,
        inline: true,
      },
      {
        name: `👤 ${p2User ? p2User.tag : "اللاعب الثاني"}`,
        value: `> ${p2Line}${data.p2Total > data.maxNum ? " ❌ تجاوز!" : ""}`,
        inline: true,
      },
    );
}

function buildTqsRows(data, msgID) {
  const isControl = data.phase === "control";
  // A button is red+disabled if its minimum alone would push p2 over the max
  const disableA = isControl && (data.rangeA1 + data.p2Total > data.maxNum);
  const disableB = isControl && (data.rangeB1 + data.p2Total > data.maxNum);

  const btnA = new MessageButton()
    .setCustomId(`arkam1tqs_${msgID}`)
    .setLabel(`${data.rangeA1} - ${data.rangeA2}`)
    .setStyle(disableA ? "DANGER" : "PRIMARY")
    .setDisabled(disableA);

  const btnB = new MessageButton()
    .setCustomId(`arkam2tqs_${msgID}`)
    .setLabel(`${data.rangeB1} - ${data.rangeB2}`)
    .setStyle(disableB ? "DANGER" : "PRIMARY")
    .setDisabled(disableB);

  const finishLabel = isControl ? "إنهاء دور صديقي 🏳️" : "إنهاء دوري ✅";
  const btnFinish = new MessageButton()
    .setCustomId(`finishtqs_${msgID}`)
    .setLabel(finishLabel)
    .setStyle(isControl ? "SECONDARY" : "SUCCESS");

  // Layout: [low range] [finish in middle] [high range] — same as bot version
  return [new MessageActionRow().setComponents(btnA, btnFinish, btnB)];
}

async function tqsFinalize(gdata, tqsData, winnerID, loserID, isDraw, reason) {
  const msgID = tqsData.msgID;
  const channelID = tqsData.channelID;
  const coins = parseInt(gdata.coins);
  const p1User = client.users.cache.get(tqsData.player1);
  const p2User = client.users.cache.get(tqsData.player2);

  const p1Line = tqsData.p1Numbers && tqsData.p1Numbers.length
    ? `${tqsData.p1Numbers.join(" + ")} = **${tqsData.p1Total}**`
    : "`0`";
  const p2Line = tqsData.p2Numbers && tqsData.p2Numbers.length
    ? `${tqsData.p2Numbers.join(" + ")} = **${tqsData.p2Total}**`
    : "`0`";

  const finalEmbed = new Discord.MessageEmbed()
    .setColor(isDraw ? "#FEE75C" : "#032943")
    .setTitle(`📊 تقريبي شروط — ${isDraw ? "تعادل! 🤝" : "انتهت اللعبة!"}`)
    .setDescription(`> **الحد الأقصى:** \`${tqsData.maxNum}\`\n> ${reason}`)
    .addFields(
      { name: `👤 ${p1User ? p1User.tag : "اللاعب الأول"}`, value: `> ${p1Line}`, inline: true },
      { name: `👤 ${p2User ? p2User.tag : "اللاعب الثاني"}`, value: `> ${p2Line}`, inline: true },
    );

  const resultContent = isDraw
    ? `> || <@${tqsData.player1}> | <@${tqsData.player2}> || تعادل! لا يُسحب مبلغ.\nاللعبة: **تقريبي شروط**, المبلغ: **${coins.toLocaleString("en-US")}**`
    : `> <@${winnerID}> فاز! 🏆 || <@${tqsData.player1}> | <@${tqsData.player2}> ||\nاللعبة: **تقريبي شروط**, المبلغ: **${coins.toLocaleString("en-US")}**`;

  const ch = client.channels.cache.get(channelID);
  if (ch) {
    const msg = await ch.messages.fetch(msgID).catch(() => null);
    if (msg) await msg.edit({ embeds: [finalEmbed], content: resultContent, components: [] }).catch(() => {});
  }

  let d1 = await db.findOne({ id: tqsData.player1 });
  if (!d1) d1 = await db.create({ id: tqsData.player1, coins: 0, status_playing: "no" });
  let d2 = await db.findOne({ id: tqsData.player2 });
  if (!d2) d2 = await db.create({ id: tqsData.player2, coins: 0, status_playing: "no" });

  if (!isDraw && winnerID && loserID) {
    const tax = await calcTax(winnerID, coins);
    const total = coins - tax;
    if (winnerID === tqsData.player1) {
      d1.coins = parseInt(d1.coins) + total;
      d2.coins = parseInt(d2.coins) - coins;
    } else {
      d2.coins = parseInt(d2.coins) + total;
      d1.coins = parseInt(d1.coins) - coins;
    }
    // Track wins/losses for !profilo
    await mafiaOnWin(winnerID, coins).catch(() => {});
    await mafiaOnLoss(loserID, coins).catch(() => {});
  } else if (isDraw) {
    await mafiaOnDraw(tqsData.player1).catch(() => {});
    await mafiaOnDraw(tqsData.player2).catch(() => {});
  }

  d1.status_playing = "no";
  d2.status_playing = "no";
  await d1.save();
  await d2.save();
  await tqsShorout.findOneAndDelete({ msgID });
  await game.findOneAndDelete({ id: tqsData.player1, with: tqsData.player2, msgID });
  await finalizePFGameSessionByChannel(channelID, `tqs-shorout ${isDraw ? "DRAW" : `winner=${winnerID}`} max=${tqsData.maxNum}`);
}

