// ════════════════════════════════════════════════════════════
//  !watch — Watch Party Command (up to 5 users)
// ════════════════════════════════════════════════════════════
client.on("messageCreate", async (message) => {
  if (message.author.bot || !message.guild) return;
  const args = message.content.trim().split(/\s+/);
  if ((args[0] || "").toLowerCase() !== "!watch") return;

  const allMentioned = [...message.mentions.users.values()].filter(u => !u.bot && u.id !== message.author.id).slice(0, 4);

  if (!allMentioned.length) {
    return message.reply({
      embeds: [
        new MessageEmbed()
          .setColor("#032943")
          .setTitle("🎬 !watch — غرفة المشاهدة")
          .setDescription([
            "> **الاستخدام:** `!watch @صديق1 @صديق2 ... اسم الفيلم`",
            "> **مثال:** `!watch @أحمد @سارة Breaking Bad`",
            "> **الحد الأقصى:** 5 مشاركين (أنت + 4 أصدقاء)",
            "> ",
            "> 🎬 يوتيوب / IMDB / أي رابط فيديو",
            "> 💰 التكلفة: 15 كوين كل 30 ثانية لكل مشارك",
          ].join("\n")),
      ],
    });
  }

  const titleWords = args.slice(1).filter(a => !a.match(/^<@!?\d+>$/));
  const title = titleWords.join(" ").trim();
  if (!title)
    return message.reply({ content: "> ❌ يرجى تحديد اسم الفيلم أو المسلسل!\n> **مثال:** `!watch @صديق Breaking Bad`" });

  const allIds = [message.author.id, ...allMentioned.map(u => u.id)];
  const existingWatch = await WatchRoom.findOne({ status:'active', $or:[{ownerId:{$in:allIds}},{'participants.userId':{$in:allIds}}] }).catch(()=>null);
  if (existingWatch) return message.reply({ content: "> ❌ أحد المشاركين في غرفة مشاهدة نشطة بالفعل!" });

  const { v4: uuidv4 } = require("uuid");
  const roomId = uuidv4().replace(/-/g,"").slice(0,16);
  const watchUrl = `${CHESS_BASE_URL}/watch/${roomId}`;

  await WatchRoom.create({
    roomId,
    ownerId: message.author.id,
    ownerUsername: message.author.username,
    ownerAvatar: message.author.avatar || "",
    invitedIds: allMentioned.map(u => u.id),
    participants: [{ userId: message.author.id, username: message.author.username, avatar: message.author.avatar||"", joinedAt: Date.now() }],
    title,
    status: "active",
    startedAt: Date.now(),
    msgID: "",
    channelId: message.channel.id,
  }).catch(() => null);

  const invitedMentions = allMentioned.map(u => `<@${u.id}>`).join("، ");
  const watchInviteEmbed = new MessageEmbed()
    .setColor("#032943")
    .setTitle("🎬 دعوة غرفة مشاهدة مشتركة")
    .setDescription([
      `> 🎬 **الفيلم / المسلسل:** \`${title}\``,
      `> 👑 **المُضيف:** ${message.author}`,
      `> 🎟️ **المدعوون:** ${invitedMentions}`,
      `> `,
      `> ⏳ في انتظار انضمام الأصدقاء...`,
      `> 🔗 **[ادخل الغرفة الآن](${watchUrl})**`,
      `> \`${watchUrl}\``,
    ].join("\n"))
    .addFields({
      name: "🍿 مميزات الغرفة",
      value: [
        "> 🎬 يوتيوب + أفلام IMDB عبر streamimdb.ru",
        "> 💬 دردشة ومزاجيات متزامنة",
        "> 👑 المُضيف يتحكم في التشغيل",
        "> 💰 15 كوين كل 30 ثانية لكل مشارك",
      ].join("\n"),
    })
    .setFooter({ text: `Diamond Casino · Watch Party · ${roomId}` })
    .setTimestamp();

  const watchRow = new MessageActionRow().addComponents(
    new MessageButton()
      .setCustomId(`watch_join_${roomId}`)
      .setLabel("✅ انضم للغرفة")
      .setStyle("SUCCESS"),
  );

  const sentMsg = await message.reply({
    embeds: [watchInviteEmbed],
    components: [watchRow],
    allowedMentions: { repliedUser: false },
  });

  await WatchRoom.findOneAndUpdate({ roomId }, { msgID: sentMsg.id }).catch(()=>{});
});

// ── Watch Party: انضمام ──────────────────────────────────────
client.on("interactionCreate", async (interaction) => {
  if (!interaction.isButton()) return;
  if (!interaction.customId.startsWith("watch_join_")) return;

  const roomId = interaction.customId.slice("watch_join_".length);
  const wr = await WatchRoom.findOne({ roomId }).catch(()=>null);
  if (!wr) return interaction.reply({ content: "> ❌ انتهت صلاحية الدعوة أو انتهت الجلسة!", ephemeral: true });
  if (wr.status === "ended") return interaction.reply({ content: "> ❌ انتهت هذه الجلسة.", ephemeral: true });

  const uid = interaction.user.id;
  if (!(wr.invitedIds||[]).includes(uid))
    return interaction.reply({ content: "> ❌ هذه الدعوة ليست لك!", ephemeral: true });

  const alreadyIn = (wr.participants||[]).some(p => p.userId === uid);
  if (!alreadyIn) {
    if ((wr.participants||[]).length >= 5)
      return interaction.reply({ content: "> ❌ الغرفة ممتلئة (الحد الأقصى 5 مشاركين)!", ephemeral: true });
    wr.participants.push({ userId: uid, username: interaction.user.username, avatar: interaction.user.avatar||"", joinedAt: Date.now() });
    wr.markModified('participants');
    await wr.save();
    gameEvents.emit('watch_update', roomId, { type:'joined', userId: uid, username: interaction.user.username, avatar: interaction.user.avatar||"" });
  }

  const watchUrl = `${CHESS_BASE_URL}/watch/${roomId}`;
  await interaction.reply({ content: `> ✅ انضممت إلى غرفة المشاهدة! ادخل هنا: ${watchUrl}`, ephemeral: true });
});

// ═══════════════════════════════════════════════════════════════════
//   MULTI-BANK DEPOSIT SYSTEM — نظام الشحن المتعدد البنوك
// ═══════════════════════════════════════════════════════════════════

const BANKS_PATH        = path.join(__dirname, "banks.json");
const PENDING_DEP_PATH  = path.join(__dirname, "pendingDeposits.json");

function mbReadBanks() {
  try { return JSON.parse(fs.readFileSync(BANKS_PATH, "utf8")); }
  catch { return []; }
}
function mbWriteBanks(data) {
  fs.writeFileSync(BANKS_PATH, JSON.stringify(data, null, 2));
}
function mbReadPending() {
  try { return JSON.parse(fs.readFileSync(PENDING_DEP_PATH, "utf8")); }
  catch { return {}; }
}
function mbWritePending(data) {
  fs.writeFileSync(PENDING_DEP_PATH, JSON.stringify(data, null, 2));
}

// Clean expired pending deposits every 10 minutes
setInterval(() => {
  try {
    const pending = mbReadPending();
    const now = Date.now();
    let changed = false;
    for (const uid of Object.keys(pending)) {
      if ((pending[uid].expires || 0) < now) { delete pending[uid]; changed = true; }
    }
    if (changed) mbWritePending(pending);
  } catch {}
}, 10 * 60 * 1000);

// Credit a user after confirmed deposit
async function mbCreditUser(userId, amount) {
  let ud = await db.findOne({ id: userId }).catch(() => null);
  if (!ud) ud = await db.create({ id: userId, coins: 0, status_playing: "no" }).catch(() => null);
  if (!ud) return 0;
  ud.coins    = parseInt(ud.coins    || 0) + parseInt(amount);
  ud.deposits = parseInt(ud.deposits || 0) + parseInt(amount);
  await ud.save().catch(() => {});
  return ud.coins;
}

// Map of active bank watcher clients { bankId: Discord.Client }
const mbBankClients = {};



async function mbInitWatchers() {
  const banks = mbReadBanks();
  const PROBOT = SERVER_SETTINGS.users.probotBotId;

  for (const bank of banks) {
    if (!bank.token) continue;

    // Destroy old client if exists
    if (mbBankClients[bank.id]) {
      try { mbBankClients[bank.id].destroy(); } catch {}
      delete mbBankClients[bank.id];
    }
    if (!bank.active) continue;

    const watcher = new Discord.Client({
      intents: [
        Discord.Intents.FLAGS.GUILDS,
        Discord.Intents.FLAGS.GUILD_MESSAGES,
      ],
    });

    watcher.once("ready", () => {
      console.log(`🏦 [BankWatcher] "${bank.name}" → جاهز كـ ${watcher.user.tag}`);
    });

    watcher.on("error", err => {
      console.error(`🏦 [BankWatcher] خطأ في "${bank.name}": ${err.message}`);
    });

    watcher.on("messageCreate", async (msg) => {
      try {
        if (msg.author.id !== PROBOT) return;
        if (bank.channelId && msg.channel.id !== bank.channelId) return;

        // ProBot transfer format:
        // **:moneybag: | Username, has transferred $5,000 ⌬ (PROBOT Credits) to ReceiverName**
        const match = msg.content.match(
          /\*\*:moneybag:.*?\|\s*(.+?),\s*has transferred\s+\$?([\d,]+)/i
        );
        if (!match) return;

        const senderUsername = match[1].trim();
        const amount         = parseInt(match[2].replace(/,/g, ""), 10);
        if (!amount || amount < 1) return;

        // Find a matching pending deposit for this bank
        const pending = mbReadPending();
        const entry   = Object.values(pending).find(p =>
          p.bankId === bank.id &&
          p.username.toLowerCase() === senderUsername.toLowerCase() &&
          Date.now() < (p.expires || 0)
        );

        if (!entry) {
          console.log(`🏦 [BankWatcher] "${bank.name}" — تحويل من ${senderUsername} (${amount}) — لا يوجد طلب معلق`);
          return;
        }

        // Remove from pending
        delete pending[entry.userId];
        mbWritePending(pending);

        // Credit user
        const newBalance = await mbCreditUser(entry.userId, amount);

        // Apply bonus (if active)
        await applyBonus(entry.userId, amount, null).catch(() => {});

        // DM success to user
        try {
          const casinoUser = await client.users.fetch(entry.userId);
          const dmEmbed = new Discord.MessageEmbed()
            .setColor("#00d26a")
            .setTitle("✅ تم الشحن بنجاح!")
            .setDescription(
              `> 🏦 **البنك:** \`${bank.name}\`\n` +
              `> 💰 **المبلغ المُشحون:** \`${amount.toLocaleString("en-US")}\`\n` +
              `> 💎 **رصيدك الجديد:** \`${newBalance.toLocaleString("en-US")}\``
            )
            .setFooter({ text: "Diamond Casino — نظام الشحن" })
            .setTimestamp();
          await casinoUser.send({ embeds: [dmEmbed] }).catch(() => {});
        } catch {}

        // Log to recharge channel
        try {
          const logCh = client.channels.cache.get(SERVER_SETTINGS.channels.rechargeLogId);
          if (logCh) {
            const logEmbed = new Discord.MessageEmbed()
              .setColor("#032943")
              .setTitle("💰 شحن ناجح — متعدد البنوك")
              .addFields(
                { name: "👤 المستخدم", value: `> <@${entry.userId}> (\`${entry.username}\`)`, inline: true },
                { name: "🏦 البنك",     value: `> \`${bank.name}\``,                           inline: true },
                { name: "💵 المبلغ",   value: `> \`${amount.toLocaleString("en-US")}\``,       inline: true },
                { name: "💎 الرصيد الجديد", value: `> \`${newBalance.toLocaleString("en-US")}\``, inline: true },
                { name: "🕐 الوقت",    value: `> <t:${Math.floor(Date.now() / 1000)}:F>`,      inline: true },
              )
              .setTimestamp();
            logCh.send({ embeds: [logEmbed] }).catch(() => {});
          }
        } catch {}

        console.log(`✅ [BankWatcher] شحن ناجح — ${entry.username} — ${amount} — بنك: ${bank.name}`);
      } catch (e) {
        console.error(`🏦 [BankWatcher] خطأ في معالجة رسالة:`, e.message);
      }
    });

    try {
      await watcher.login(bank.token);
      mbBankClients[bank.id] = watcher;
    } catch (err) {
      console.error(`🏦 [BankWatcher] فشل تسجيل الدخول للبنك "${bank.name}": ${err.message}`);
    }
  }
}


