  const spyCount          = parseInt(userData?.spyCount)          || 0;
  const freezeCount       = parseInt(userData?.freezeCount)       || 0;
  const blockCount        = parseInt(userData?.blockCount)        || 0;
  const customTitleCount  = parseInt(userData?.customTitleCount)  || 0;
