// ─── معالج اختيار من المتجر (Select Menu) ─────────────────────────
client.on("interactionCreate", async (interaction) => {
  if (!interaction.isSelectMenu()) return;
  if (!interaction.customId.startsWith("shop_select_")) return;

  await interaction.deferReply({ ephemeral: true });

  const userId = interaction.customId.split("_")[2];

  // Verify user
  if (interaction.user.id !== userId) {
    return interaction.editReply({ content: "> ❌ هذا المتجر ليس لك!" });
  }

  const selection = interaction.values[0];

  // ── Helper: buy any shop item ──
  async function buyShopItem(itemKey, price, label, emoji, countField, howToUse) {
    let checkStatus = await db.findOne({ id: interaction.user.id }).catch(() => null);
    if (checkStatus && checkStatus.status_playing === "yes")
      return interaction.editReply({ content: "> ❌ لا يمكن الشراء أثناء اللعب!" });

    let userData = await db.findOne({ id: interaction.user.id }).catch(() => null);
    if (!userData) userData = await db.create({ id: interaction.user.id, coins: 0, status_playing: "no" }).catch(() => null);
    if (!userData) return interaction.editReply({ content: "> ❌ حدث خطأ في الوصول إلى قاعدة البيانات!" });

    const userCoins = parseInt(userData.coins) || 0;
    if (userCoins < price) {
      const needed = (price - userCoins).toLocaleString();
      return interaction.editReply({ content: `> ❌ لا تملك عملات كافية! تحتاج \`${needed}\` عملة إضافية.\n> 💰 رصيدك الحالي: \`${userCoins.toLocaleString()}\` عملة` });
    }

    userData.coins = userCoins - price;
    userData[countField] = (parseInt(userData[countField]) || 0) + 1;
    await userData.save();

    userData = await db.findOne({ id: interaction.user.id }).catch(() => null);
    const finalCount = parseInt(userData?.[countField]) || 0;
    const finalCoins = parseInt(userData?.coins) || 0;
    await interaction.editReply({
      content: `> ✅ تم شراء **${emoji} ${label}** بنجاح!\n> 💰 تم خصم \`${price.toLocaleString()}\` عملة\n> 📍 ${howToUse}\n\n**الرصيد الجديد:** \`${finalCoins.toLocaleString()}\` عملة\n**الملكية:** \`${finalCount}\` نسخة`
    });
  }

  if (selection === 'buy_backnumber')
    return buyShopItem('backnumber', 25000000, 'BackNumber', '🔙', 'backNumberCount', 'اكتب **backnumber** في الدردشة أثناء لعبة تقريبي لاستخدامها!');

  if (selection === 'buy_luckyreduce')
    return buyShopItem('luckyreduce', 50000000, 'LuckyReduce', '🍀', 'luckyReduceCount', 'اكتب **luckyreduce** في الدردشة بعد تجاوز الحد لاستخدامها!');

  if (selection === 'buy_replay')
    return buyShopItem('replay', 75000000, 'Replay', '🔄', 'replayCount', 'اكتب **replay** في الدردشة أثناء دورك لإعادة التشغيل!');

  if (selection === 'buy_changemax')
    return buyShopItem('changemax', 10000000, 'ChangeMax', '🔀', 'changeMaxCount', 'اكتب **changemax** في الدردشة أثناء دورك لطلب تغيير الرقم الأقصى!');

  if (selection === 'buy_spy')
    return buyShopItem('spy', 5000000, 'Spy', '👁️', 'spyCount', 'اكتب **spy** في الدردشة أثناء دورك لكشف مجموع خصمك!');

  if (selection === 'buy_freeze')
    return buyShopItem('freeze', 40000000, 'Freeze', '❄️', 'freezeCount', 'اكتب **freeze** في الدردشة أثناء دورك لتجميد اختيار خصمك القادم!');

  if (selection === 'buy_block')
    return buyShopItem('block', 30000000, 'Block', '🚫', 'blockCount', 'اكتب **block** في الدردشة أثناء دورك لمنع خصمك من أي أداة في هذه اللعبة!');

  if (selection === 'buy_customtitle')
    return buyShopItem('customtitle', 20000000, 'Custom Title', '🏅', 'customTitleCount', 'اكتب **!settitle <النص>** لتعيين لقبك المخصص الذي يظهر في بطاقتك!');

  if (selection === 'buy_profilecolor')
    return buyShopItem('profilecolor', 15000000, 'Profile Color', '🌈', 'profileColorCount', 'اكتب **!setcolor #hex** لتعيين لون بطاقتك الشخصية!');

  if (selection === 'buy_custombackground') {
    let userData = await db.findOne({ id: interaction.user.id }).catch(() => null);
    if (userData && userData.status_playing === "yes")
      return interaction.editReply({ content: "> ❌ لا يمكن الشراء أثناء اللعب!" });

    if (!userData) userData = await db.create({ id: interaction.user.id, coins: 0, status_playing: "no" }).catch(() => null);
    if (!userData) return interaction.editReply({ content: "> ❌ حدث خطأ في الوصول إلى قاعدة البيانات!" });

    const userCoins = parseInt(userData.coins) || 0;
    const price = 25000000;
    if (userCoins < price) {
      const needed = (price - userCoins).toLocaleString();
      return interaction.editReply({ content: `> ❌ لا تملك عملات كافية! تحتاج \`${needed}\` عملة إضافية.` });
    }

    userData.coins = userCoins - price;
    userData.customBackgroundStatus = "active";
    await userData.save();

    await interaction.editReply({
      content: `> ✅ تم خصص \`${price.toLocaleString()}\` عملة\n> 🖼️ الآن يمكنك استخدام الأمر \`!setbackground <رابط الصورة>\` لتعيين خلفيتك!\n> 📐 الدقة: 1920×1080 HD | الصيغ المدعومة: PNG, JPG, GIF (مع الحركة)`
    });
  }
});

