// ================================================================\
// !control — Advanced Process Management for Owner
// ================================================================


// ================================================================
// !control — Advanced Process Management for Owner (No exec)
// ================================================================

const fs_control = require('fs');
const path_control = require('path');

// Store managed processes
const managedProcesses = new Map(); // name -> { process, pid, startTime, scriptPath }

// Scripts to monitor (add any other scripts you run)
const SCRIPTS_TO_MANAGE = [
    { name: 'main', script: 'index.js', autoRestart: true, isMain: true },
    { name: 'selfbot', script: 'self.js', autoRestart: true },
    { name: 'website', script: 'website.js', autoRestart: true },
    { name: 'adminBot', script: 'adminBot.js', autoRestart: true },
];

// Track active control messages
const activeControlMessages = new Map();

// Add current main process to managed list
managedProcesses.set('main', {
    pid: process.pid,
    startTime: Date.now(),
    scriptPath: 'index.js',
    status: 'running',
    isMain: true
});

// Function to start a script
async function startScript(scriptName, interaction = null) {
    const scriptConfig = SCRIPTS_TO_MANAGE.find(s => s.name === scriptName);
    if (!scriptConfig) {
        return { success: false, message: `❌ Script "${scriptName}" not found in management list` };
    }

    // Don't start main from within itself
    if (scriptConfig.isMain) {
        return { success: false, message: `⚠️ Cannot start main bot from within itself! Use the Restart button.` };
    }

    if (managedProcesses.has(scriptName) && managedProcesses.get(scriptName).process) {
        const existing = managedProcesses.get(scriptName);
        // Check if process is still alive
        if (existing.process && !existing.process.killed) {
            return { success: false, message: `⚠️ ${scriptName} is already running! (PID: ${existing.pid})` };
        }
    }

    try {
        const scriptPath = path_control.join(__dirname, scriptConfig.script);
        if (!fs_control.existsSync(scriptPath)) {
            return { success: false, message: `❌ Script file not found: ${scriptConfig.script}` };
        }

        const proc = spawn('node', [scriptPath], {
            stdio: 'inherit',
            detached: false,
            env: { ...process.env }
        });

        const processInfo = {
            process: proc,
            pid: proc.pid,
            startTime: Date.now(),
            scriptPath: scriptConfig.script,
            status: 'running'
        };

        managedProcesses.set(scriptName, processInfo);

        proc.on('close', (code) => {
            console.log(`[Control] ${scriptName} exited with code ${code}`);
            if (scriptConfig.autoRestart && code !== 0 && code !== null) {
                console.log(`[Control] Auto-restarting ${scriptName} in 3 seconds...`);
                setTimeout(() => startScript(scriptName), 3000);
            } else {
                managedProcesses.delete(scriptName);
            }
        });

        proc.on('error', (err) => {
            console.error(`[Control] Error starting ${scriptName}:`, err.message);
            managedProcesses.delete(scriptName);
        });

        return { success: true, message: `✅ Started ${scriptName} (PID: ${proc.pid})` };
    } catch (err) {
        return { success: false, message: `❌ Failed to start ${scriptName}: ${err.message}` };
    }
}

// Function to stop a script
async function stopScript(scriptName, force = false) {
    const managed = managedProcesses.get(scriptName);

    // Prevent stopping main bot
    if (scriptName === 'main') {
        return { success: false, message: "⚠️ Cannot stop main bot! Use 'Restart Main' button instead." };
    }

    if (!managed || !managed.process) {
        return { success: false, message: `❌ ${scriptName} is not running` };
    }

    try {
        if (force) {
            managed.process.kill('SIGKILL');
        } else {
            managed.process.kill('SIGTERM');
        }

        // Wait a bit to confirm termination
        await new Promise(resolve => setTimeout(resolve, 500));

        if (!managed.process.killed) {
            managed.process.kill('SIGKILL');
        }

        managedProcesses.delete(scriptName);
        return { success: true, message: `✅ Stopped ${scriptName}` };
    } catch (err) {
        return { success: false, message: `❌ Failed to stop ${scriptName}: ${err.message}` };
    }
}

// Function to restart main bot
// تعديل دالة restartMainBot
async function restartMainBot(interaction) {
    const embed = new Discord.MessageEmbed()
        .setColor("#e67e22")
        .setTitle("🔄 إعادة تشغيل البوت...")
        .setDescription("جاري إعادة تشغيل البوت عبر PM2...")
        .setTimestamp();

    if (interaction) {
        await interaction.followUp({ embeds: [embed] }).catch(() => {});
    }

    // استخدام PM2 لإعادة التشغيل
    const { exec } = require('child_process');
    exec('pm2 restart index.js', (error, stdout, stderr) => {
        if (error) {
            console.error(`خطأ في إعادة التشغيل: ${error}`);
            // إذا فشل PM2، جرب الخروج العادي
            setTimeout(() => process.exit(0), 1000);
        } else {
            console.log(`تم إعادة التشغيل: ${stdout}`);
        }
    });
}

// Format uptime
function formatUptime(ms) {
    const seconds = Math.floor(ms / 1000);
    const minutes = Math.floor(seconds / 60);
    const hours = Math.floor(minutes / 60);
    const days = Math.floor(hours / 24);

    if (days > 0) return `${days}d ${hours % 24}h`;
    if (hours > 0) return `${hours}h ${minutes % 60}m`;
    if (minutes > 0) return `${minutes}m ${seconds % 60}s`;
    return `${seconds}s`;
}

// Build control panel embed
function buildControlEmbed() {
    const statusLines = [];
    const uptimes = {};

    for (const script of SCRIPTS_TO_MANAGE) {
        const managed = managedProcesses.get(script.name);
        let status = 'stopped';
        let uptime = '—';

        if (script.name === 'main') {
            status = 'running';
            uptime = formatUptime(Date.now() - (managed?.startTime || process.uptime() * 1000));
        } else if (managed && managed.process && !managed.process.killed) {
            status = 'running';
            if (managed.startTime) {
                uptime = formatUptime(Date.now() - managed.startTime);
            }
        } else if (managed && managed.pid) {
            // Process might be dead but not cleaned
            managedProcesses.delete(script.name);
            status = 'stopped';
        }

        const emoji = status === 'running' ? '🟢' : '🔴';
        statusLines.push(`> ${emoji} **${script.name}** — \`${status}\` ${uptime !== '—' ? `(${uptime})` : ''}`);
        uptimes[script.name] = uptime;
    }

    const embed = new Discord.MessageEmbed()
        .setColor("#5865F2")
        .setTitle("🎮 Bot Control Panel — Process Manager")
        .setDescription("```yaml\n╔══════════════════════════════════════════╗\n║     Owner Only — Process Management      ║\n╚══════════════════════════════════════════╝\n```")
        .addFields(
            {
                name: "📊 Current Status",
                value: statusLines.join('\n') || "> No processes",
                inline: false
            },
            {
                name: "🎮 Main Process Info",
                value: `> 🆔 **PID:** \`${process.pid}\`\n> 💾 **Memory:** \`${(process.memoryUsage().heapUsed / 1024 / 1024).toFixed(2)} MB\`\n> ⏱️ **Uptime:** \`${formatUptime(process.uptime() * 1000)}\``,
                inline: true
            },
            {
                name: "📂 Working Directory",
                value: `> \`${__dirname}\``,
                inline: true
            }
        )
        .setFooter({ text: "Control Panel • Owner Only • Use buttons below" })
        .setTimestamp();

    return embed;
}

// Build control buttons
function buildControlButtons() {
    const buttons = [];

    // Start buttons (only for non-main scripts)
    const startButtons = SCRIPTS_TO_MANAGE.filter(s => !s.isMain).map(script => 
        new Discord.MessageButton()
            .setCustomId(`ctrl_start_${script.name}`)
            .setLabel(`▶️ Start ${script.name}`)
            .setStyle("SUCCESS")
    );

    if (startButtons.length) {
        // Split into rows of 5
        for (let i = 0; i < startButtons.length; i += 5) {
            buttons.push(new Discord.MessageActionRow().addComponents(startButtons.slice(i, i + 5)));
        }
    }

    // Stop buttons (only for non-main scripts)
    const stopButtons = SCRIPTS_TO_MANAGE.filter(s => !s.isMain).map(script => 
        new Discord.MessageButton()
            .setCustomId(`ctrl_stop_${script.name}`)
            .setLabel(`⏹️ Stop ${script.name}`)
            .setStyle("DANGER")
    );

    if (stopButtons.length) {
        for (let i = 0; i < stopButtons.length; i += 5) {
            buttons.push(new Discord.MessageActionRow().addComponents(stopButtons.slice(i, i + 5)));
        }
    }

    // Utility buttons row
    buttons.push(new Discord.MessageActionRow().addComponents(
        new Discord.MessageButton()
            .setCustomId("ctrl_restart_main")
            .setLabel("🔄 Restart Main Bot")
            .setStyle("PRIMARY"),
        new Discord.MessageButton()
            .setCustomId("ctrl_refresh")
            .setLabel("🔄 Refresh Status")
            .setStyle("SECONDARY"),
        new Discord.MessageButton()
            .setCustomId("ctrl_memory")
            .setLabel("📊 Memory Stats")
            .setStyle("SECONDARY")
    ));

    return buttons;
}

// Main command handler
client.on("messageCreate", async (message) => {
    if (message.author.bot || !message.guild) return;
    if (message.content.trim().toLowerCase() !== "!control") return;

    // Check if user is owner
    if (!owners.includes(message.author.id)) {
        return message.reply({ 
            content: "> ❌ **Access Denied — Owner Only!**\n> This command is restricted to the bot owner.",
            ephemeral: true 
        });
    }

    const embed = buildControlEmbed();
    const rows = buildControlButtons();

    const sentMsg = await message.reply({ 
        embeds: [embed], 
        components: rows,
        allowedMentions: { repliedUser: false }
    });

    activeControlMessages.set(sentMsg.id, { 
        userId: message.author.id, 
        channelId: message.channel.id,
        lastUpdate: Date.now()
    });

    // Auto-cleanup after 5 minutes
    setTimeout(() => {
        if (activeControlMessages.has(sentMsg.id)) {
            activeControlMessages.delete(sentMsg.id);
            sentMsg.edit({ components: [] }).catch(() => {});
        }
    }, 5 * 60 * 1000);
});

// Handle button interactions
client.on("interactionCreate", async (interaction) => {
    if (!interaction.isButton()) return;
    if (!interaction.customId.startsWith("ctrl_")) return;

    // Verify ownership
    if (!owners.includes(interaction.user.id)) {
        return interaction.reply({ 
            content: "> ❌ **Access Denied — Owner Only!**",
            ephemeral: true 
        });
    }

    await interaction.deferReply({ ephemeral: true });

    const action = interaction.customId;

    // Handle start commands
    if (action.startsWith("ctrl_start_")) {
        const scriptName = action.replace("ctrl_start_", "");
        const result = await startScript(scriptName, interaction);
        await interaction.editReply({ content: result.message });

        // Refresh the control panel
        setTimeout(async () => {
            const originalMsg = await interaction.channel.messages.fetch(interaction.message.id).catch(() => null);
            if (originalMsg) {
                const newEmbed = buildControlEmbed();
                await originalMsg.edit({ embeds: [newEmbed], components: buildControlButtons() }).catch(() => {});
            }
        }, 1000);
    }

    // Handle stop commands
    else if (action.startsWith("ctrl_stop_")) {
        const scriptName = action.replace("ctrl_stop_", "");
        const result = await stopScript(scriptName);
        await interaction.editReply({ content: result.message });

        // Refresh the control panel
        setTimeout(async () => {
            const originalMsg = await interaction.channel.messages.fetch(interaction.message.id).catch(() => null);
            if (originalMsg) {
                const newEmbed = buildControlEmbed();
                await originalMsg.edit({ embeds: [newEmbed], components: buildControlButtons() }).catch(() => {});
            }
        }, 1000);
    }

    // Handle restart main
    else if (action === "ctrl_restart_main") {
        await interaction.editReply({ content: "🔄 Restarting main bot..." });
        await restartMainBot(interaction);
    }

    // Handle refresh
    else if (action === "ctrl_refresh") {
        const newEmbed = buildControlEmbed();
        await interaction.editReply({ content: "🔄 Refreshed!", ephemeral: true });
        await interaction.message.edit({ embeds: [newEmbed], components: buildControlButtons() }).catch(() => {});
    }

    // Handle memory stats
    else if (action === "ctrl_memory") {
        const memStats = {
            rss: (process.memoryUsage().rss / 1024 / 1024).toFixed(2),
            heapTotal: (process.memoryUsage().heapTotal / 1024 / 1024).toFixed(2),
            heapUsed: (process.memoryUsage().heapUsed / 1024 / 1024).toFixed(2),
            external: (process.memoryUsage().external / 1024 / 1024).toFixed(2),
        };

        const managedMem = [];
        for (const [name, proc] of managedProcesses) {
            if (proc.process && proc.pid && name !== 'main') {
                managedMem.push(`> **${name}:** PID ${proc.pid} — running`);
            }
        }

        const memEmbed = new Discord.MessageEmbed()
            .setColor("#5865F2")
            .setTitle("📊 Memory Statistics")
            .addFields(
                { name: "Main Process", value: `> 📦 RSS: \`${memStats.rss} MB\`\n> 🧠 Heap: \`${memStats.heapUsed} MB / ${memStats.heapTotal} MB\`\n> 🔗 External: \`${memStats.external} MB\``, inline: false },
                { name: "Managed Processes", value: managedMem.length ? managedMem.join('\n') : "> No other managed processes running", inline: false },
                { name: "Process Count", value: `> Main: \`${process.pid}\`\n> Managed: \`${managedProcesses.size - 1}\``, inline: true }
            )
            .setTimestamp();

        await interaction.editReply({ embeds: [memEmbed], ephemeral: true });
    }
});

// Simple status command
client.on("messageCreate", async (message) => {
    if (message.author.bot || !message.guild) return;
    if (message.content.trim().toLowerCase() === "!status") {
        if (!owners.includes(message.author.id)) return;

        const statusLines = [];
        for (const script of SCRIPTS_TO_MANAGE) {
            const managed = managedProcesses.get(script.name);
            let status = '❌ stopped';
            let pid = '';

            if (script.name === 'main') {
                status = '✅ running';
                pid = ` (PID: ${process.pid})`;
            } else if (managed && managed.process && !managed.process.killed) {
                status = '✅ running';
                pid = ` (PID: ${managed.pid})`;
            }

            statusLines.push(`> **${script.name}:** ${status}${pid}`);
        }

        const embed = new Discord.MessageEmbed()
            .setColor("#5865F2")
            .setTitle("📊 Bot Status")
            .setDescription(statusLines.join('\n'))
            .addField("Memory", `\`${(process.memoryUsage().heapUsed / 1024 / 1024).toFixed(2)} MB\``, true)
            .addField("Uptime", `\`${formatUptime(process.uptime() * 1000)}\``, true)
            .addField("Node Version", `\`${process.version}\``, true)
            .setTimestamp();

        await message.reply({ embeds: [embed] });
    }
});

