// تحميل إعدادات قناة اللوج عند بدء التشغيل
function loadLogChannelConfig() {
  try {
    const fs = require('fs');
    const path = require('path');
    const LOG_CONFIG_PATH = path.join(__dirname, 'logChannel.json');
    const config = JSON.parse(fs.readFileSync(LOG_CONFIG_PATH, 'utf8'));
    return config.channelId;
  } catch {
    return null;
  }
}

// تحديث متغير DEPOSIT_LOG_CHANNEL_ID في ملف self.js
function updateSelfLogChannel(channelId) {
  const fs = require('fs');
  const path = require('path');
  const selfPath = path.join(__dirname, 'self.js');
  let content = fs.readFileSync(selfPath, 'utf8');

  // تحديث السطر const DEPOSIT_LOG_CHANNEL_ID
  content = content.replace(
    /const DEPOSIT_LOG_CHANNEL_ID = ".*?"/,
    `const DEPOSIT_LOG_CHANNEL_ID = "${channelId}"`
  );

  fs.writeFileSync(selfPath, content);
}


// ── API لتسوية لعبة الشطرنج وتحديث الرصيد (للاستدعاء من المتصفح) ──
app.post('/api/chess/settle', express.json(), async (req, res) => {
  try {
    const { gameId, result, winner, reason } = req.body;
    console.log(`[chess settle] Game: ${gameId}, result: ${result}, winner: ${winner}, reason: ${reason}`);

    // البحث عن اللعبة في قاعدة البيانات
    const ChessGame = require("./models_games/chessGame");
    const game = await ChessGame.findOne({ gameId });
    if (!game) {
      return res.json({ error: 'Game not found' });
    }

    // إذا كانت اللعبة قد تمت تسويتها بالفعل
    if (game.status === 'finished' && game.settled) {
      return res.json({ error: 'Game already settled' });
    }

    const betAmount = game.betAmount || 0;
    if (betAmount <= 0) {
      game.settled = true;
      await game.save();
      return res.json({ message: 'No bet amount, no coins transferred' });
    }

    const p1Id = game.player1;
    const p2Id = game.player2;
    const p1Tag = game.player1Username;
    const p2Tag = game.player2Username;

    let winnerId = null, loserId = null;

    if (winner === 'white') {
      winnerId = p1Id;
      loserId = p2Id;
    } else if (winner === 'black') {
      winnerId = p2Id;
      loserId = p1Id;
    } else if (result === 'draw') {
      // تعادل — فقط إعادة تعيين حالة اللعب
      let p1data = await db.findOne({ id: p1Id });
      let p2data = await db.findOne({ id: p2Id });
      if (!p1data) p1data = await db.create({ id: p1Id, coins: 0, status_playing: "no" });
      if (!p2data) p2data = await db.create({ id: p2Id, coins: 0, status_playing: "no" });

      p1data.status_playing = "no";
      p2data.status_playing = "no";
      await p1data.save();
      await p2data.save();

      game.settled = true;
      await game.save();

      return res.json({ message: `تعادل! لا تغيير في الرصيد.` });
    }

    if (!winnerId) {
      return res.json({ error: 'Could not determine winner' });
    }

    // حساب الضريبة والجائزة
    const tax = await calcTax(winnerId, betAmount);
    const prize = betAmount - tax;

    // تحديث الرصيد
    let winnerData = await db.findOne({ id: winnerId });
    if (!winnerData) winnerData = await db.create({ id: winnerId, coins: 0, status_playing: "no" });

    let loserData = await db.findOne({ id: loserId });
    if (!loserData) loserData = await db.create({ id: loserId, coins: 0, status_playing: "no" });

    winnerData.coins = parseInt(winnerData.coins) + prize;
    loserData.coins = Math.max(0, parseInt(loserData.coins) - betAmount);
    loserData.cashback = (parseInt(loserData.cashback) || 0) + Math.floor(betAmount * 0.02);

    winnerData.status_playing = "no";
    loserData.status_playing = "no";

    await winnerData.save();
    await loserData.save();

    // تحديث إحصائيات المافيا
    if (typeof mafiaOnWin === 'function') await mafiaOnWin(winnerId, betAmount).catch(() => {});
    if (typeof mafiaOnLoss === 'function') await mafiaOnLoss(loserId, betAmount).catch(() => {});

    game.settled = true;
    await game.save();

    // إرسال إشعار لقناة السجل
    const logCh = client.channels.cache.get(SERVER_SETTINGS.channels.allBetsLogId);
    if (logCh) {
      const winnerUser = await client.users.fetch(winnerId).catch(() => null);
      const loserUser = await client.users.fetch(loserId).catch(() => null);
      const logEmbed = new Discord.MessageEmbed()
        .setColor("#032943")
        .setTitle("♟️ نتيجة مباراة شطرنج")
        .setDescription(
          `> 🏆 **الفائز:** ${winnerUser ? winnerUser.tag : winnerId}\n` +
          `> 💀 **الخاسر:** ${loserUser ? loserUser.tag : loserId}\n` +
          `> 💰 **الرهان:** \`${betAmount.toLocaleString("en-US")}\`\n` +
          `> 🎁 **الجائزة:** \`${prize.toLocaleString("en-US")}\` (بعد الضريبة)\n` +
          `> 📝 **السبب:** ${reason || 'انتهت اللعبة'}`
        )
        .setTimestamp();
      logCh.send({ embeds: [logEmbed] }).catch(() => {});
    }

    const winnerName = winnerId === p1Id ? p1Tag : p2Tag;
    res.json({ message: `${winnerName} فاز بمبلغ ${prize.toLocaleString("en-US")} عملة!` });

  } catch (err) {
    console.error('[chess settle]', err);
    res.json({ error: err.message });
  }
});
// ─── Rain Command ───────────────────────────────────────────────────────────
const activeRains = new Map(); // msgId → { ownerId, totalAmount, participants: Set, channelId, endTime, timer }

function parseRainAmount(str) {
  const s = str.toLowerCase().trim();
  if (s.endsWith('b')) return Math.floor(parseFloat(s) * 1_000_000_000);
  if (s.endsWith('m')) return Math.floor(parseFloat(s) * 1_000_000);
  if (s.endsWith('k')) return Math.floor(parseFloat(s) * 1_000);
  const n = parseInt(s);
  return isNaN(n) ? null : n;
}

function parseRainDuration(str) {
  const s = str.toLowerCase().trim();
  if (s.endsWith('h')) return Math.floor(parseFloat(s) * 3600 * 1000);
  if (s.endsWith('m')) return Math.floor(parseFloat(s) * 60 * 1000);
  if (s.endsWith('s')) return Math.floor(parseFloat(s) * 1000);
  const n = parseInt(s);
  return isNaN(n) ? null : n * 1000;
}

function fmtRainDuration(ms) {
  const totalSec = Math.floor(ms / 1000);
  const h = Math.floor(totalSec / 3600);
  const m = Math.floor((totalSec % 3600) / 60);
  const s = totalSec % 60;
  if (h > 0) return `${h}h ${m}m`;
  if (m > 0) return s > 0 ? `${m}m ${s}s` : `${m}m`;
  return `${s}s`;
}

function buildRainEmbed(totalAmount, participants, perPerson, endsAt, ended) {
  const fmt = (v) => Number(v).toLocaleString("en-US");
  const embed = new Discord.MessageEmbed()
    .setColor(ended ? '#2ECC71' : '#3498DB')
    .setTitle(ended ? '🌧️ Rain Event — انتهى!' : '🌧️ Rain Event')
    .setDescription(
      ended
        ? `> ✅ انتهى المطر! تم توزيع الكوينز على المشاركين.`
        : `> 💧 هناك مطر كوينز قادم! اضغط الزر أدناه للانضمام والحصول على نصيبك.\n> ⏰ ينتهي <t:${Math.floor(endsAt / 1000)}:R>`
    )
    .addFields(
      { name: '💰 إجمالي المبلغ', value: `\`${fmt(totalAmount)}\` كوين`, inline: true },
      { name: '👥 المشاركون', value: `\`${participants}\` شخص`, inline: true },
      { name: '🎁 نصيب كل شخص', value: participants > 0 ? `\`${fmt(perPerson)}\` كوين` : `\`—\``, inline: true },
    )
    .setFooter({ text: 'Diamond Casino • Rain Event' })
    .setTimestamp();
  return embed;
}

client.on("messageCreate", async (message) => {
  if (message.author.bot || !message.guild) return;
  if (!message.content.toLowerCase().startsWith("!rain")) return;
  if (!owners.includes(message.author.id))
    return message.reply({ content: "> ❌ هذا الأمر مخصص للمالك فقط!" });

  const args = message.content.trim().split(/\s+/);
  if (args.length < 3) {
    return message.reply({
      content: "> ❌ **الاستخدام الصحيح:** `!rain <المبلغ> <المدة>`\n> **مثال:** `!rain 30m 1m`\n> يدعم: `k` ألف — `m` مليون — `b` مليار\n> المدة: `s` ثانية — `m` دقيقة — `h` ساعة"
    });
  }

  const totalAmount = parseRainAmount(args[1]);
  const durationMs  = parseRainDuration(args[2]);

  if (!totalAmount || totalAmount <= 0)
    return message.reply({ content: "> ❌ المبلغ غير صحيح. مثال: `30m`, `500k`, `1b`" });
  if (!durationMs || durationMs < 5000)
    return message.reply({ content: "> ❌ المدة غير صحيحة أو قصيرة جداً (أدنى 5 ثوانٍ). مثال: `1m`, `30s`, `2h`" });

  // Deduct from owner balance
  let ownerData = await db.findOne({ id: message.author.id });
  if (!ownerData) ownerData = await db.create({ id: message.author.id, coins: 0, status_playing: "no" });
  if (parseInt(ownerData.coins) < totalAmount)
    return message.reply({ content: `> ❌ رصيدك غير كافٍ! رصيدك الحالي: \`${parseInt(ownerData.coins).toLocaleString("en-US")}\`` });

  ownerData.coins = parseInt(ownerData.coins) - totalAmount;
  await ownerData.save();

  const endsAt = Date.now() + durationMs;
  const participants = new Set();
  const perPerson = 0;

  const embed = buildRainEmbed(totalAmount, 0, 0, endsAt, false);
  const joinBtn = new Discord.MessageActionRow().addComponents(
    new Discord.MessageButton()
      .setCustomId(`joinrain_PLACEHOLDER`)
      .setLabel(`🌧️ انضم للمطر`)
      .setStyle("PRIMARY")
  );

  const sentMsg = await message.channel.send({ embeds: [embed], components: [joinBtn] });

  // Fix button with actual message ID
  const realBtn = new Discord.MessageActionRow().addComponents(
    new Discord.MessageButton()
      .setCustomId(`joinrain_${sentMsg.id}`)
      .setLabel(`🌧️ انضم للمطر`)
      .setStyle("PRIMARY")
  );
  await sentMsg.edit({ components: [realBtn] });

  // Register active rain
  const timer = setTimeout(async () => {
    const rain = activeRains.get(sentMsg.id);
    if (!rain) return;
    activeRains.delete(sentMsg.id);

    const pList = [...rain.participants];
    const count = pList.length;

    if (count === 0) {
      // Refund owner
      let od = await db.findOne({ id: rain.ownerId });
      if (!od) od = await db.create({ id: rain.ownerId, coins: 0, status_playing: "no" });
      od.coins = parseInt(od.coins) + rain.totalAmount;
      await od.save();

      const endEmbed = buildRainEmbed(rain.totalAmount, 0, 0, rain.endsAt, true);
      endEmbed.setDescription('> 😔 لم ينضم أحد! تم استرداد المبلغ للمالك.');
      return sentMsg.edit({ embeds: [endEmbed], components: [] }).catch(() => {});
    }

    const share = Math.floor(rain.totalAmount / count);
    const remainder = rain.totalAmount - (share * count);

    // Distribute to each participant
    for (const uid of pList) {
      let ud = await db.findOne({ id: uid });
      if (!ud) ud = await db.create({ id: uid, coins: 0, status_playing: "no" });
      ud.coins = parseInt(ud.coins) + share;
      await ud.save();
    }
    // Give remainder back to owner
    if (remainder > 0) {
      let od = await db.findOne({ id: rain.ownerId });
      if (!od) od = await db.create({ id: rain.ownerId, coins: 0, status_playing: "no" });
      od.coins = parseInt(od.coins) + remainder;
      await od.save();
    }

    const winnerMentions = pList.map(id => `<@${id}>`).join(', ');
    const endEmbed = buildRainEmbed(rain.totalAmount, count, share, rain.endsAt, true);
    endEmbed.addFields({ name: '🏆 الفائزون', value: winnerMentions.length > 1024 ? `${winnerMentions.slice(0, 1020)}...` : winnerMentions });

    sentMsg.edit({ embeds: [endEmbed], components: [] }).catch(() => {});
    sentMsg.channel.send({
      content: `> 🌧️ **انتهى المطر!** حصل كل من:\n${winnerMentions}\n> على **${share.toLocaleString("en-US")}** كوين! 🎉`
    }).catch(() => {});
  }, durationMs);

  activeRains.set(sentMsg.id, {
    ownerId: message.author.id,
    totalAmount,
    participants,
    endsAt,
    timer
  });
});

// ── Join Rain Button ─────────────────────────────────────────────────────────
client.on("interactionCreate", async (interaction) => {
  if (!interaction.isButton()) return;
  if (!interaction.customId.startsWith("joinrain_")) return;

  const msgId = interaction.customId.replace("joinrain_", "");
  const rain = activeRains.get(msgId);

  if (!rain) return interaction.reply({ content: "> ❌ هذا المطر انتهى أو لم يعد متاحاً.", ephemeral: true });
  if (rain.ownerId === interaction.user.id) return interaction.reply({ content: "> ❌ المالك لا يمكنه الانضمام للمطر.", ephemeral: true });
  if (rain.participants.has(interaction.user.id)) return interaction.reply({ content: "> ✅ أنت منضم بالفعل! انتظر انتهاء المطر.", ephemeral: true });

  rain.participants.add(interaction.user.id);
  const count = rain.participants.size;
  const share = Math.floor(rain.totalAmount / count);

  const updatedEmbed = buildRainEmbed(rain.totalAmount, count, share, rain.endsAt, false);
  await interaction.message.edit({ embeds: [updatedEmbed] }).catch(() => {});

  return interaction.reply({ content: `> 🌧️ انضممت للمطر! ستحصل على نصيبك عند انتهاء العداد.`, ephemeral: true });
});

const GIFEncoder = require('gifencoder');

client.on("messageCreate", async (message) => {
    if (!message.guild || message.author.bot) return;

    const trig = message.content.trim().toLowerCase();
    if (trig !== "pass" && trig !== "باس") return;

    const target = message.mentions.users.first() || message.author;
    const member = message.guild.members.cache.get(target.id) || await message.guild.members.fetch(target.id).catch(() => null);

    const waitMessage = await message.reply("⏳ Syncing live Discord assets, claiming rewards, and constructing premium interface...");

    try {
        // ── 1. DATABASE FETCH & PROGRESSION ──
        const mp = await mafiaGetOrCreate(target.id);
        const udb = await db.findOne({ id: target.id }) || {};

        const totalXP = mp.totalEarned || 0; 
        const maxLevel = 100;

        const xpPerLevel = 5000000;
        let lvl = Math.floor(totalXP / xpPerLevel);
        if (lvl > maxLevel) lvl = maxLevel;

        const currentLevelXPBase = lvl * xpPerLevel;
        const xpRequiredForNextLevel = xpPerLevel;
        const userCurrentXPInLevel = totalXP - currentLevelXPBase;

        const xpPct = Math.min(Math.max(userCurrentXPInLevel / xpRequiredForNextLevel, 0), 1);

        const premiumRoleId = "1332070217685401611";
        const isPremiumUser = member ? member.roles.cache.has(premiumRoleId) : false;

        const freeRewards = ["250K", "500K", "750K", "1M", "1.5M"];
        const premiumRewards = ["1M", "2.5M", "5M", "10M", "BackNumber"];

        // ── 2. AUTO-CLAIM ENGINE ──
        let claimedFree = udb.claimedFreeRewards || [];
        let claimedPremium = udb.claimedPremiumRewards || [];
        let dbUpdates = {};
        let dbNeedsUpdate = false;

        freeRewards.forEach((_, index) => {
            const tierLvl = index + 1;
            if (lvl >= tierLvl && !claimedFree.includes(tierLvl)) {
                claimedFree.push(tierLvl);
                dbNeedsUpdate = true;
            }
        });

        if (isPremiumUser) {
            premiumRewards.forEach((_, index) => {
                const tierLvl = index + 1;
                if (lvl >= tierLvl && !claimedPremium.includes(tierLvl)) {
                    claimedPremium.push(tierLvl);
                    dbNeedsUpdate = true;

                    if (tierLvl === 5) {
                        const currentBackNumbers = parseInt(udb.backNumberCount) || 0;
                        dbUpdates.backNumberCount = currentBackNumbers + 1; 
                    }
                }
            });
        }

        if (dbNeedsUpdate) {
            dbUpdates.claimedFreeRewards = claimedFree;
            dbUpdates.claimedPremiumRewards = claimedPremium;
            await db.updateOne({ id: target.id }, { $set: dbUpdates }, { upsert: true });
        }

        // ── 3. CANVAS SETUP ──
        const W = 1200, H = 750; 
        const canvas = createCanvas(W, H);
        const ctx = canvas.getContext("2d");

        const encoder = new GIFEncoder(W, H);
        const outPath = `./output/pass-${target.id}.gif`;
        if (!fs.existsSync("./output")) fs.mkdirSync("./output");

        const writeStream = fs.createWriteStream(outPath);
        encoder.createReadStream().pipe(writeStream);

        encoder.start();
        encoder.setRepeat(0);   
        encoder.setDelay(55); // Smooth rendering frame speed   
        encoder.setQuality(8); // High quality crisp output compression

        // ── 4. ADVANCED DISCORD AVATAR & DECORATION LOADING ──
        let avatarImg = null;
        let decorationImg = null;

        try {
            // Fetch High-Res Avatar URL explicitly forcing PNG formatting
            const avatarURL = target.displayAvatarURL({ format: 'png', dynamic: false, size: 256 });
            avatarImg = await loadImage(avatarURL);

            // Fetch Live Custom Avatar Decoration Effects via Discord CDN asset map fallback
            let decoURL = null;
            if (target.avatarDecorationURL) {
                decoURL = target.avatarDecorationURL({ format: 'png', size: 256 });
            } else if (target.avatarDecoration) {
                // Manual fallback construction via API payload asset hash
                decoURL = `https://cdn.discordapp.com/avatar-decorations/${target.id}/${target.avatarDecoration.asset}.png?size=256`;
            }

            if (decoURL) {
                decorationImg = await loadImage(decoURL);
            }
        } catch (e) {
            console.log("Profile graphics asset loading skipped/failed: ", e.message);
        }

        // Generate Ambient Dynamic Starfield Matrix Background Particles
        const particles = [];
        for (let i = 0; i < 30; i++) {
            particles.push({
                x: Math.random() * W, y: Math.random() * H,
                size: Math.random() * 2.2 + 1, speedY: Math.random() * 0.9 + 0.3,
                alpha: Math.random() * 0.6 + 0.1
            });
        }

        const totalFrames = 15;

        // ── 5. RENDER SYSTEM LOOP ──
        for (let f = 0; f < totalFrames; f++) {
            ctx.clearRect(0, 0, W, H);

            // Dark space backdrop
            ctx.fillStyle = "#040108";
            ctx.fillRect(0, 0, W, H);

            // Neon Radial Glow
            const pulse = Math.sin((f / totalFrames) * Math.PI * 2) * 18;
            const glow = ctx.createRadialGradient(W/2, H/2, 40, W/2, H/2, 620 + pulse);
            glow.addColorStop(0, "rgba(124, 77, 255, 0.15)");
            glow.addColorStop(1, "transparent");
            ctx.fillStyle = glow;
            ctx.fillRect(0, 0, W, H);

            // Cyber Grid Lines
            ctx.strokeStyle = "rgba(142, 68, 173, 0.02)";
            ctx.lineWidth = 1;
            const lineOffset = (f / totalFrames) * 40; 
            for (let i = -H - 40; i < W; i += 40) {
                ctx.beginPath(); ctx.moveTo(i + lineOffset, 0); ctx.lineTo(i + H + lineOffset, H); ctx.stroke();
            }

            // Fall Particles
            particles.forEach(p => {
                let currentY = p.y + (p.speedY * f);
                if (currentY > H) currentY -= H;
                ctx.fillStyle = `rgba(224, 64, 251, ${p.alpha})`;
                ctx.beginPath(); ctx.arc(p.x, currentY, p.size, 0, Math.PI * 2); ctx.fill();
            });

            // ── TOP IDENTITY LAYOUT HEADER ──
            ctx.textAlign = "left";
            ctx.font = "bold 38px 'Segoe UI', Arial, sans-serif";
            ctx.fillStyle = "#ffffff";
            ctx.fillText("DIAMOND ROYAL PASS", 50, 75);

            ctx.font = "bold 13px 'Segoe UI', Arial, sans-serif";
            ctx.fillStyle = "rgba(255, 255, 255, 0.35)"; 
            ctx.fillText("LIVE SEASONAL PROGRESSION ENGINE", 50, 100);

            // Right-aligned status badges
            ctx.textAlign = "right";
            ctx.font = "bold 22px 'Segoe UI', Arial, sans-serif";
            ctx.fillStyle = isPremiumUser ? "#e040fb" : "#b388ff";
            ctx.fillText(target.username.toUpperCase(), W - 50, 75);

            ctx.font = "bold 13px 'Segoe UI', Arial, sans-serif";
            ctx.fillStyle = isPremiumUser ? "#e040fb" : "#7c4dff";
            ctx.fillText(isPremiumUser ? "✦ PASS+ ELITE MEMBER ACTIVE" : "⚝ STANDARD ACCOUNT PROFILE", W - 50, 100);

            // ── 🔘 ULTRA STYLED CENTER AVATAR LEVEL RING ──
            const circleX = W / 2, circleY = 125, radius = 54;

            // Matte background track
            ctx.strokeStyle = "#0e051d"; ctx.lineWidth = 9;
            ctx.beginPath(); ctx.arc(circleX, circleY, radius, 0, Math.PI * 2); ctx.stroke();

            // Glowing Arc Fill Progress Line
            ctx.strokeStyle = "#d500f9"; ctx.lineWidth = 9; ctx.lineCap = "round";
            ctx.shadowBlur = 12; ctx.shadowColor = "#d500f9";
            ctx.beginPath(); ctx.arc(circleX, circleY, radius, -Math.PI / 2, (-Math.PI / 2) + (Math.PI * 2 * xpPct)); ctx.stroke();
            ctx.shadowBlur = 0; // Clear raw glow immediately

            // Clip & Draw Main User Profile Photo inside ring safely
            if (avatarImg) {
                ctx.save();
                ctx.beginPath(); ctx.arc(circleX, circleY, radius - 8, 0, Math.PI * 2); ctx.clip();
                ctx.drawImage(avatarImg, circleX - (radius - 8), circleY - (radius - 8), (radius - 8) * 2, (radius - 8) * 2);
                ctx.restore();
            } else {
                // Modern text fallback if avatar failed loading entirely
                ctx.save();
                ctx.fillStyle = "#1e113a";
                ctx.beginPath(); ctx.arc(circleX, circleY, radius - 8, 0, Math.PI * 2); ctx.fill();
                ctx.textAlign = "center"; ctx.font = "bold 20px Arial"; ctx.fillStyle = "#ffffff";
                ctx.fillText(target.username.slice(0, 2).toUpperCase(), circleX, circleY + 7);
                ctx.restore();
            }

            // Draw Profile Custom Avatar Decoration Effects Overlaying the Frame
            if (decorationImg) {
                ctx.save();
                // Custom scale matching accurate Discord presentation offsets
                const decoSize = radius * 2.38;
                ctx.drawImage(decorationImg, circleX - (decoSize / 2), circleY - (decoSize / 2) + 1.5, decoSize, decoSize);
                ctx.restore();
            }

            // Centered Level Badge Block underneath the Avatar Frame
            ctx.save();
            ctx.fillStyle = "#d500f9";
            ctx.beginPath(); ctx.roundRect(circleX - 35, circleY + radius - 4, 70, 20, 6); ctx.fill();

            ctx.textAlign = "center";
            ctx.font = "bold 12px 'Segoe UI', Arial, sans-serif"; ctx.fillStyle = "#ffffff";
            ctx.fillText(`LVL ${lvl}`, circleX, circleY + radius + 10);
            ctx.restore();

            // Total Live EXP Subtitle Track
            ctx.textAlign = "center";
            ctx.font = "bold 12px Arial"; ctx.fillStyle = "rgba(187, 134, 252, 0.75)";
            ctx.fillText(`${Math.floor(userCurrentXPInLevel)} / ${xpRequiredForNextLevel} XP`, circleX, circleY + radius + 34);

            // ── GRID STRUCT REWARD COMPONENT RENDERER ──
            const drawRewardCard = (x, y, itemLvl, amount, claimedList, requiresPremium) => {
                ctx.save();
                const isLevelReached = lvl >= itemLvl;
                const isClaimed = claimedList.includes(itemLvl);
                const isPremiumLocked = requiresPremium && !isPremiumUser;
                const isLocked = !isLevelReached || isPremiumLocked;

                const themeColor = requiresPremium ? "#e040fb" : "#7c4dff";
                const bgGradient = ctx.createLinearGradient(x, y, x, y + 140);

                if (isClaimed) {
                    bgGradient.addColorStop(0, "rgba(46, 204, 113, 0.08)");
                    bgGradient.addColorStop(1, "rgba(0, 0, 0, 0.75)");
                    ctx.strokeStyle = "rgba(46, 204, 113, 0.5)"; 
                } else if (!isLocked) {
                    bgGradient.addColorStop(0, "rgba(156, 39, 176, 0.06)");
                    bgGradient.addColorStop(1, "rgba(0, 0, 0, 0.45)");
                    ctx.strokeStyle = themeColor;
                } else {
                    bgGradient.addColorStop(0, "rgba(10, 5, 18, 0.9)");
                    bgGradient.addColorStop(1, "rgba(2, 1, 4, 0.99)");
                    ctx.strokeStyle = "rgba(255, 255, 255, 0.02)"; 
                }

                ctx.fillStyle = bgGradient;
                ctx.lineWidth = 1.5;
                const cardWidth = 145;
                ctx.beginPath(); ctx.roundRect(x, y, cardWidth, 135, 12); ctx.fill(); ctx.stroke();

                ctx.textAlign = "center";
                ctx.font = "bold 12px 'Segoe UI', Arial, sans-serif";
                ctx.fillStyle = isClaimed ? "#2ecc71" : (!isLocked ? "#ffffff" : "rgba(255,255,255,0.2)");
                ctx.fillText(`TIER 0${itemLvl}`, x + (cardWidth/2), y + 25);

                // Check Custom Icon render types
                if (requiresPremium && itemLvl === 5) {
                    // Custom Ticket Graphic Layout with back-arrow routing
                    ctx.save();
                    ctx.translate(x + (cardWidth / 2), y + 54);
                    ctx.fillStyle = isLocked ? "rgba(255,255,255,0.02)" : "#e040fb";
                    ctx.strokeStyle = isLocked ? "rgba(255,255,255,0.02)" : "#ffffff";
                    ctx.lineWidth = 2;
                    ctx.rotate(-0.15); 
                    ctx.beginPath(); ctx.roundRect(-20, -13, 40, 24, 4); ctx.fill(); if (!isLocked) ctx.stroke();
                    ctx.fillStyle = "#040108";
                    ctx.beginPath(); ctx.arc(-20, -1, 3.5, 0, Math.PI * 2); ctx.fill();
                    ctx.beginPath(); ctx.arc(20, -1, 3.5, 0, Math.PI * 2); ctx.fill();

                    if (!isLocked) {
                        ctx.strokeStyle = "#ffffff"; ctx.lineWidth = 2.2; ctx.lineCap = "round"; ctx.lineJoin = "round";
                        ctx.beginPath(); ctx.arc(3, 1, 7, Math.PI * 1.5, Math.PI * 0.5, false); ctx.lineTo(-5, 8); ctx.stroke();
                        ctx.beginPath(); ctx.moveTo(-1, 5); ctx.lineTo(-7, 8); ctx.lineTo(-1, 11); ctx.stroke();
                    }
                    ctx.restore();
                } else {
                    ctx.fillStyle = isLocked ? "rgba(255,255,255,0.02)" : themeColor;
                    for(let i=0; i<3; i++) {
                        ctx.beginPath(); ctx.ellipse(x + (cardWidth/2), y + 58 + (i*4), 20, 6, 0, 0, Math.PI * 2); ctx.fill();
                    }
                }

                ctx.font = "bold 14px Arial";
                ctx.fillStyle = isLocked ? "rgba(255,255,255,0.15)" : "#ffffff";
                ctx.fillText(amount, x + (cardWidth/2), y + 98);

                // Button State Interfaces
                if (isClaimed) {
                    ctx.fillStyle = "rgba(46, 204, 113, 0.1)";
                    ctx.beginPath(); ctx.roundRect(x + 15, y + 110, cardWidth - 30, 16, 4); ctx.fill();
                    ctx.font = "bold 8px Arial"; ctx.fillStyle = "#2ecc71";
                    ctx.fillText("CLAIMED", x + (cardWidth/2), y + 121);
                } else if (isPremiumLocked) {
                    ctx.font = "bold 8px Arial"; ctx.fillStyle = "rgba(239, 83, 80, 0.75)";
                    ctx.fillText("LOCKED", x + (cardWidth/2), y + 121);
                } else {
                    ctx.strokeStyle = "rgba(255,255,255,0.15)";
                    ctx.beginPath(); ctx.arc(x + (cardWidth/2), y + 115, 3.5, 0, Math.PI, true); ctx.stroke();
                    ctx.fillStyle = "rgba(255,255,255,0.08)";
                    ctx.beginPath(); ctx.roundRect(x + (cardWidth/2) - 5, y + 115, 10, 8, 1); ctx.fill();
                }
                ctx.restore();
            };

            // ── 6. FREE PASS HOUSING CONTAINER ──
            const freeY = 275; 
            ctx.fillStyle = "rgba(124, 77, 255, 0.005)";
            ctx.strokeStyle = "rgba(124, 77, 255, 0.04)";
            ctx.beginPath(); ctx.roundRect(50, freeY, 1100, 190, 14); ctx.fill(); ctx.stroke();

            ctx.textAlign = "left";
            ctx.font = "bold 18px 'Segoe UI', Arial, sans-serif"; ctx.fillStyle = "#b388ff";
            ctx.fillText("FREE PROGRESSION TIER", 80, freeY + 45);
            ctx.font = "11px Arial"; ctx.fillStyle = "rgba(179, 136, 255, 0.35)";
            ctx.fillText("Standard tier progression matrix.\nAll available milestone tokens claimed.", 80, freeY + 70);

            freeRewards.forEach((amt, index) => {
                drawRewardCard(310 + (index * 155), freeY + 28, index + 1, amt, claimedFree, false);
            });

            // ── 7. PASS+ ELITE HOUSING CONTAINER ──
            const premiumY = 495; 
            ctx.fillStyle = "rgba(224, 64, 251, 0.005)";
            ctx.strokeStyle = "rgba(224, 64, 251, 0.04)";
            ctx.beginPath(); ctx.roundRect(50, premiumY, 1100, 190, 14); ctx.fill(); ctx.stroke();

            ctx.textAlign = "left";
            ctx.font = "bold 18px 'Segoe UI', Arial, sans-serif"; ctx.fillStyle = "#e040fb";
            ctx.fillText("PASS+ PREMIUM ELITE TIER", 80, premiumY + 45);
            ctx.font = "11px Arial"; ctx.fillStyle = "rgba(224, 64, 251, 0.35)";
            ctx.fillText("Premium elite tier matrix rewards.\nRequires authorized system activation.", 80, premiumY + 70);

            premiumRewards.forEach((amt, index) => {
                drawRewardCard(310 + (index * 155), premiumY + 28, index + 1, amt, claimedPremium, true);
            });

            // Footer Clean Brand Sign
            ctx.textAlign = "center";
            ctx.font = "11px Arial";
            ctx.fillStyle = "rgba(179, 136, 255, 0.08)";
            ctx.fillText("DIAMOND CASINO PLATFORM SYSTEMS © 2026", W / 2, H - 20);

            encoder.addFrame(ctx);
        }

        encoder.finish();

        writeStream.on('finish', async () => {
            await waitMessage.delete().catch(() => null);
            await message.reply({ files: [outPath] });
        });

    } catch (err) {
        console.error(err);
        await waitMessage.delete().catch(() => null);
        await message.reply("❌ An unexpected system exception blocked pass profile asset compilation.");
    }
});

// ─── أمر !كاش — عرض ومطالبة الكاش باك ────────────────────────────────────
client.on("messageCreate", async (message) => {
  if (message.author.bot || !message.guild) return;
  const trig = message.content.trim().toLowerCase();
  if (trig !== "كاش" && trig !== "cash") return;

  const userData = await db.findOne({ id: message.author.id }).catch(() => null);
  const cashback = parseInt(userData?.cashback) || 0;

  const embed = new Discord.MessageEmbed()
    .setColor("#F0B429")
    .setTitle("💰 كاش باك")
    .setDescription(
      `> رصيد الكاش باك الخاص بك: **\`${cashback.toLocaleString("en-US")}\`** عملة\n` +
      `> تحصل على **2%** من كل رهان تخسره كاش باك.\n` +
      (cashback > 0 ? `> اضغط الزر أدناه لاستلام رصيدك!` : `> لا يوجد رصيد كاش باك متاح حالياً.`)
    )
    .setFooter("Diamond Casino — Cash Back System");

  const row = new MessageActionRow().addComponents(
    new MessageButton()
      .setCustomId(`cashclaim_${message.author.id}`)
      .setLabel("استلام الكاش باك")
      .setStyle("SUCCESS")
      .setEmoji("💰")
      .setDisabled(cashback === 0)
  );

  await message.reply({ embeds: [embed], components: [row] });
});

// ─── معالج زر استلام الكاش باك ────────────────────────────────────────────
client.on("interactionCreate", async (interaction) => {
  if (!interaction.isButton()) return;
  if (!interaction.customId.startsWith("cashclaim_")) return;

  const ownerId = interaction.customId.replace("cashclaim_", "");
  if (interaction.user.id !== ownerId)
    return interaction.reply({ content: "> ❌ هذا الزر ليس لك!", ephemeral: true });

  try {
    await interaction.deferReply({ ephemeral: true });
    const userData = await db.findOne({ id: interaction.user.id }).catch(() => null);
    const cashback = parseInt(userData?.cashback) || 0;
    if (!userData || cashback === 0)
      return interaction.editReply({ content: "> ❌ لا يوجد رصيد كاش باك لاستلامه!" });

    userData.coins = (parseInt(userData.coins) || 0) + cashback;
    userData.cashback = 0;
    await userData.save();

    return interaction.editReply({
      content: `> ✅ **تم استلام الكاش باك!**\n> 💰 **المبلغ المضاف:** \`${cashback.toLocaleString("en-US")}\`\n> 💵 **رصيدك الجديد:** \`${userData.coins.toLocaleString("en-US")}\``
    });
  } catch (err) {
    console.error(err);
    return interaction.editReply({ content: "> ❌ حدث خطأ أثناء استلام الكاش باك." });
  }
});

